// مولّدة آلياً بواسطة scripts/split-fatwas.mjs — لا تُعدَّل يدوياً.
export default [{"id":133,"question":"أحيانًا أذهب إلى صلاة الفجر ولا أُوقظ الأولاد؛ لتأخُّرٍ أو ما شابه ذلك، فما حكمه؟","title":"حكم من لا يوقظ أولاده لصلاة الفجر","answer":"الجواب: الواجب توقيت الساعة على وقت مبكر حتى تُوقظهم وتُعينهم على طاعة الله، يجب عليك وجوبًا، عليك أن تأمرهم بالصلاة لسبع، وتضربهم عليها لعشرٍ، وعليك أن تبكِّر حتى تُوقظهم، فإذا غُلبت على ذلك بأن ضاق الوقتُ فإذا رجعت تُوقظهم حتى يصلوا، وتتوب إلى الله مما قصرت فيه، ولا تغفل عنهم حتى يصلوا في الوقت. ولكن عليك أن تتقدم بالوقت بتوقيت الساعة حتى تتمكن من أداء صلاتك، ومن وضوئك، ومن غسلك إن كان عليك غسلٌ، ومن إيقاظهم قبل وقت الصلاة؛ حتى لا يضيق عليك الوقت.","link":"https://binbaz.org.sa/fatwas/3660/حكم-من-لا-يوقظ-اولاده-لصلاة-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0122.mp3","categories":["تربية الأولاد"]},{"id":316,"question":"هل يجوز ضرب الأطفال لتأديبهم على الوجه أو باستخدام الكيّ؟","title":"حكم ضرب أو كي الأطفال للتربية والتأديب","answer":"الجواب: الشيخ: يجب تأديب الأطفال، ما هو يجوز، يجب ولو كانوا أيتامًا، حتى الأيتام يُؤَدَّبون إذا أخطأوا، يُؤَدَّب مثلما قال النبيُّ ﷺ: مُروا أولادكم بالصلاة لسبعٍ، واضربوهم عليها لعشرٍ، فإذا تخلَّف الولد أو البنت عن الصلاة بعد العشر يُضرب، وإذا كان سبَّابًا شتَّامًا يُضرب ويُؤَدَّب، إذا كان ما نفع فيه الكلام، وإذا كان يُخالف أهله في أشياء، يضرُّ أهله، لا بأس أن يُؤَدِّبوه حتى يستقيم، سواء ذكرًا أو أنثى، يتيمًا أو غير يتيمٍ، إن كان نفع الكلام فالحمد لله، وإذا ما نفع الكلام تُؤَدِّبه أمه، يُؤدبه أبوه، يُؤدبه أخوه الكبير حتى يستقيم.\nإذا تُرِكَ على حاله السَّيئة نشأ على ذلك، وصار ضررًا على المجتمع، ولكن متى قام عليه أبوه وأمه وإخوته الكبار ووجَّهوه وعلَّموه ومنعوه مما لا ينبغي: من كونه سبَّابًا، كذَّابًا، أو ما يُصلي بعد بلوغ العشر، أو ما أشبه ذلك؛ فإنه يُؤَدَّب حتى يرتدع إذا كان الكلام ما نفع فيه ولا أثَّر.\nبعض الناس يقول: اليتيم ما يُقال له شيءٌ، لا، هذا غلطٌ، إذا تركت اليتيم على حاله ساءت أخلاقُه، وساءت أعماله، ونشأ على شرٍّ، فليس هذا من مصلحته، بل على ولي اليتيم أن يُؤَدِّبه إذا ما نفع فيه الكلام بالضرب، لكن ما يضرب الوجه، يضرب في غير الوجه، في محلات مثل: الفخذ، مثل: الظهر، الكتف، في محلات غير خطيرةٍ، ولا يضرب الوجه أبدًا، النبي نهى عن ضرب الوجه، ولا يضرب المحلات الخطيرة –المقاتل- ولكن يضربه في المحال المُحتملة، مثل: إليته، فخذه، ظهره، شيء خفيف يحصل به الردع.","link":"https://binbaz.org.sa/fatwas/4343/حكم-ضرب-او-كي-الاطفال-للتربية-والتاديب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0367.mp3","categories":["تربية الأولاد"]},{"id":767,"question":"فضيلة الشيخ، إني أحبُّك حبًّا شديدًا، وأكاد أبكي إذا سمعتُ كلامك، فضيلة الشيخ، إنَّ لي أولادًا قد آذوني بصلاة الفجر وغيرها، فهم لا يُصلون، فما أفعل معهم؟ وقد جاهدتُهم كثيرًا، ما الحكم الشَّرعي في ذلك؟ أفيدونا أثابكم الله.","title":"ما حكم الشرع في الأولاد الذين لا يصلون؟","answer":"الجواب: أحبَّك الله الذي أحببتنا له، وأسأل الله أن يجعلنا وإيَّاكم مُتحابين بجلاله، يقول عليه الصلاة والسلام: يقول الله يوم القيامة: أين المتحابُّون بجلالي؟ اليوم أُظلُّهم في ظلِّي يوم لا ظلَّ إلا ظلِّي، ويقول عليه الصلاة والسلام: يقول الله : وجبت محبَّتي للمُتحابين فيَّ، والمتباذلين فيَّ، والمتجالسين فيَّ، والمتزاورين فيَّ، هذا كله مما يُحبُّه الله ، ومن أسباب محبَّة الله للعبد.\nفينبغي للمؤمن أن يكون يُحبّ في الله، ويبغض في الله، ويُوالي في الله، ويُعادي في الله، هكذا المؤمن.\nويقول ﷺ: سبعةٌ يُظلّهم الله في ظلِّه يوم لا ظلَّ إلا ظلّه: إمام عادل، وشابٌّ نشأ في عبادة الله، ورجلٌ قلبه مُعلَّقٌ بالمساجد يعني: كلما خرج من المسجد قلبه مُعلَّقٌ به حتى يُؤدي الصلاة الأخرى، ورجلان تحابَّا في الله، اجتمعا على ذلك، وتفرَّقا عليه، والخامس: رجل دعته امرأةٌ ذات منصبٍ وجمالٍ أي: دعته إلى الزنا فقال: إني أخاف الله، وفي معنى ذلك: امرأة دعاها رجلٌ للزنا فقالت: إني أخاف الله، فهي من السبعة الذين يُظلّهم الله في ظلِّه يوم لا ظلَّ إلا ظله، والسادس: رجل تصدَّق بصدقةٍ فأخفاها، حتى لا تعلم شمالُه ما تُنفق يمينُه من حرصه على الإخلاص، والسابع: رجل ذكر الله خاليًا ما عنده أحدٌ، خاليًا في غرفته، أو في منزله، أو في أي مكانٍ، ففاضت عيناه خوفًا من الله، وتعظيمًا له، هؤلاء السبعة الذين يُظلّهم الله في ظلِّه.\nأما أولادك يا أخي الذين يعصونك ولا يُصلون فعليك بالعصا، اضربهم، يقول النبيُّ ﷺ: مروا أولادكم بالصلاة لسبعٍ، واضربوهم عليها لعشرٍ، كيف إذا بلغوا؟ إذا بلغ ولم يُصلِّ يُقتل، يُرفع أمره إلى ولي الأمر ويُقتل، الذي يبلغ الحلم ولا يُصلي يُرفع إلى ولاة الأمور -إلى المحكمة والإمارة- حتى يُقتل إن لم يستجب ولم يستقم، وإذا كان دون البلوغ وقد بلغ العشر يُضْرَب، فإذا كنتَ ما تستطيع ضربه ارفع أمره إلى الهيئة، إلى المحكمة، إلى أمير بلدك، حتى يقوموا عليه، وإذا كنتَ تستطيع إبعاده أبعده، قل له: لا تأتِ إلى بيتي مرة واحدة، لا تقربني، ولا أعرفك. إذا صدقتَ في هذا نجوتَ من شرِّهم، أما التَّساهل معهم فما ينفع، إن كنت تستطيع الضرب اضربهم حتى يستقيموا، ارفع أمرهم إلى ولاة الأمور: إلى الحسبة، إلى المحكمة، إلى الإمارة، إن كانت تنفع، فإن لم تستطع فأبعدهم عن بيتك، لا يجلسون في بيتك بالكلية، يروحون حتى يهديهم الله، أو النار أمامهم.\nس: ادعوا لهم بالهداية.\nالشيخ: نسأل الله لهم الهداية، نسأل الله لنا ولهم الهداية، ولكل مسلم، وهذا ما هو بخاصٍّ بك، هذا الكلام أقوله للحاضرين جميعًا، ولكل مَن بلغه هذا الكلام، نصيحتي للجميع ولكل مَن بلغه هذا الكلام من رجلٍ أو امرأةٍ: الجد في الأولاد، والصدق في الأولاد، إما أن يستقيموا، أو يبعدوا، وإلا يرفع أمرهم إلى ولاة الأمور، أما أن يُتركوا لا يُصلون فهذا منكرٌ عظيمٌ، وكفرٌ ظاهرٌ -نعوذ بالله.","link":"https://binbaz.org.sa/fatwas/20702/ما-حكم-الشرع-في-الاولاد-الذين-لا-يصلون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0598ما حكم الشرع في الأولاد الذين لا يصلون؟ ابن باز فتاوى المحاضرات.mp3","categories":["حكم الصلاة وأهميتها","تربية الأولاد"]},{"id":1164,"question":"إنَّ أبي وبعض جماعتنا يمنعونني من الذهاب مع الشباب، مع أنهم شباب طيبون، فهل أُطيعه أم أعصيه، مع أنني إذا منعني من الذهاب معهم تتغير حالي، ونرجع إلى الفساد والمعصية؟ أفيدونا جزاكم الله خيرًا.","title":"ما حكم من أمره والداه بترك صحبة الأخيار؟","answer":"الجواب:\nأما مَن أمرك بأن تترك صحبة الأخيار فليس عليك طاعته، يقول النبيُّ ﷺ: إنما الطاعة في المعروف، لكن إذا كان الآمرُ الوالد أو الوالدة فعليك بالحكمة والكلام الطيب، ولا تُظهر المعصية، ولكن تصحب الأخيار من غير علمهما، وتجتهد في صحبة الأخيار من غير علمهما، إذا كان علمُهما يضرّك أو يُسبب ضربهم لك أو نحو ذلك لا تُعلمهما، ولكن لا تترك صحبة الأخيار، والتمس الأخيار في كل وقتٍ أمكنك، واحذر صحبة الأشرار أبدًا، ولا تُطع أحدًا في ذلك أبدًا، لا أبًا، ولا أمًّا، ولا غير ذلك، لكن مع الوالدين تأدَّب بكل طريقةٍ تمكنك، ولو بإخفاء ذلك عليهما في الأوقات المناسبة، حتى لا يكون بينك وبينهما سوءُ تفاهمٍ، وحتى لا تترك صحبة الأخيار، فاتَّقِ الله: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2]، وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4].","link":"https://binbaz.org.sa/fatwas/21219/ما-حكم-من-امره-والداه-بترك-صحبة-الاخيار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1015ما حكم من أمرهُ والديه بترك الصالحين والأخيار؟ابن باز.mp3","categories":["تربية الأولاد","حكم الصلاة وأهميتها"]},{"id":1334,"question":"بعض الناس يقول : هذا الابن صغير؛ إن شاء الله يَكْبُر ويتوب إلى الله أو يَعْقِل أو كذا؟","title":"حكم التهاون في نصح الصغار حتى يكبروا","answer":"الجواب:\nلا، ما يصلح هذا، الواجب جهاده ونصيحته، من يقول له أنه يكبر؟! قد يموت وهو ابن ستة عشر سنة أو سبعة عشر، لا، هذا غلط، هذا تسويف، من طاعة الشيطان. الواجب البِدار بالتوبة ولو هو ابن سبعة عشر أو ثمانية عشر أو ستة عشر، المقصود أنه متى بلغ الحُلُم وَجَب عليه، حتى إنه قبل بلوغ الحُلُم يؤدَّب؛ حتى يعتاد الخير، ما يترك على المعاصي ولو أنه ثمان ولا تسع، ما يُسمح له يشرب الخمر، ولا يسمح له يسب والديه، ولا يُسمح له يعبث بشيء يضر الناس، يُمنع ولو أنه صغير.","link":"https://binbaz.org.sa/fatwas/21425/حكم-التهاون-في-نصح-الصغار-حتى-يكبروا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من يقول هذا الابن صغير إن شاء الله يكبر ويتوب إلى الله.mp3","categories":["تربية الأولاد"]},{"id":1475,"question":"أعمل مدرسًا للعلوم الشرعية في إحدى المدارس، وفي حصة القرآن يتهرّب بعضُ الطلاب من القراءة بحجة أنهم ليسوا على وضوءٍ ولا يستطيعون مسَّ المصحف، مع العلم أننا لو سمحنا لهم بالخروج للوضوء فلن يعودوا إلا بعد انتهاء الحصة، فهل يجوز أن يقرؤوا من المصحف؟","title":"حكم مس الطلّاب المصحف بغير وضوء","answer":"الجواب:\nلا،ــ يلزمهم أن يتوضؤوا للمصحف، وإلا يقرؤوا عن ظهر قلب حتى يَشُوفُهُم حِفْظًا، وإلا يسمحُ لهم أن يذهبوا ويأتوا، والذي لا يأتي يُؤَدَّب.","link":"https://binbaz.org.sa/fatwas/21573/حكم-مس-الطلاب-المصحف-بغير-وضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في تربية الطلاب وقراءتهم للقرآن بغير وضوء.mp3","categories":["القرآن وعلومه","تربية الأولاد"]},{"id":1582,"question":"هذا رجل ابتُلِيَ بأن أبناءه لا يخرجون إلى بيت الله ، يصلون في بيوتهم، وتعب معهم في توجيههم ونصحهم حتى وصل إلى ضربهم، فما الواجب في حقِّه؟","title":"حكم تأديب الأبناء لتقصيرهم في الصلاة","answer":"الجواب:\nهذا هو الواجب: التأديب، وإذا عجز يرفعهم إلى الهيئة، أو الإمارة إذا كان في بلده إمارة، أو الهيئة أقوى منها.\nس: وابتُلِيَ أحدُهم بأن ابنته لا تُصلي البتة؟\nج: كذلك يُؤدِّبها حتى تستقيم، ومع الأدب تستقيم إن شاء الله.","link":"https://binbaz.org.sa/fatwas/21685/حكم-تاديب-الابناء-لتقصيرهم-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/وجوب تأديب الأبناء عند تقصيرهم في الصلاة.mp3","categories":["تربية الأولاد","حكم الصلاة وأهميتها"]},{"id":1587,"question":"رجلٌ يذهب مع جماعة التبليغ، وأولاده لا يُصلُّون، فيقول: ماذا أعمل فيهم قد نصحتهم مرةً ومرتين؟","title":"حكم مَنْ يدعو الناس وأولاده لا يُصلُّون","answer":"الجواب:\nيجلس مع أولاده يُجاهدهم، ولا يذهب يُعلِّم الناسَ ويترك مَن كان تحت يده، مَن كان تحت يده أبْدَى، فيقوم عليهم ويستعين بالله ثم بالهيئة عليهم، فالهيئة ما جُعِلَتْ إلا لهذا.\nس: خروجه أحسن الله إليك؟\nج: إذا كانت الجماعة التي معه أهل سنة ما في بأس إذا كان خروجه لا يترتب عليه شرٌّ، إذا كان ما يُضَيِّع ما يجب عليه، أما هذا فلا يخرج، يجاهد الذين عنده.\nس: بعضهم يقول: أنا مجنون؟! أُعْلِم الهيئة على عيالي أو الإمارة؟!\nج: إذا ما أطاق يُعلِّمهم، هذا من التعاون على البر والتقوى.\nس: قال أخاف؟\nج: لا، ما في جنون، يقول: إني عجزتُ عنهم، عجزتُ عن أولادي، فعاونوني عليهم. يقول لرئيس الهيئة، أو لبعض أعضاء الهيئة، فلعلهم إن شاء الله إذا جاءوا معه يتأدَّبون.\nس: سكوته عن ذلك يأثم به؟\nج: هو الظاهر.","link":"https://binbaz.org.sa/fatwas/21690/حكم-من-يدعو-الناس-واولاده-لا-يصلون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تربية الأبناء ومجاهدتهم للصلاة وحكم سكوته عنهم.mp3","categories":["تربية الأولاد","حكم الصلاة وأهميتها"]},{"id":3151,"question":"تسأل من فرنسا تقول: تخشى على ابنها أن يكون في الشارع فهل لا بأس أن تأخذه إلى المدرسة الفرنسية؟ يعني تخشى عليه أن يتعلم بعض الكلام في الشارع فتقول: الآن هل يُسمح لي أن يدخل في المدرسة لكي يتعلم؟ علمًا بأن في هذه المدرسة يعلمون من الأساس توحيدهم يعني؟","title":"كيف تكون تربية أبناء المسلمين في الغرب؟","answer":"الجواب: ما يجوز، تحفظه في بيتها، تصونه في بيتها، أو تدوّر \"مركز إسلامي\"، تلتمس المراكز الإسلامية، فرنسا فيها مراكز إسلامية كثيرة، وإنجلترا كذلك.\nس: أكثرهم يطلبون مالًا لدخول الأبناء؟\nالشيخ إذا اجتهدت يسّر الله أمرها وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2] يُيَسِر الله له مَنْ يرحمه ويقبله.","link":"https://binbaz.org.sa/fatwas/23313/كيف-تكون-تربية-ابناء-المسلمين-في-الغرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تربية الأبناء في بلاد الغرب.mp3","categories":["تربية الأولاد","حكم الصلاة وأهميتها"]},{"id":3776,"question":"الطفل الذي عمره سبع سنوات، ذَكَر، يُبعد عن قضية الإسبال في الثياب ويُربَّى عليه؟","title":"متى يُؤمر الطفل بتجنب الإسبال في الثياب؟","answer":"الجواب: نعم، يمنع من الإسبال وإن كان صغيرًا.","link":"https://binbaz.org.sa/fatwas/23972/متى-يومر-الطفل-بتجنب-الاسبال-في-الثياب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/يمنع الطفل الذي عمره سبع سنوات من الإسبال.mp3","categories":["تربية الأولاد","حكم الصلاة وأهميتها"]},{"id":3777,"question":"تأمره بالصلاة لسبع: هل مع التشديد عند بالصلاة، أم أمر فقط؟","title":"هل أمر الأبناء بالصلاة لسبع على الوجوب؟","answer":"الجواب: على وليه أن يأمره بالصلاة لسبعٍ، يجب على وليه وجوبًا، الرسول قال: مُرُوا، والأصل في الأوامر الوجوب، واضربوهم عليها لعشرٍ حتى يتمرَّنوا على الخير، وبعض الصبيان قد يبلغ بعد العشر، قد يبلغ في الحادي عشر والثاني عشر.","link":"https://binbaz.org.sa/fatwas/23973/هل-امر-الابناء-بالصلاة-لسبع-على-الوجوب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مروا أبنائكم بالصلاة لسبع.mp3","categories":["تربية الأولاد","حكم الصلاة وأهميتها"]},{"id":4468,"question":"المدرس الذي يدرس الأطفال هل يأمرهم بأن يتوضَّؤوا؟","title":"هل يؤمر الأطفال بالوضوء لتعلم القرآن؟","answer":"الجواب: إذا كانوا بلغوا السبعَ يأمرهم بالوضوء، أما من دون السبع... تكتب لهم حاجاتهم في أوراقٍ أو في ألواحٍ.\nس: متى ما بلغوا سنَّ التَّكليف...؟\nج: لا يمكنهم من المصحف، يجعل لهم أشياء، حاجاتهم؛ لأنه والله أعلم أنه هو في السنة الأولى، سن السابعة في السنة الأولى، وهو طالب.\nس: وإن كان أجزاء؟\nج: أقول: يجعل لهم في أوراق أسهل من المصحف، أو يُؤجل تعليمهم القرآن إلى إكمال السبع حتى يُعلِّمهم الطَّهارة.\nس: مَن حمل الطَّهارة على الطهارة المعنوية -طهارة الإنسان؟\nج: لا، نوع الطهارة الشرعية، مَن كان له عُرف شرعًا يُحمل عليه.\nس: الخلاف في المُميزين أو في البالغين؟\nج: في المميزين والبالغين، المميز يُعلّم الطهارة، والبالغ معروف.","link":"https://binbaz.org.sa/fatwas/24746/هل-يومر-الاطفال-بالوضوء-لتعلم-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يأمر مدرس الأطفال بالوضوء لتعلم القرآن.mp3","categories":["تربية الأولاد","القرآن وعلومه"]},{"id":5058,"question":"بعضهم يجيء إلى المدرسة وما صلَّى الفجر، وهو في الصف السادس، وفي الصف الخامس، يعني: تجاوز سنَّ البلوغ؟","title":"ما كيفية النصح للطلاب الذين لا يصلون الفجر؟","answer":"الجواب: نسأل الله العافية، هذا في ذمة أهله يُعلِّمونه، والمدرس يُعلِّمه.\nس: هل يجب على المدرس أن يُخرجه؟\nج: يجب أن يُنبهه إلى صلاة الفجر في وقتها إن كان مُمَيِّزًا، وإن لم يكن مميزًا فما عليه شيء، لكن يُعَلَّم إذا كان ابن سبعٍ فأكثر، وإن كان ابن عشرٍ فأكثر فإنه يستحق الضرب، والواجب على المدرسين أن يُعلِّموهم ويُوجِّهوهم.","link":"https://binbaz.org.sa/fatwas/29325/ما-كيفية-النصح-للطلاب-الذين-لا-يصلون-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما كيفية التوجية للطالب الذي لم يصلّ الفجر؟.mp3","categories":["تربية الأولاد","حكم الصلاة وأهميتها"]},{"id":5583,"question":"جاءت والدة الصبي بعد العشاء وهو قد نام، هل تُوقظه؟ ابن سبع سنين، يعني: لم يبلغ العاشرة؟","title":"هل يجب إيقاظ الصبي النائم إذا فاتته الصلاة؟","answer":"الجواب: ظاهر الأحاديث أنه يعمُّه ذلك. س: يأمره بالجماعة؟ ج: الظاهر حتى يتمرن عليها يُؤمر بالصلاة في الجماعة. س: إذا فاتت الصبي ابن سبعٍ؟ ج: ما في قضاء، الظاهر ما عليه قضاء، وإذا أمره بالقضاء حتى يتمرن طيب، حسن، قد يُقال: يعمّه الأمر، لكن ظاهر الحديث أنه يأمره في أوقاتها يعني. س: يُضرب على الجماعة أم على الأداء -ابن سبع؟ ج: لا، يُضرب عليها إذا بلغ عشرًا. س: هل يُضرب على الأداء؟ ج: هو الظاهر، الأداء في الجماعة حتى يتمرن.[1]","link":"https://binbaz.org.sa/fatwas/31541/هل-يجب-ايقاظ-الصبي-الناىم-اذا-فاتته-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 023.mp3","categories":["تربية الأولاد","حكم الصلاة وأهميتها"]},{"id":5910,"question":"هل للمرأة أن تتكلم على الزوج إذا أدب أولاده؟","title":"حكم تدخل المرأة عند تأديب الزوج أولاده","answer":"الجواب: لا بأس أن تتدخل في الموضوع إذا كان الزوج يسرف في الأدب، وليس عنده بصيرة في الأدب، لكن بحكمة بأسلوب حسن بالعبارات الحسنة، لا بالغلظة، والشدة، ولا بالأساليب التي تسبب فراقه لها، أو سبه لها، أو نحو ذلك. أما كونه يؤدب التأديب الصالح، والتأديب المناسب؛ فليس لها التدخل في ذلك؛ لأن هذا مما يفسد الأولاد عليه، فتعينه على ذلك، وتدعو له، وتشجعه، وتكون عونًا له على تأديبهم بما ينفعهم، ويردعهم عن السوء، لكن بعض الآباء قد يسرف إسرافًا كثيرًا! ويضع الأدب في غير محله؛ فيؤدب على الشيء اليسير بأشياء كثيرة إذا تدخلت في هذا الحال بوجه صالح، أو بأسلوب حسن، لا يزيغه، ولا يفسد الأولاد عليه، بل يكون بأسلوب حسن، أو في وقت آخر في غير وجود الأولاد، في وقت آخر يكون أسلم وأحسن. اللهم إلا أن يكون شيء كبير لا يتحمل؛ فلها التدخل في حضرتهم، لكن إذا أمكن أن يكون تدخلها في غير وجود الأولاد في وقت آخر فيما بينها وبينه خاص، تقول له: كذا وكذا، ويا فلان كذا وكذا، ينبغي أن يكون الأدب بصفة كذا، من باب النصيحة، والتعاون على الخير؛ فلا بأس. أما إذا كان تأديبهم مناسبًا، وفي محله، أو تأديب لم يتجاوز الحدود؛ فإنها تعينه على ذلك، تشجعه على ذلك عند أولاده، وفي غيبة أولاده.","link":"https://binbaz.org.sa/fatwas/1258/حكم-تدخل-المراة-عند-تاديب-الزوج-اولاده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_254.mp3","categories":["تربية الأولاد","القرآن وعلومه"]},{"id":6065,"question":"أنشئت -بفضل الله وتوفيقه- حلقات لتحفيظ القرآن الكريم ابتغاء مرضاة الله في أكثر من خمسين مسجدًا إلى الآن، وكنت قد وعدت كل طالب يحفظ جزءًا من القرآن أن أعطيه خمسين ريالًا، ولكني أخشى أن يكون هدف الطالب الحفظ لغرض الخمسين ريالًا فقط، فينشأ على حب المال، وأكون أنا السبب في ذلك، وأخشى على عقيدتي، فهل أوفي بعهدي لهم؟ علمًا بأن الخمسين ريالاً تشجعهم على الحفظ فعلًا، وبعضهم تخلف عن المسجد لما علم أنه لن يأخذ شيئًا، أم أمنع هذه المكافأة؛ حتى يتعود الحفظ لله خالصًا، دون انتظار أجر على ذلك، أفتونا جزاكم الله؟","title":"حكم تشجيع الطلاب بالمال لحفظ القرآن","answer":"الجواب: لا نعلم بأسًا في هذا، وهذا إن شاء عمل صالح؛ لأنهم يتعودون حفظ القرآن، ثم يهديهم الله للإخلاص في العمل، كما يروى عن بعض السلف أنه قال: تعلمنا العلم لغير الله، فأبى أن يكون إلا لله. فالحاصل: أن التشجيع على حفظ القرآن، وعلى تعلم العلم بالمساعدة، والجوائز، هذا لا حرج فيه -إن شاء الله- وهو يعين بلا شك على الاستمرار في طلب العلم، وفي حفظ القرآن، فنرجو ألا يكون في هذا شيء، وأن الباذل للمال مأجور، لكن من غير زكاة، يكون من مال آخر غير الزكاة، فإن الطالب قد يكون غنيًا لا يستحق الزكاة، فتكون هذه الأمور من غير الزكاة، إلا إذا علم أن الطلبة فقراء، وشجعوا بالمال ليدرسوا، ويتحفظوا القرآن، والذين أهلهم فقراء لا يستطيعون القيام بشؤونهم؛ فهذا لا بأس من الزكاة.","link":"https://binbaz.org.sa/fatwas/1475/حكم-تشجيع-الطلاب-بالمال-لحفظ-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_405.mp3","categories":["القرآن وعلومه","تربية الأولاد"]},{"id":6133,"question":"بعض الأولاد يبكرون يوم الجمعة، ويأتي أناس أكبر منهم، ويقيمونهم، ويجلسون مكانهم، ويحتجون بقوله ليلني منكم أولوا الأحلام، والنهى هل هذا جائز؟","title":"حكم إبعاد الأولاد من الصفوف المتقدمة إذا سبقوا إليها","answer":"الجواب: هذا يقوله بعض أهل العلم، ويرى أن الأولى بهم أن يصفوا وراء الرجال، ولكن هذا فيه نظر، والأولى أنهم إذا تقدموا ألا يقاموا إذا سبقوا إلى الصف الأول، أو إلى الصف الثاني، فلا يقيمهم من جاء بعدهم، لأنهم سبقوا إلى حق.. فلا يقامون أيضًا، في إقامتهم تنفير لهم من الصلاة، ومن المسابقة؛ فلا يليق ذلك. لكن لو اجتمع الناس، جاؤوا مجتمعين في سفر، أو لأي سبب، اجتمعوا صف الرجال أولًا، ثم الصبيان ثانيًا، ثم النساء بعدهم، إذا صادف ذلك، وهم مجتمعون، أما أن يخرجوا من الصفوف، ويزالون، ويصف مكانهم الكبار؛ فلا ينبغي هذا؛ لأنه مخالف للقواعد الإسلامية المعروفة، من سبق إلى مباح؛ فهو أحق به؛ ولأن هذا فيه تنفير لهم من المسابقة.","link":"https://binbaz.org.sa/fatwas/1577/حكم-ابعاد-الاولاد-من-الصفوف-المتقدمة-اذا-سبقوا-اليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_479.mp3","categories":["صلاة الجمعة","تربية الأولاد"]},{"id":6148,"question":"بعض الأولاد في الرابعة، والخامسة يحضرهم أباؤهم إلى المسجد، ثم بعدما ينتهي الإمام الصلاة يشوشون على المصلين، ويتكلمون، ويخرجون؟","title":"حكم إحضار الأطفال إلى المساجد","answer":"الجواب: الأولى أن لا يحضرهم حتى يعقلوا، إذا بلغوا سبعًا، وعقلوا يحضرهم، أما وهم دون ذلك، أو ما عندهم عقل يعبثون، ويؤذون فهذا لا ينبغي إحضارهم؛ لأنهم يؤذون المصلين، ويشوشون عليهم، أما إذا كان عاقلًا يفهم، ولا يؤذي، ويصلي؛ فلا بأس. السؤال: طيب يقطع الصلاة؟ الجواب:  لا ما يقطع، ما يقطع الصلاة إلا ثلاثة (المرأة، والحمار، والكلب الأسود) بس هذا الذي يقطع الصلاة، لكن لا تجعله يمر الرجل، والصبي لا يمر، والدابة لا تمر إذا تيسر منع ذلك، لكن لو مر الرجل، أو البعير، أو الغنم ما قطعت الصلاة، يقطع الصلاة: الحمار خاصة، والكلب الأسود، والمرأة.","link":"https://binbaz.org.sa/fatwas/1584/حكم-احضار-الاطفال-الى-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_483.mp3","categories":["صلاة الجماعة","حكم الصلاة وأهميتها","تربية الأولاد"]},{"id":6314,"question":"ما صحة الحديث الوارد في الأذان، والإقامة في أذني المولود؟","title":"درجة الحديث الوارد في الأذان والإقامة في أذني المولود","answer":"الجواب: جاء فيه حديث رواه الترمذي، وغيره في سنده ضعف، ولكن عمله جمع من أهل العلم، كعمر بن عبدالعزيز، وجماعة، وجاء فيه حديث آخر يعضده ضعيف أيضاً، فمن فعله؛ فلا بأس، جاءت به السنة يشد بعضها بعضًا، وإن كان فيها ضعف، ولكن يشد بعضها بعضًا، وقد عمل به المسلمون كثيرًا، ومن ترك؛ فلا بأس. السؤال: متى يعمل هذا؟  الجواب: في اليوم السابع، أو اليوم الأول يؤذن في أذنه اليمنى، ويقيم في اليسرى، ويسميه في اليوم الأول، أو في اليوم السابع، ويحلق رأسه، كل هذا سنة.","link":"https://binbaz.org.sa/fatwas/1901/درجة-الحديث-الوارد-في-الاذان-والاقامة-في-اذني-المولود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_684.mp3","categories":["تربية الأولاد","الحكم على الأحاديث","صلاة الجماعة"]},{"id":6726,"question":"ذكرتم أن من أسباب انحراف الأولاد الفراغ الذي يعيشون فيه، فما هو رأيكم في الحلول، والخطوات التي يتبعها المربي في تربية أولاده؛ لئلا يشعرهم بوقت الفراغ؟","title":"كيفية استغلال فراغ الأولاد","answer":"الفراغ إذا لم يشغل بحق، فإن النفوس تشغله بالباطل، فلا بد من سد الفراغ بما ينفع، وإذا كان عند الولد فراغ يشغله، إما بالمطالعة، وإما بمسابقات تنفع في شيء من العلم، والدين، وإما بنوادي نافعة، يلقى فيها المحاضرات الطيبة، والكلمات النافعة، والعظات الصالحة، وما أشبه ذلك، فلا بد من شغل الفراغ بشيء ينفع، ولا يضر، حتى ولو مباحًا، حتى لا يقع في الباطل، وحتى لا يقع في أيدي قرناء السوء، فلا بد أن يشغل فراغه بما ينفعه، من المطالعة في دروسه، من توجيه إلى الخير، من إشغاله بمراجعة الدروس مع أبيه، أو مع رجل طيب، أو مع أخيه، إيجاد أشياء في البيت تشغلهم عن الباطل، أشياء مباحة، يشغلهم عن الباطل... ثم يبيتون مبكرين، لا يسهرون، لا بد من فعل شيء ينفعهم، إما في الدين، وإما في الدنيا.","link":"https://binbaz.org.sa/fatwas/2614/كيفية-استغلال-فراغ-الاولاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1110.mp3","categories":["صلاة الجمعة","تربية الأولاد"]},{"id":6735,"question":"لي ولد ربيته على تلاوة القرآن الكريم حتى من العمر ثماني عشرة سنة، ولما كبر لم أقدر على أدبه، وهرب مني، ولا عاد أمتلك لي عليه شيء، فما الحل؟","title":"الواجب فعله على الوالدين تجاه أولادهم","answer":"الجواب: الذي عليك فعلته، إذا فعلت هذا في الصغر، وجاهدته، وربيته؛ فأنت قد فعلت خيرًا كثيرًا، وإذا هرب منك بعد الكبر، وضيع، قلت له فالإثم عليه، ما هو عليك أنت، الإثم عليه، أما ما دام في الصغر؛ فعليك أن تقوم بالواجب، وتعلمه.  ومن أهم ذلك أن تعلمه فاتحة الكتاب؛ الحمد، فإنها أعظم سورة، وأفضل سورة في كتاب الله القرآن، الفاتحة أم القرآن، هي أعظم سورة، وأفضل سورة، فتعليم الطفل لها، والطفلة حتى يعتاد قراءتها فيها خير عظيم، وفيها فوائد جمة، وهي أم القرآن، وأعظم سورة في القرآن.  وهكذا تعليمهن القصار من القرآن، والمعوذتين، وقل هو الله أحد، وتبت، وقل يا أيها الكافرون، والسور القصيرة، إذا تعلمها الأولاد فيها الخير الكثير حتى يعشن عليها، ويتمرن على قراءتها، ثم يستفيد من المعاني، يوجههم والدهم، أو أمهم -إن كان عندها علم- من المعاني العظيمة في هذه السور القصيرة، فيحصل لهم بذلك علم عظيم، وفائدة كبيرة تنفعهم عند الكبر، كما يعين أولادهم بهذا على ما توجه المدرسة، وتقول له المدرسة هذا تعاون بين آباء الأطفال، وأمهات الأطفال، وبين المدرسة. المقصود: أن الوالد، والأم عليهم أن يعلماه، ما دام الولد بحضانتهما، وتحت قدرتهما، وتصرفهما، فإذا كبر، وخرج منها، واستقل بنفسه، فالإثم عليه، لا عليهما.","link":"https://binbaz.org.sa/fatwas/2612/الواجب-فعله-على-الوالدين-تجاه-اولادهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1108.mp3","categories":["تربية الأولاد","الآداب والأخلاق المحمودة"]},{"id":6736,"question":"من المعلوم أن العدل بين الأولاد في الأعطية واجب، ولكن قد يحتاج أحدهم ما لا يحتاج الآخر، فالكبير يحتاج مصاريف أكثر من الصغير، والبنت قد تحتاج بعض الذهب، فكيف يكون العدل بينهم؟","title":"كيفية العدل بين الأولاد في العطية والنفقة","answer":"الجواب: الأعطية التي فيها العدل، المنحة الزائدة على النفقة، الرسول ﷺ قال: اتقوا الله، واعدلوا بين أولادكم يعني في العطايا الزائدة، أما الإنفاق عليهم، فكل ينفق عليه بقدر حاجته، الكبير له نفقة، والرضيع له نفقة،  والذي بين هذين له نفقة، فليسوا سواء، فهذه نفقة واجبة، ينفق عليهم بقدر حاجتهم، فالكبير بحاجة إلى ملابس غير ملابس الصغير، في حاجة إلى الزواج، إذا كان ما عنده مال؛ يزوجه، بحاجة إلى السكن، والصغير حاجته دون [ذلك] فكل من الأولاد يعطى حاجته على حسب حاله، ولا .. تعديل، التعديل في ذلك أنه يعطى حاجته هذا التعديل. أما العطايا الزائدة على النفقة، هذا هو محل التعديل، ولا يخص أحدًا بشيء، فيعطي هذا .. وهذا ما يعطيه، هذا يعطيه سيارة، وهذا ما يعطيه سيارة، لا، يساوي بينهم، لكن في نفقتهم في الملابس، والمآكل، والمشارب، والسفر، ونحو ذلك، كل له قدر حاجته.","link":"https://binbaz.org.sa/fatwas/2607/كيفية-العدل-بين-الاولاد-في-العطية-والنفقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1103.mp3","categories":["تربية الأولاد","النفقات","الهبة والعطية"]},{"id":6739,"question":"زوجتي لا تأمر أولادها بالصلاة، ولا تزجرهم عن فعل المنكرات، رغم محاولتي لها بالعدول عن هذا الموقف، علمًا أنني ضربتها مرات عديدة، وهجرتها بعض الأحيان أكثر من أربعة أشهر متواصلة، ولكن دون جدوى، فماذا أفعل والحالة كذلك؟","title":"الحث على توجيه الأولاد والزوجة إلى الخير ونصيحتهم وأمرهم بذلك","answer":"الجواب: عليك أن تجتهد أنت بنفسك، وتأمرهم، وتنهاهم، وتنصح الأم، وتستمر في نصيحتها، وتوجيهها إلى الخير، وإذا نصحت أنت، واتقيت الله، واجتهدت، وبذلت الوسع؛ سوف تعان -إن شاء الله- توفق، والله يقول: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2]، وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4].  فعليك أن تتقي الله، وأنت المسؤول، وهيبتك أعظم، فعليك أن تتقي الله في ذلك، وأن تجتهد في أمرهم بالصلاة، وتوجيههم إلى الخير ذكورًا وإناثًا، وأن تنصح أمهم دائمًا، وأن تطلب منها أن تعينك على الخير، وألا تكون عونًا على الشر، ومع الجهاد المستمر، والنصيحة المستمرة والقيام بالواجب المستمر، يهديهم الله -إن شاء الله- وتكفى شر أمهم.","link":"https://binbaz.org.sa/fatwas/2608/الحث-على-توجيه-الاولاد-والزوجة-الى-الخير-ونصيحتهم-وامرهم-بذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1104.mp3","categories":["تربية الأولاد","الآداب والأخلاق المحمودة"]},{"id":7118,"question":"والدي يملك أموالًا وعقارات، وله ثلاث زوجات، وقام بتزويجي أنا وأخي الذي يصغرني في السن، وكنا ولازلنا نسكن مع والدنا، وأصبحنا نملك الأولاد، عندها قال والدي: كل واحد يأخذ قطعة أرض، ويبنيها بقرض من الدولة، وقد ذهب والدي وإخوتي إلى المحكمة لإفراغ الأرض بأسمائنا، ولكنهم فوجئوا برفض القاضي حيث قال: إن هناك لهم إخوة كثيرون، وهم صغار من بنين وبنات، ولا بد أن يعطى كل واحد منهم قطعة أرض، أو يمنعوا جميعًا، علمًا بأني أعمل بوظيفة ودخلي لا يمكنني من شراء أرض، ما هو الحكم إذا أنا أعطيت والدي قطعتين أرض قد منحت لي من قبل الدولة في مكانين مختلفين من المملكة مقابل أن يفرغ لي أحد الأراضي التي في الرياض، على أن لدي شعور على أن الوالد إذا فعل بي هذا الشيء؛ فهو من أجل أن يمكنني الأرض التي في الرياض؟","title":"حكم عطية الوالد بعض أولاده دون الآخرين","answer":"الجواب:\n\nالذي قاله القاضي صواب، لأن الرسول  قال: اتقوا الله واعدلوا بين أولادكم فليس له أن يعطي بعض الأولاد أراضي، ولا يعطي الآخرين، فعليه أن يعمهم جميعًا، أو يتركهم جميعًا، هكذا أمر النبي ﷺ: اتقوا الله واعدلوا بين أولادكم.\n\nفإذا كان يريد نفعكم؛ يبيع عليكم بيعًا، يبيع عليكم الأراضي بيعًا، مثل ما يبيع على الناس من غير محاباة، يبيع عليكم الأرض بما تساوي عند أهل الخبرة بيعًا عليكم مؤجلًا، مثل ما يباع على الأجانب، يباع عليكم وتكون في ذمتكم؛ حتى يتيسر لكم الوفاء مثل ما يبيع على أناس أجانب.\n\nوإذا باعها عليكم بيعًا بأراضي أخرى من غير محاباة، بل بأراضي تكون قيمتها معادلة لقيمة الأرض التي أعطاكم بغير محاباة، ولا حيلة، فلا بأس بذلك؛ لأنه يجوز أن يبيع عليكم كما يبيع على غيركم.\n\nالسؤال: وإذا كانوا راضين؟\n\nالجواب: إن كانوا كبارًا، وراضين؛ لا بأس، أما إن كانوا صغارًا ما لهم رضا، إن كانوا مرشدين، ووافقوا مثل عنده عشرة أو ثمانية، وأعطى اثنين أو ثلاثة، ورضي الباقون، وهم مرشدون؛ لا بأس، أما إن كانوا صغارًا، أو مجانين، أو معتوهين ليس له ذلك.","link":"https://binbaz.org.sa/fatwas/3147/حكم-عطية-الوالد-بعض-اولاده-دون-الاخرين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1505.mp3","categories":["النفقات","الهبة والعطية","تربية الأولاد"]},{"id":7475,"question":"أيضاً في رسالة عبد الله السليمان من الرياض سؤال يقول: قال الله تعالى: فَأَمَّا الْيَتِيمَ فَلا تَقْهَرْ [الضحى:9]، هل تأديب اليتيم وضربه إذا أخطأ، ولو أدى إلى بكائه الشديد يعتبر من قهره؟","title":"هل يجوز ضرب اليتيم لتأديبه وتوجيهه إلى الخير؟","answer":"الجواب:  لا، المقصود من قهره: ظلمه والتعدي عليه والتكبر عليه، أما تأديبه وتوجيهه إلى الخير فهو غير داخل في هذا، بل واجب على الولي، يجب على الولي أن يؤدبه وألا يهمله حتى تسوء أخلاقه، إذا أهمل اليتيم ساءت أخلاقه، وصار كلاً على الناس وثقيلاً على الناس. لكن الواجب على وليه أن يلاحظه، كعمه، وأخيه.. ونحو ذلك، أن يلاحظه إذا ساءت أخلاقه أدبه حتى يستقيم، حتى يكون شاباً مؤدباً، مثلما يؤدب أولاده، فالإصلاح لهم لابد منه، فكما تؤدب أولادك تؤدب اليتيم الذي عندك، وليس هذا من ظلمه ولا من قهره ولا من الإساءة إليه، بل هذا من الإصلاح والإحسان إليه حتى تستقيم أخلاقه، وحتى يكون شاباً جيداً مؤدباً يضع الأمور في مواضعها ويضع الكلام في مواضعه. نعم.","link":"https://binbaz.org.sa/fatwas/4320/هل-يجوز-ضرب-اليتيم-لتاديبه-وتوجيهه-الى-الخير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_003/00305.mp3","categories":["تربية الأولاد","حكم الصلاة وأهميتها"]},{"id":7784,"question":"أيضاً يقول: هل ضرب إخواني وسبهم لتأديبهم حلال أم حرام، وكيف تربية النبي ﷺ؟","title":"مشروعيةضرب الأولاد لتأديبهم","answer":"الجواب: تربية الإخوان والأولاد أمر واجب، ضربهم وتوجيههم إلى الخير أمر واجب، النبي ﷺ قال: مروا أولادكم بالصلاة لسبع، واضربوهم عليها لعشر فضرب الأولاد والإخوة الصغار وتوجيههم إلى الخير أمر لازم لك إذا كنت أنت القائم عليهم، أما السب فلا، لا تسبهم، لكن تقول لهم الكلام الطيب تحذرهم، وتأتي بالكلام الذي فيه زجرهم من دون سب: يا عدو نفسه، يا ظالم نفسه، يا كذا.. يا كذا، بالكلمات التي ليس فيها سب، ومع توبيخه، مع ضربه الضرب الذي لا يضره، ضرب غير مبرح، يحصل به المقصود من توجيهه إلى الخير ومنعه من الشر، وأما السب: لعنك الله أو أخزاك الله، هذا لا يجوز، أما بعبارات أخرى مثل يا حمار! أو يا كلب! أو يا كذا فالأولى ترك هذه الألفاظ أيضاً؛ لأنها نابية، وقد تفضي إلى ما لا تحمد عقباه، فالأولى تركها وأن يستعمل ألفاظاً غير هذه الألفاظ: يا عدو نفسه، يا ظالم نفسه، يا كذا.. من الكلمات التي ليس فيها ما يجرح الشعور أو يسبب مشاكل. نعم.","link":"https://binbaz.org.sa/fatwas/5126/مشروعية-ضرب-الاولاد-لتاديبهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_048/04806.mp3","categories":["تربية الأولاد","حكم الصلاة وأهميتها"]},{"id":8184,"question":"تقول أنا معلمة وقد قمت بواجبي في التعليم ابتغاء رضا الله فلم أقصر فيه أو أتهاون عن بعض ولكن قد تعتريني بعض المشكلات، فمثلاً: الطالبة تكون غير مجتهدة أو لم تؤد واجبها فأنا بطبيعة الحال أقوم بضربها حتى لا تكرر هذا الإهمال فما حكم ضرب الطالبات لتأديبهن؟ وما صحة قول رسول الله ﷺ: العصا لمن عصى، نسبت هذا إلى الرسول صلى الله عليه وسلم! أرجو أن تفيدوها سماحة الشيخ؟","title":"حكم ضرب المعلم للطالب على إهماله","answer":"الجواب: لا شك أن الواجب على المعلمة تحري أسباب نجاح الطالب والطالبة، فإذا كانت الطالبة تقصر وتتساهل في أداء واجبها فعليك أن تنصحيها وتوجيهها وإذا لم ينفع النصح ولم تتأثر بالكلام فلا مانع من تأديبها التأديب الذي يعينها على أداء الواجب من دون خطر تأديب ليس فيه خطر لا جرح ولا كسر ولكنه تأديب يحصل به المقصود من تشجيعها على العمل وتنشيطها على العمل وأنت مأجورة في ذلك كما يؤدب الإنسان ولده على الصلاة قال النبي ﷺ مروا أبناءكم بالصلاة لسبع واضربوهم عليها لعشر.\nفالضرب للتأديب وكما يؤدب الرجل زوجته للقيام بحقه أو بحق الله سبحانه لا بأس بهذا فهذا من هذا الباب تأديب الطالب وتأديب الطالبة عند وجود التقصير منهما أو التساهل أمر مطلوب وهو في مصلحتهما لكن مع مراعاة عدم الخطر في ذلك، وأما قولك في الحديث: «العصا لمن عصى» فهذا فليس بحديث وليس بوارد عن النبي ﷺ وإنما هذا من كلام العامة.\nالمقدم: بارك الله فيكم. سماحة الشيخ عن تربية المعلم للتلاميذ يدور حديث وحديث في الصحافة وفي وسائل الإعلام وكانت نتيجة ذلك الحديث أن ذهبت هيبة المعلم وأصبح في مكان خوف من قبل بعض الطلبة الذين لم يؤدبوا كما يجب لعل لسماحة الشيخ رأي في هذا وفق لشرع الله؟\nالشيخ: وما هو الحديث؟\nالمقدم: الحديث أن تلك الصحافة أو وسائل الإعلام تلك لا ترى أن يقوم المعلم بضرب الطالب إطلاقاً.\nالشيخ: يعني يخوضون في هذا.\nالسائل: يخوضون في هذا حتى أن الطلبة قرأوا هذا فأصبح المعلم بدون شخصية أمام تلاميذه.\nالشيخ: لا، هذا خطأ من الصحافة هذا خطأ من الخائضين بل ينبغي لمن يتكلم في هذا الشأن أن ينصح الطلبة والطالبات وأن يقول لهم عليهم أن يتقوا الله وعليهم أن يؤدوا الواجب وعليهم أن يعينوا الأستاذ ويعينوا المدرسة على ما ينفعهما على ما ينفع الطلبة على هذا ..... ينبغي، وعلى المعلم وعلى المدرسة أن يقوم بالواجب من التأديب عند تمرد الطالب أو الطالبة وعند عدم اكتراث الطالب والطالبة بما يوجهه إليه الأستاذ أو المدرسة هذا هو الواجب على من يتكلم في الصحافة أن يكون مع هؤلاء ومع هؤلاء.\nينصحوا الطلبة والطالبات ويأمروا الجميع بتقوى الله والعناية بالطلب والحرص على أداء الواجب وأن يقوم بما وكل إليه وأن يعد ما ينبغي أن يعده وأن يحرص ويبذل بوسعه وعلى المعلم وعلى المعلمة أن ينظرا في ذلك فإذا ظهر لهما من الطالب أو من الطالبة أنهما مقصران وأنهما لم يبذلا الواجب فإنهما يؤدبان أما لو كان الأمر بخلاف ذلك يعني كان الطالب مغفل ما فيه حيله أو المطلوب يعجز عنه مثله لصغر سنه وعدم تحمل هذا الشيء فينبغي لهم أن يقدروا ذلك وأن ينصحوا الجهات المختصة بأن تخفف هذا المقرر وتعوض عنه مقرراً آخر أو تحذف ما يشق على الطالب ولا يتحمله الطالب لأن الطالب له قدرة محدودة فلابد من كون المعلم أو المعلمة ينظران في هذا الأمر فلا يحملان الطالب ما لا يحتمل ولا يحملا الطالبة ما لا تحتمل ولكن يكونان مع الطالبة في الأمر الموافق ومع الطالب في الأمر الموافق ويقومان عليه في الأمر الذي يريان أنه مقصر فيه هذا هو الواجب لا هذا ولا هذا، لا الغلو في الأمر حتى يؤدب كل أحد ولا التقصير حتى لا يؤدب كل أحد ولكن من استحق التأديب يؤدب.\nومن كان لا يقوى وليس مثله يقوى فهو يعني يعامل بطرق أخرى من النصيحة أو العناية بالجهات المختصة حتى تخفف وتزيل العقبة التي لا يتحملها هذا الطالب أو هذه الطالبة المقصود المعلم طبيب والمعلمة طبيبة لابد أن ينظرا في الأمر فيؤدبا حيث يكون التأديب في محله ويتوقفا عن التأديب حيث لا يكون في محله. نعم.","link":"https://binbaz.org.sa/fatwas/5991/حكم-ضرب-المعلم-للطالب-على-اهماله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_106/10607.mp3","categories":["العالم والمتعلم","تربية الأولاد","الدعوة والدعاة"]},{"id":8337,"question":"أختنا في الواقع لها سؤال آخر سماحة الشيخ ويبدو لي أنه ثمرة هذا الزواج غير الموفق ولا حول ولا قوة إلا بالله، تقول: إن لها ابناً لا يصلي، وقد نصحته وهددته ولم يبال، عمره ست عشرة سنة، تقول: إنها تنصحه وهو يستهزئ بها وفي بعض الأحيان يصلي ويعود ويقول: إن الشيطان يوسوس فوق رأسه، وتستمر من مثل هذه العبارات سماحة الشيخ وتسأل وتقول: إنني مستجيرة بالله ثم بكم تنقذوني مما أنا فيه وتقودوني إلى الصواب، وما العمل لأرملة لا حول لها ولا قوة إلا بالله، ثم تريد العون منكم. وجزاكم الله عنها خير الجزاء؟","title":"ما واجب الأم تجاه ولدها الذي لا يصلي؟","answer":"الجواب: هذا الولد الذي ليس بمواظب على الصلاة الواجب نصيحته وتوجيهه إلى الخير، ووعظه وتذكيره، وتحذيره من غضب الله، قال الله جل وعلا في حق أهل النار: مَا سَلَكَكُمْ فِي سَقَرَ ۝ قَالُوا لَمْ نَكُ مِنَ الْمُصَلِّينَ [المدثر:42-43]، فترك الصلاة من أعظم الأسباب في دخول النار؛ لأن تركها كفر أكبر، قال النبي ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، وقال عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة، فالصلاة لها شأن عظيم، وهي عمود الإسلام، وهي الفارقة بين المسلم والكافر.\nفالواجب على كل مسلم ومسلمة قد بلغ الحلم وبلغت الحلم أن يؤدي الصلاة، وهو مأمور بها قبل أن يبلغ الحلم حتى يعتادها ويتمرن عليها، كما أمر النبي ﷺ بأن نأمر أبناءنا بالصلاة إذا بلغوا سبعاً ونضربهم عليها إذا بلغوا عشراً، وهكذا الفتيات، أما من بلغ فيجب عليه أن يصلي، وإذا تأخر عن الصلاة وجب أن يستتاب فإن تاب وإلا وجب على ولي الأمر قتله؛ لأن الصلاة أمرها عظيم، وهي الركن الثاني من أركان الإسلام. فعليك أيها الأخت في الله أن تنصحيه وأن تجتهدي في توجيهه إلى الخير، وتحذيره من مغبة عمله السيئ، فإن أصر فتبرئي منه واطلبي منه الخروج، مريه بالخروج عنك والبعد عنك حتى لا يضرك أمره وحتى لا تحل بك العقوبة وهو عندك.\nفيجب عليه أن ينصاع لأمرك وأن يتقي الله ، وأن يطيع أمره سبحانه وأمر رسوله عليه الصلاة والسلام في أداء الصلاة، فإذا لم يمتثل وأصر على عناده وكفره فإن الواجب عليك هجره وكراهة لقائه والتمعر في وجهه بالكراهة، وأمره بالخروج من بيتك وعدم اعتباره ابناً لك، لعل الله يهديه بعد ذلك، وعليك مع هذا أن تأمري من له شأن من أقاربك كأبيك أو أخيك الكبير أو أخواله الآخرين أن يوجهوه وأن ينصحوه وأن يؤدبوه إذا استطاعوا، لعل الله يهديه بأسبابهم.\nالمقدم: اللهم آمين. سماحة الشيخ بقي من وقت البرنامج ما يقرب من دقيقتين أرجو أن تتكرموا فيها بمعالجة نفسية أختنا، حيث ألحظ أن فيها الألم والحسرة لو تكرمتم؟\nالشيخ: نوصيك أيها الأخت في الله! بالصبر، فالأمر ليس إليك الأمر إلى الله، يقول الله سبحانه: لَيْسَ عَلَيْكَ هُدَاهُمْ وَلَكِنَّ اللَّهَ يَهْدِي مَنْ يَشَاءُ [البقرة:272]، ويقول سبحانه لنبيه ﷺ: إِنَّكَ لا تَهْدِي مَنْ أَحْبَبْتَ وَلَكِنَّ اللَّهَ يَهْدِي مَنْ يَشَاءُ [القصص:56]، لما اجتهد في هداية عمه أبي طالب لم يتيسر له ذلك، فأنزل الله عليه سبحانه وتعالى قوله سبحانه: إِنَّكَ لا تَهْدِي مَنْ أَحْبَبْتَ وَلَكِنَّ اللَّهَ يَهْدِي مَنْ يَشَاءُُ [القصص:56] ففي هذا عزاء، وفيه تسلية لك ولأمثالك، إذا أبى ابنك أن يهتدي ولم يوافق فلك في رسول الله عليه الصلاة والسلام الأسوة الحسنة، فإذا نصحت ووجهت وأمرت فالأمر إلى الله سبحانه وتعالى.","link":"https://binbaz.org.sa/fatwas/6152/ما-واجب-الام-تجاه-ولدها-الذي-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_111/11109.mp3","categories":["حكم الصلاة وأهميتها","تربية الأولاد"]},{"id":8358,"question":"أخونا يقول: أنا أسكن مع عائلتي في منزلٍ واحد، وأقوم بمراعاة مصالحهم بعد وفاة والدي، لكني أود السفر إلى المدينة المنورة والبقاء فيها، ولكن والدتي لا تطيق فراقي، وأنها تقول: ليس لهم إلا الله ثم أنا، مع العلم بأن لدي إخوة أربعة غيري، الأكبر مني والأصغر قد تزوجوا، وأنجبوا أولاد، إلا أنا، وأنا لا أريد السفر إلا لطاعة الله وقضاء باقي العمر في الطاعة؛ لأن بلادنا تعلمون ما نشكو منها، وإذا لم أستطع السفر فأود الخروج في بيتٍ لوحدي كي يتسنى لي تربية أولادي التربية الصحيحة؛ لأني لا أستطيع أن أعيش معهم؛ لأنهم يتتبعون مشاهدة الفيديو وغير ذلك، أرجو من سماحة الشيخ توجيهي حول هذه القضايا، جزاكم الله خيراً؟","title":"حكم البقاء في المنزل طاعة للوالدة مع الخلطة","answer":"الجواب: إذا كان عليك خطر في البقاء معهم فلا بأس أن تنتقل في بيت مستقل في المدينة أو في غيرها، وعليك أن تراعي مشاعر الوالدة وتستسمحها بالكلام الطيب والعبارة الحسنة، حتى تسمح إن شاء الله، فإن لم تسمح وأنت عليك خطر وعلى أولادك خطر من الاجتماع بإخوتك الذين يتسامحون في الفيديو وغير ذلك، فلا حرج عليك، وعلى الوالدة أن تسمح عنك، عليها أن تتقي الله وعليها أن تسمح لك، وعليها أن لا تشدد؛ لأنك تطلب السلامة لدينك، فلا حرج عليك، وأنت استعن بالله جل وعلا واعمل ما تراه أصلح لدينك وأصلح لأولادك، وأسلم لعرضك، هذا هو الواجب عليك، الله يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] فالمؤمن يتقي الله ما استطاع، ويحرص على سلامة دينه، وسلامة أولاده، وعلى تربية أولاده التربية الإسلامية، وعلى الوالدة أن تعينك على ذلك، فإن هدى الله إخوتك، وتباعدوا عما حرم الله وصلحت الحال، فابق معهم والحمد لله، أما إن لم تتغير الحال، وأنت تخشى على دينك وعلى أولادك فلك أن تنتقل وإن لم ترض الوالدة، لكن عليها أن ترضى وعليها أن تسمح وعليها أن تقدر ما ذكرته من الحاجة إلى الانفراد، رزق الله الجميع التوفيق والهداية.\nالمقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/6207/حكم-البقاء-في-المنزل-طاعة-للوالدة-مع-الخلطة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_113/11315.mp3","categories":["تربية الأولاد","الآداب والأخلاق المحمودة"]},{"id":8477,"question":"أختنا أم الحسن تسأل مع المعلمات سماحة الشيخ اللائي يسألن عن ضرب الطالبات لغرض التعليم، ولغرض الحث على أداء الواجبات، وتقول: سبب الضرب هو حث الطالب أو الطالبة على أداء واجباتهم المطلوبة منهم، وتعويدهم على عدم التهاون فيها؟","title":"حكم ضرب الصغير للتعليم","answer":"الجواب: لا بأس في ذلك، المعلم والمعلمة والوالد كل منهم عليه أن يلاحظ الأولاد وأن يؤدب من يستحق التأديب إذا قصر في واجبه، حتى يعتاد الأخلاق الفاضلة وحتى يستقيم على ما ينبغي من العمل الصالح، ولهذا ثبت عنه ﷺ أنه قال: مروا أولادكم بالصلاة لسبعع واضربوهم عليها لعشر، وفرقوا بينهم في المضاجع فالولد إذا كان يضرب وهكذا الأنثى تضرب إذا بلغ كل منهما العشر وقصر في الصلاة يؤدب حتى يستقيم على الصلاة، وهكذا الواجبات الأخرى في التعليم وفي شئون البيت وفي غير ذلك الواجب على أولياء الصغار من الذكور والإناث أن يعنوا بتوجيههم وتأديبهم لكن يكون ضرباً لا خطر فيه، ضرباً خفيفاً يحصل به المقصود من دون مضرة على الذكر والأنثى جميعاً. نعم.","link":"https://binbaz.org.sa/fatwas/6514/حكم-ضرب-الصغير-للتعليم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_125/12504.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":8593,"question":"ننتقل بعد هذا إلى رسالة وصلت إلى البرنامج من مجموعة من الأخوات المستمعات هن خمس فتيات، رسالتهن مطولة ملخصها سماحة الشيخ: يشكين من خلاف أسري بين البنات وأبيهن وجدتهن لأبيهن نظراً لعدم الاهتمام بالبنات الخمس، وأصغرهن في الثانية والعشرين ولم يتزوجن بعد، فالأب بعيد عن البيت ولا يأتي إلا كالزائر، والأم تفكر في الطلاق ويرجين التوجيه لو تكرمت سماحة الشيخ؟","title":"إهمال الوالد لبناته وتركهن دون زواج","answer":"الجواب: الواجب على أبيهن أن يتقي الله سبحانه وتعالى، وأن يلاحظهن ويعتني بهن، ويزورهن كثيراً، ويتفقد أحوالهن هذا الواجب عليه، هو مسئول وهو وليهن فعليه أن يتقي الله في ذلك وأن يجتهد في تزويجهن إذا خطبهن من يصلح لهن من المسلمين، عليه أن يجتهد ولو كان ليس بكامل ولو كان عنده شيء من المعاصي، ما دام مسلماً فإنه يزوجهن؛ لأن تركهن بدون زواج فيه خطر كبير، فإذا شاروهن أو أخبرهن بحاله ورضين زوجهن، لكن لا يزوجهن بكافر يزوجهن بمسلم، وإن كان هناك شيء من النقص من بعض المعاصي، لكن إذا وجد الطيب إذا وجد الكفء الذي هو سليم مستور ليس عنده معاصي فهو مقدم على غيره، وهو الغنيمة العظيمة، لكن بكل حال عليه أن يعتني ويقدم الأفضل فالأفضل من المسلمين الخاطبين، ويجتهد في الحرص على سترهن وبعدهن عن الفتنة وعن أسباب الفتنة، وعلى الجدة كذلك أم الأب أن تساعد في هذا الخير، وأن تقول لابنها: اتق الله في بناتك، وإذا كان لهن أعمام كذلك، ينصحون والد البنات، ويجتهدون في توجيهه إلى الخير حتى لا يهمل بناته، هذا هو الواجب التعاون على الجميع، التعاون على البر والتقوى، وإذا كانت أمهن موجودة كذلك تنصح أباهن بالكلام الطيب بالأسلوب الحسن حتى لا يسبب طلاقاً يجتهد، تجتهد المرأة التي هي أمهن والجدة التي هي أم أبيهن، وهكذا إذا كان لهن عمات أو أعمام يشتركون في هذا الخير نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6700/اهمال-الوالد-لبناته-وتركهن-دون-زواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_128/12805.mp3","categories":["تربية الأولاد"]},{"id":8729,"question":"إذا كان الفرقة بين الأبناء يسبب هذا سماحة الشيخ فما بالكم إذا ابتعدت المرأة عن بيتها وتركت أطفالها للخدم أو ما أشبه ذلك؟","title":"نصيحة حول ضرر ابتعاد الأم عن تربية الأولاد وتركهم للخادمة","answer":"الجواب: لاشك أن هذا يضر كثيراً ويجعل الولد ينشأ نشأة فيها نظر ولاسيما إذا كانت الخادمة ليست ذات دين فإن الأولاد ينشئون نشأة غير دينية وعليهم خطر من ذلك، فمن الأهم أن تتولى الأم تربية الأولاد التربية الإسلامية وأن تعطف عليهم وتحن عليهم وتواسيهم وتنظر في حاجاتهم وشئونهم وتقدم ذلك على الوظيفة ما دام الزوج يقوم بحالها وحاجاتها فلا حاجة إلى الوظيفة، قيامها بأولادها وتربية أولادها والإحسان إليهم وتوجيههم إلى الخير أهم وأهم وأهم من الوظائف التي تدر مالاً ليست في حاجة إليه ولا في ضرورة إليه، والله المستعان. نعم.","link":"https://binbaz.org.sa/fatwas/6881/نصيحة-حول-ضرر-ابتعاد-الام-عن-تربية-الاولاد-وتركهم-للخادمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_135/13502.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":8752,"question":"له سؤال ثالث يقول فيه: ورد في الحديث: اتقوا الله واعدلوا بين أولادكم فهل المقصود المساواة المطلقة أو أن للذكر مثل حظ الأنثيين أسوة بالميراث، فالحديث على ما أظن يقول: أكلهم أعطيته مثل فكلمة: (مثل) إن صحت توحي بالمساواة المطلقة، اللهم إن كان يتكلم عن الذكور فقط أفيدونا أفادكم الله؟","title":"العدل بين الأولاد وحكم تفضيل بعضهم على بعض","answer":"الجواب: الحديث صحيح رواه الشيخان عن النعمان بن بشير رضي الله تعالى عنه: أن أباه أعطاه غلاماً فقالت أمه: لا أرضى حتى يشهد رسول الله عليه الصلاة والسلام، فذهب بشير بن سعد إلى النبي ﷺ، وأخبره بما فعل فقال: أكل ولدك أعطيته مثل ما أعطيت النعمان؟ قال: لا، فقال: اتقوا الله واعدلوا بين أولادكم.\nفدل ذلك على أنه لا يجوز تفضيل بعض الأولاد على بعض بالعطايا كلهم ولده وكلهم يرجى بره فلا يجوز أن يخص بعضهم بالعطية، واختلف العلماء رحمة الله عليهم هل يسوى بينهم ويكون الذكر كالأنثى أم يفضل الذكر على الأنثى كالميراث؟ على قولين لأهل العلم: والأرجح أن العطية تكون كالميراث وأن التسوية تكون بجعل الذكر كالأنثيين، فإن هذا هو الذي جعله الله له في الميراث، وهو سبحانه الحكم العدل، فيكون المؤمن في عطيته لأولاده كذلك، كما لو خلفه لهم بعد موته للذكر مثل حظ الأنثيين فهكذا إذا أعطاهم في حال حياته يعطى الذكر مثل حظ الأنثيين، هذا هو العدل بالنسبة إليهم وبالنسبة إلى أمهم وأبيهم، وهذا هو الواجب على الأب والأم أن يعطوا الأولاد هكذا للذكر مثل حظ الأنثيين، وبذلك يحصل العدل والتسوية كما جعل الله ذلك عدلاً في إرثهم من أبيهم وأمهم والله المستعان. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6905/العدل-بين-الاولاد-وحكم-تفضيل-بعضهم-على-بعض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_217/21703.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":8883,"question":"إذا أراد الوالد أو الوالدة أو الوالدان جميعاً لأبنائهما الفرح والسرور بم ينصحونهم لو تكرمتم سماحة الشيخ؟","title":"سبل إسعاد الأبناء","answer":"الجواب: يستعملون ما يسرهم من الأحاديث الطيبة، من الذهاب بهم إلى البساتين الطيبة، إلى الأرض الطيبة إذا كان عندهم بستان طيب، إذا كان في محل طيب يذهبون إليه ليس فيه منكر، يشترون لهم حاجات تسرهم مثل أشرطة إسلامية تنفعهم يعني فيها الخطب الطيبة والمواعظ الطيبة، والأشعار المفيدة الداعية إلى الخير وإلى ترك الشر، وما أشبه ذلك مما يسر أولادهم وينفع أولادهم من دون أن يوقعهم في المحرمات، أهل الخير يلتمسون طرق الخير التي تشرح الصدور وتنير القلوب، ويحصل بها المتعة الحسنة ويحصل بها الأنس دون ما حرم الله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7039/سبل-اسعاد-الابناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_139/13909.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":8900,"question":"من البصرة الأخت سميحة عمار تسأل مجموعة من الأسئلة من بينها سؤال عن أخت لها تقول: إنها في العقد الخامس من عمرها، ولها ابن لشدة حبها له تتغاضى كثيرًا عن مخالفاته لأمر دينه ولأمور تتعلق بالأخلاق، وتقول: إن ذلك شأن كثير من الوالدات وبعض الآباء وترجو التوجيه في هذا لو تكرمتم؟","title":"وجوب الأمر بالمعروف والنهي عن المنكر للقريب والبعيد","answer":"الجواب: الواجب على المسلم أن يتقي الله في نفسه وفي أهل بيته وفي جيرانه وفي كل المسلمين، وذلك بدعوتهم إلى الله وأمرهم بالمعروف ونهيهم عن المنكر وأن لا تأخذه في الله لومة لائم ، هذا هو الواجب على كل مسلم، فلا يدع الأمر بالمعروف والنهي عن المنكر من أجل قرابة قريب أو محبة شخص بل من حبه له ومن صلته له الحقيقية التي يؤجر عليها أن يأمره بالمعروف وينهاه عن المنكر، كما قال : وَإِذَا قُلْتُمْ فَاعْدِلُوا وَلَوْ كَانَ ذَا قُرْبَى [الأنعام:152] فالواجب على المؤمن أن يتقي الله ويؤدي الحق الذي عليه وإن كان مع القريب، يقول سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا كُونُوا قَوَّامِينَ بِالْقِسْطِ شُهَدَاءَ لِلَّهِ وَلَوْ عَلَى أَنفُسِكُمْ أَوِ الْوَالِدَيْنِ وَالأَقْرَبِينَ إِنْ يَكُنْ غَنِيًّا أَوْ فَقِيرًا فَاللَّهُ أَوْلَى بِهِمَا [النساء:135].\nفالواجب على المؤمن أن ينكر المنكر وأن يأمر بالمعروف مع الأقرباء وغيرهم، وأن ينصح قريبه وغير قريبه، وإذا كان قريبًا له فمن أهم المهمات أن ينصحه وأن يوجهه هذا أعظم من صلته بالمال فإذا كان يصله بالمال ويؤجر على صلة الرحم فكونه يصله بتوجيهه إلى الخير وتعليمه الخير وأمره بالمعروف ونهيه عن المنكر هذا أهم من صلة المال، وهذا ينفعه في الدنيا والآخرة، فليس لهذه المرأة ولا لغيرها أن تدع الأمر بالمعروف والنهي عن المنكر لحبها لولدها أو ابن أخيها أو ابن أختها أو غيرهم بل يجب أن تأمر بالمعروف وتنهى عن المنكر بالطرق التي تراها مفيدة ومجدية، وبالأساليب الحسنة حتى تنجح إن شاء الله في عملها.\nالمقدم: إذًا: من التربية الحسنة من الرأفة بالأبناء إنكار المنكر عليهم ..؟\nالشيخ: نعم.. نعم، لكن بالأساليب التي تراها مفيدة لا بالعنف والشدة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/7056/وجوب-الامر-بالمعروف-والنهي-عن-المنكر-للقريب-والبعيد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_168/16802.mp3","categories":["العالم والمتعلم","تربية الأولاد","الدعوة والدعاة"]},{"id":8971,"question":"أخت لنا من الخبر رمزت إلى اسمها بالحروف (م. م. س) لم تسأل إلا عشرة أسئلة فقط، تسأل في سؤال لها وتقول: قال رسول الله ﷺ: من كانت له ثلاث بنات فصبر عليهن وسقاهن وكساهن كن له حجاباً من النار،  هل يكن حجاباً من النار لوالدهن فقط أم حتى الأم شريكة في ذلك، وإن عندي ولله الحمد ثلاث بنات؟","title":"فضل البنات والصبر على تربيتهن","answer":"الجواب: هذا عام، يقول ﷺ: من ولي ابنتين فأحسن إليهن كن له ستراً من النار، وهكذا لو كن أخوات أو عمات أو خالات ونحو ذلك المعنى واحد، فإذا كان ابنتان أو أختان أو عمتان أو نحو ذلك فإن المعنى واحد إذا أحسن إليهما أو كانوا أكثر من ثنتين كالثلاث والأربع ونحو ذلك من باب أولى، فإنه متى أحسن إليهن فإنه بذلك يستحق الأجر العظيم، وأن يحجب من النار ويحال بينه وبين النار لعمله الطيب، وهذا في المسلمين، هذه من أعمال المسلمين، فالمسلم الذي يعمل هذه الخيرات يكون قد تسبب في نجاته من النار، والنجاة من النار ودخول الجنة لها أسباب كثيرة فينبغي للمؤمن أن يستكثر منها، فالإسلام نفسه هو السبب الوحيد هو الأصل هو الأساس في دخول الجنة والنجاة من النار.\nوهناك أعمال إذا عملها المسلم موعود بالجنة والنجاة من النار، مثل من رزق بنات أو أخوات فأحسن إليهن كن له ستراً من النار، مثل من مات له أفراط لم يبلغوا الحنث كانوا له حجاباً من النار، قال النبي ﷺ: من مات له ثلاثة أفراط كانوا له حجاباً من النار، قالوا: يا رسول الله! أو اثنين؟ قال: أو اثنين، ولم يسألوه عن الواحد، وجاء عنه ﷺ أنه قال: يقول الله : ما لعبدي المؤمن جزاء إذا أخذت صفيه من أهل الدنيا فاحتسبه إلا الجنة.\nفبين سبحانه وتعالى أن ليس لعبده المؤمن عنده جزاء إذا أخذ صفيه يعني: محبوبه من أهل الدنيا فصبر واحتسب إلا الجنة، فالواحد من ذلك يدخل في هذا، الواحد من أولاده إذا أخذه الله قبضه فاحتسب وصبر فله الجنة، فهذا فضل عظيم، هكذا زوجته وهكذا أخوه وهكذا أبوه إلى غير ذلك. نعم.\nالمقدم: بارك الله فيكم، وجه هذا الإحسان، أو وجوه هذا الإحسان لو تكرمتم؟\nالشيخ: الوجوه كثيرة، فيكون من ذلك: الإحسان إلى البنات بتربيتهن التربية الإسلامية وتعليمهن وإرشادهن، والحرص على عفتهن أو بعدهن عما حرم الله من التبرج وغيره، تربية الأخوات كذلك، أو الأولاد الذكور كذلك إلى غير ذلك من وجوه الإحسان حتى يتربى الجميع على طاعة الله ورسوله والبعد عن محارم الله والقيام بحق الله سبحانه وتعالى.\nالمقدم: بارك الله فيكم، إذاً ليس هو المقصود الأكل والشرب والكسوة فقط؟\nالشيخ: الدين أعظم. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7129/فضل-البنات-والصبر-على-تربيتهن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_146/14604.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":9255,"question":"أفيدونا عن حكم المربيات من غير المسلمات ولاسيما إذا ظهر منهن نقل لغاتهن وطباعهن وطريقة ملابسهن إلى الطفل والطفلة، نرجو التوجيه في هذا الأمر الذي عمت به البلوى وأصبح يتألم لوجوده كل مؤمن ومؤمنة؟","title":"حكم استقدام المربيات غير المسلمات","answer":"الجواب: الأطفال أمانة، الأطفال أمانة عند أبيهم وأمهم، فالواجب أن لا يتولى تربيتهم إلا من هو يؤمن بالله واليوم الآخر ويرجى منه الفائدة لهم والتوجيه الطيب، أما أن يتولى الأطفال نساء كافرات هذا منكر ولا يجوز، وإذا كان في الجزيرة العربية صار منكراً من جهتين:\nمن جهة أنهن يربين أطفالاً مسلمين وهذا خيانة للأمانة.\nومن جهة أن الجزيرة العربية لا يجوز أن يستدعى فيها كافر أو يقيم فيها كافر.\nبل الواجب أن لا يقر فيها إلا مسلم؛ لأن الرسول ﷺ أمر بإخراج المشركين وأوصى بذلك من هذه الجزيرة، فلا يجوز لأهل الجزيرة أن يستقدموا الكفرة للتربية أو للعمل؛ لأنهم ممنوعون من هذا، فإذا استقدمت المربية من النصارى أو غير النصارى كـالبوذية أو غير البوذية من الكفرة هذا لا يجوز لأمرين:\nأحدهما: أن هذا خيانة للأمانة، فالتربية أمانة، والأطفال أمانة، فلا يجوز أن يربي الأطفال إلا مؤمنة تقية يرجى فيها الخير حتى لو كانت مسلمة إذا كانت فاجرة خبيثة لا ينبغي أن تولى على الأطفال ولو كانت مسلمة إذا كانت رديئة الدين ضعيفة الدين.\nالأمر الثاني: أن هذه الجزيرة لا يجوز أن يستقدم لها غير المسلم، فلا يستقدم عمال كافرون ولا خادمات كافرات ولا مربيات كافرات هذا هو الواجب على المؤمنين أن يحذروا ذلك؛ لأن الرسول ﷺ أوصى بإخراج المشركين من هذه الجزيرة، ولأن هذه الجزيرة مهد الإسلام ومنبع الإسلام فلا يجوز أن يجتمع فيها دينان بل يجب أن يكون السائد فيها هو دين الحق هو الإسلام فقط، ويجب على ولاتها وعلى سكانها أن يحذروا جلب الكفار إلى هذه الجزيرة إلا من ضرورات قصوى يراها ولي الأمر لنفع المسلمين في أشخاص معينين. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7417/حكم-استقدام-المربيات-غير-المسلمات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_153/15304.mp3","categories":["تربية الأولاد"]},{"id":9366,"question":"أخت لنا من السودان بعثت برسالة مطولة وضمنتها اثني عشر سؤالًا متنوعة من أحد أسئلتها: تقول: لي أربعة أطفال، أكبرهم في السابعة من عمره، كانت أمنيتي قبل أن يرزقني الله بهم إن كانت لي ذرية سأحاول بقدر الإمكان تعليمهم أمور الدين وتهيئة الجو الإسلامي لهم، وفعلًا أخذت أعلمهم ومنهم من يحفظ كثيرًا من القرآن الكريم والأحاديث حتى القصص لا يعلمون غير قصص الأنبياء، ولم أدخل عليهم أي جهاز من الأجهزة الحديثة كالمسجل أو الفيديو أو ما أشبه ذلك، إلا أنهم يعيشون في جو غريب تمامًا، وبدءوا يستنكرون كل ما عدا ما في منزلنا أو كل ما عدا ما يسمعون منا، وبدءوا يعيشون في شيء من الازدواجية وترجو التوجيه جزاكم الله خيرًا؟","title":"نصيحة في تربية الأبناء","answer":"الجواب: قد أحسنت في تعليمهم وتوجيههم، وعليك أن تكملي أنت ووالدهم وإخوتهم الكبار وغير ذلك من أقاربهم، عليكم أن تلاحظوهم حتى لا يضرهم ما حولهم من المجتمع، أنت على خير، وأبوهم على خير في التعليم والتوجيه والإرشاد والتربية الإسلامية، ولكن لابد من اختلاطهم بمن حولهم، فعليكم بالحرص عليهم وتوجيههم إلى الخير، وتحذيرهم مما قد يسمعون من الباطل، أو يشاهدون من الباطل حولهم حتى لا يتأثروا به، والله جل وعلا هو الموفق الهادي، وإنما عليكم أن تفعلوا المستطاع: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] وأنتم على خير إن شاء الله وسوف ينفع الله بجهودكم. نعم.","link":"https://binbaz.org.sa/fatwas/7530/نصيحة-في-تربية-الابناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_186/18606.mp3","categories":["تربية الأولاد","نصائح وتوجيهات","الهبة والعطية","فتاوى متنوعة"]},{"id":9731,"question":"السائلة أم مريم تقول: لي مجموعة من الأولاد الصغار ويكثرون من اللعب، هل يجوز الدعاء على الأولاد في مثل هذه الحالة؟","title":"واجب الأم تجاه أولادها","answer":"الجواب: إذا كان أولادك فيهم بعض الشر كاللعن والشتم والمخاصمة ... بينهن، هذا جاهديهم بالتوجيه والإرشاد والنصيحة والتأديب واسألي الله أن الله يهديهم، اسألي الله أن الله يهديهم جل وعلا، ولا تقنطي ولا تيئسي، اسألي الله لهم الهداية وعلميهم وهكذا أبوهم وهكذا أخوهم الكبير وهكذا جدهم ينصحهم ويؤدبهم إذا رأى التأديب حتى يستقيموا، لا تقنطي أبداً. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7886/واجب-الام-تجاه-اولادها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_272/27220.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":9911,"question":"هذه رسالة رمز السائل بـ (ع. ع. ع) المنصورة يقول: والدي قد بلغ من العمر ما يقارب من اثنين وخمسين عام، يحافظ على الصلوات المكتوبة في أوقاتهن.الشيخ: أعد أعد.المقدم: يقول هذا السائل: والدي بلغ من العمر ما يقارب من الثانية والخمسين يحافظ على الصلوات المكتوبة في أوقاتهن ولكنه كثير المزاح مع الناس ومع الغير صالحين والفاسدين بالفواحش والمنكر، فهذا يغضبني ويجعلني لا أملك نفسي فأقوم بتوجيهه في نفس الوقت وأمام هؤلاء الناس وهؤلاء الفاسدين بأسلوب متشدد جدًا، فمثلًا أقول له: بأن هذا الكلام لا يقوله إلا الفاسد والفاسق ولو مت يا أبي على هذه الحالة ستلقى الله وهو عليك غضبان، ولا أطيل عليكم فقد كنت متشدد معه مع خوفي عليه من غضب الله؟ فماذا أفعل لو كان أسلوبي هذا يغضب الله وجهوني مأجورين؟","title":"مشروعية الرفق بالوالد عند توجيهه ونصيحته","answer":"الجواب: المشروع لك -يا أخي- الرفق والدعوة إلى الله بالحكمة والأسلوب الحسن، ولا سيما مع والدك، الله يقول جل وعلا: فَقُولا لَهُ قَوْلًا لَيِّنًا [طه:44] لما أرسل موسى وهارون إلى فرعون لَعَلَّهُ يَتَذَكَّرُ أَوْ يَخْشَى [طه:44] ويقول الله سبحانه لنبيه محمد ﷺ: فَبِمَا رَحْمَةٍ مِنَ اللَّهِ لِنْتَ لَهُمْ وَلَوْ كُنْتَ فَظًّا غَلِيظَ الْقَلْبِ لانْفَضُّوا مِنْ حَوْلِكَ [آل عمران:159] ويقول الله سبحانه: ادْعُ إِلَى سَبِيلِ رَبِّكََ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125] فنوصيك بالرفق بوالدك ومخاطبته بالأسلوب الحسن بينك وبينه حتى يهديه الله، عليك بالكلام الطيب والأسلوب الحسن والرفق في نصيحته وتوجيهه إلى الخير، سواء كان عند الناس أو بينك وبينه نسأل الله أن يهديه وأن يعيذه من الشيطان.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8079/مشروعية-الرفق-بالوالد-عند-توجيهه-ونصيحته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_273/27323.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":10476,"question":"بماذا تنصحون الذين يصطحبون أطفالهم إلى المسجد يوم الجمعة، فيشغلون المصلين بالكلام واللعب والخطيب على المنبر؟","title":"حكم اصطحاب الأطفال إلى المسجد يوم الجمعة","answer":"الجواب: الطفل الذي دون السبع ينبغي أن يبقى عند أهله حتى لا يشغل الناس، ينبغي أن يبقى عند أهله حتى لا يحصل به إيذاء للناس، أما إذا كان الطفل قد كمل السبع فأكثر فهذا يصلي مع الناس؛ لأن الرسول ﷺ أمر الأولياء بأمرهم بالصلاة قال: مروا أبناءكم بالصلاة لسبع واضربوهم عليها لعشر، فعلى آبائهم وعلى إخوانهم الكبار أن يخرجوا بهم إلى الصلاة، وأن يوجهوهم ويؤدبوهم إذا آذوا الناس ويمنعوهم، حتى يستقيموا على الطريق السوي، وحتى يصلوا مع الناس من دون أذى.","link":"https://binbaz.org.sa/fatwas/8651/حكم-اصطحاب-الاطفال-الى-المسجد-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_281/28103.mp3","categories":["صلاة الجمعة","تربية الأولاد"]},{"id":10557,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من جمهورية مصر العربية، وباعثها أحد المستمعين من هناك هو: محمد عثمان، الأخ محمد له أكثر من سؤال، في سؤاله الأول يقول: إن جدي -رحمه الله- قسّم تركته قبل وفاته على والدي وعمي وعمتي، وهو عبارة عن أطيان زراعية، ولم يعط عمتي حقها الشرعي في تلك الأراضي، فما حكم الإسلام في ذلك؟ وماذا يجب عليّ فعله الآن، وما الحكم في المدة السابقة، وهي تزيد عن عشر سنوات؟","title":"العدل بين الأولاد في الوصية","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فلا ريب أن الواجب على جدك أن يعدل في الورثة والتقسيم، وأن يكون أولاده على قسمة الله: لِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ [النساء:11]، في الهبة، وفي الإرث، ولقد ثبت عن رسول الله عليه الصلاة والسلام أنه قال لبشير بن سعد الأنصاري لما وهب ابنه النعمان غلاماً قال له ﷺ: أكل ولدٍ أعطيته مثل هذا؟، قال: لا، قال: اتقوا الله، واعدلوا بين أولادكم، فدل ذلك على أن يجب على الوالد العدل في عطيته لأولاده، فيكون لأبيك ولعمك أربعة أسهم، ولعمتك سهمين، هكذا يجب لِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ، إن كانت عمتك سمحت لأخويها وهي مرشدة، سمحت لهم بحقها فلا حرج، وإلا فلها الحق في المطالبة في حقها لدى المحكمة، والله -جل وعلا- نسأله أن يوفق الجميع.\nالمقدم: اللهم آمين، جزاكم الله خيراً، المدة السابقة الحكم فيها لو تكرمتم؟\nالشيخ: هذا إلى المحكمة، إذا كانت ما سمحت العمة، فالمحكمة تنظر في الأمر في حقها، وفيما فات عليها في هذه المدة.\nالمقدم: يعني إن كان هناك محاصيل زراعية، أو ما أشبه؟\nالشيخ: كلها، تنظر المحكمة.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8731/العدل-بين-الاولاد-في-الوصية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_322/32201.mp3","categories":["تربية الأولاد","الهبة والعطية"]},{"id":10791,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين هو: (خ. ن. ج) أخونا يقول: ألاحظ يا سماحة الشيخ! أن هناك كثيراً من الآباء قد أهملوا تربية أبنائهم مما أعاد عليهم بأمور سيئة للغاية، لذلك فإني أطلب من سماحتكم أن تتفضلوا بتوجيه الآباء كيما يهتموا كثيراً بأبنائهم ولا سيما في هذا الزمان جزاكم الله خيراً؟","title":"نصيحة وتوجيه للآباء وبيان واجبهم في تربية أبنائهم","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فهذا الذي ذكره السائل جدير بالعناية؛ لأن مراعاة الأولاد ذكوراً وإناثاً والعناية بهم وتربيتهم الإسلامية أمر من أهم المهمات، يقول النبي الكريم عليه الصلاة والسلام: كلكم راع وكلكم مسئول عن رعيته، فالرجل راع في أهل بيته ومسئول عن رعيته، والأمير -الذي على الناس- راع ومسئول عن رعيته، والمرأة راعية في بيت زوجها ومسئولة عن رعيتها، والخادم راع في مال سيده ومسئول عن رعيته، ثم قال: ألا فكلكم راع وكلكم مسئول عن رعيته خرجه الإمام البخاري في الصحيح وغيره.\nفهذا الحديث العظيم يدل على وجوب العناية بالرعية، وأعظم مسئول في ذلك الإمام الذي على الناس، وهو أمير المسلمين وسلطانهم، يجب عليه أن يرعاهم من كل ما فيه صلاحهم، وسلامة دينهم ودنياهم، والعناية بكل ما ينفعهم في الدنيا والآخرة، حسب الطاقة والإمكان، وأعظم ذلك العناية في الدين، حتى يستقيموا عليه، وحتى يلتزموا به، وذلك بأداء الواجبات وترك المحارم، كما يجب على كل وال على الناس أن يحكم فيهم شريعة الله، وأن يلزمهم بشرع الله، وألا يحكم فيهم غير شرع الله، وهو مسئول عن ذلك كما قال جل وعلا: فَوَرَبِّكَ لَنَسْأَلَنَّهُمْ أَجْمَعِينَ [الحجر:92] عَمَّا كَانُوا يَعْمَلُونَ [الحجر:93]، وكما في هذا الحديث الصحيح: كلكم راع وكلكم مسئول عن رعيته، فالأمير الذي على الناس راع ومسئول عن رعيته نسأل الله أن يوفق ولاة أمر المسلمين لكل ما فيه صلاحهم وصلاح المسلمين جميعاً.\nوهكذا كل إنسان مسئول عن أهل بيته، فالأب مسئول عن أولاده، والأم مسئولة عن أولادها، من جهة تربيتهم الإسلامية، وأمرهم بالمعروف، ونهيهم عن المنكر وإلزامهم بالحق، وتركهم ما خالف شرع الله ومن ذلك أمر الصلاة، فإنها عمود الإسلام، فالواجب على الأب أن يعتني بأولاده وهكذا الأم، حتى يستقيموا على الصلاة وحتى يحافظوا عليها في بيوت الله مع المسلمين، يقول الله : حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى [البقرة:238] ويقول سبحانه: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَارْكَعُوا مَعَ الرَّاكِعِينَ [البقرة:43] ويقول جل وعلا: يَا أَيُّهَا الَّذِينَ آمَنُوا قُوا أَنفُسَكُمْ وَأَهْلِيكُمْ نَارًا وَقُودُهَا النَّاسُ وَالْحِجَارَةُ [التحريم:6] والوالدان داخلان في هذا يَا أَيُّهَا الَّذِينَ آمَنُوا قُوا أَنفُسَكُمْ وَأَهْلِيكُمْ نَارًا وَقُودُهَا النَّاسُ وَالْحِجَارَةُ [التحريم:6].\nوالعناية بأمر الصلاة من أسباب الوقاية من النار، للوالد والولد جميعاً، وقال تعالى يخاطب نبيه عليه الصلاة والسلام: وَأْمُرْ أَهْلَكَ بِالصَّلاةِ وَاصْطَبِرْ عَلَيْهَا [طه:132] ويقول عليه الصلاة والسلام: مروا أبناءكم بالصلاة لسبع، واضربوهم عليها لعشر، وفرقوا بينهم في المضاجع.\nفالولد ذكراً كان أو أنثى يؤمر بالصلاة إذا بلغ سبعاً، ويضرب عليها إذا بلغ عشراً؛ لأنه بهذا قد ناهز الاحتلام وقارب، وإذا بلغ وجبت عليه عيناً وفرضاً واستحق بذلك إذا تركها أن يستتاب فإن تاب وإلا قتل من جهة ولي الأمر، فالأمر عظيم، فالواجب على الآباء والأمهات وإخوان الأولاد الكبار وأعمامهم التعاون في هذا الأمر، وأن يجتهدوا في إصلاح الأولاد وتربيتهم التربية الإسلامية، ومن ذلك إلزامهم بالصلاة، وأمرهم بها إذا بلغوا سبعاً، وضربهم عليها إذا بلغوا عشراً وقصروا في ذلك.\nوهكذا يؤمرون بما أمر الله به من بر الوالدين، وحفظ اللسان عن السب والشتم والكذب، وعن غير هذا من المعاصي، وعن غير هذا مما حرم الله ، وهكذا يمنعون من شرب المسكرات والتدخين، حتى لا ينشئوا على هذا الباطل، فيجب على الآباء والأمهات العناية بالأولاد لما ينفعهم في الدنيا والآخرة وعليهم أن يمنعوهم مما حرم الله  حتى ينشئوا نشأة صالحة وحتى يستقيموا على دين الله، فإذا بلغوا فإذا هم قد عرفوا ما يجب عليهم وما يحرم عليهم، وقد تربوا على الخير وعلى ترك الشر، ولأبيهم وأخيهم وأمهم ومن سعى في هذا الخير له مثل أجورهم، كما قال النبي الكريم عليه الصلاة والسلام: من دل على خير فله مثل أجر فاعله وهذا من فضل الله ، نسأل الله للجميع التوفيق والهداية، نعم.\nالمقدم: اللهم آمين، جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8964/نصيحة-وتوجيه-للاباء-وبيان-واجبهم-في-تربية-ابناىهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_351/35101.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":10818,"question":"رسالة وصلت إلى البرنامج من الرياض باعثها المستمع مسفر فهد سعيد القحطاني يقول: هناك عمارة من دورين اشتراها الوالد بمبلغ مائة وثلاثين ألف ريال، وتقبلت الصندوق العقاري بمبلغ مائة وثلاثة وعشرين ألف ومائتين وثمانية وتسعين، وهذا كان في حياة الوالد، وقد توفي قبل ثلاث سنوات، وقد أعطاني تلك العمارة، وأخبر إخواني الخمسة بذلك وأختين، وكان لديهم علم بذلك، ولم يعارض منهم أحد، وهو على قيد الحياة، حسب علمي، وأظن أن الوالد أعطاني العمارة حبًا لي، وليس تفضيلًا على إخواني وأخواتي، والآن أريد أن أبرئ ذمتي في هذا الموضوع، هل يجوز لي أن أمتلك تلك العمارة؟ مع العلم أنهم وقعوا على ورقة أنهم راضين بذلك، وليس لديهم مانع بعد وفاته؛ لأن العمارة باسم شخص ثاني، ولم تنقل ملكيتها، وهي مسجلة باسمي في الصندوق العقاري، وإنما أخشى أن يكون أحدهم غير راضٍ من قلبه، وهل يلحق والدي ذنب؟ أفتونا مأجورين، جزاكم الله خير الجزاء.","title":"حكم هبة الوالد شيئاً لأحد أولاده برضى البقية","answer":"الجواب:  إذا كان الواقع كما ذكرته فلا حرج، إذا كانوا مرشدين، ورضوا بذلك فلا حرج عليك، والحمد لله، وجزاهم الله خيرًا، القلوب إلى الله  ما دام صدقوا على ذلك، ورضوا بذلك، ولم يعارضوا فلا حرج عليك، إن شاء الله، نعم. المقدم: وفيما يخص والده؟ الشيخ: ولا حرج على والدك، ما دام سامحوه ورضوا، الحمد لله. نعم. المقدم: الحمد لله، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8992/حكم-هبة-الوالد-شيىا-لاحد-اولاده-برضى-البقية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_354/35403.mp3","categories":["تربية الأولاد","الهبة والعطية"]},{"id":10824,"question":"رسالة وصلت إلى البرنامج من الرياض باعثها المستمع مسفر فهد سعيد القحطاني يقول: هناك عمارة من دورين اشتراها الوالد بمبلغ مائة وثلاثين ألف ريال، وتقبلت الصندوق العقاري بمبلغ مائة وثلاثة وعشرين ألف ومائتين وثمانية وتسعين، وهذا كان في حياة الوالد، وقد توفي قبل ثلاث سنوات، وقد أعطاني تلك العمارة، وأخبر إخواني الخمسة بذلك وأختين، وكان لديهم علم بذلك، ولم يعارض منهم أحد، وهو على قيد الحياة، حسب علمي، وأظن أن الوالد أعطاني العمارة حبًا لي، وليس تفضيلًا على إخواني وأخواتي، والآن أريد أن أبرئ ذمتي في هذا الموضوع، هل يجوز لي أن أمتلك تلك العمارة؟ مع العلم أنهم وقعوا على ورقة أنهم راضين بذلك، وليس لديهم مانع بعد وفاته؛ لأن العمارة باسم شخص ثاني، ولم تنقل ملكيتها، وهي مسجلة باسمي في الصندوق العقاري، وإنما أخشى أن يكون أحدهم غير راضٍ من قلبه، وهل يلحق والدي ذنب؟ أفتونا مأجورين، جزاكم الله خير الجزاء.","title":"حكم هبة الوالد شيئاً لأحد أولاده برضى البقية","answer":"الجواب:  إذا كان الواقع كما ذكرته فلا حرج، إذا كانوا مرشدين، ورضوا بذلك فلا حرج عليك، والحمد لله، وجزاهم الله خيرًا، القلوب إلى الله  ما دام صدقوا على ذلك، ورضوا بذلك، ولم يعارضوا فلا حرج عليك، إن شاء الله، نعم. المقدم: وفيما يخص والده؟ الشيخ: ولا حرج على والدك، ما دام سامحوه ورضوا، الحمد لله. نعم. المقدم: الحمد لله، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8992/حكم-هبة-الوالد-شيىا-لاحد-اولاده-برضى-البقية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_354/35403.mp3","categories":["تربية الأولاد","الهبة والعطية"]},{"id":11188,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من خميس مشيط، باعث الرسالة مستمع يقول: أخوكم في الله علي القحطاني الأخ علي له قضية يقول فيها: إن لي إخوانًا ولله الحمد متعلمين، ولكنهم عند الصلاة لا يهتمون بها، ويصلون وهم يلعبون بالصلاة، وعندما أفرغ من الصلاة آمرهم بإعادة الصلاة فيرفضون ويهربون، وعندما أضربهم على ذلك تغضب الوالدة، فبماذا أتخلص من هذه المشكلة، علمًا بأن أصغرهم عمره عشر سنوات، وأكبرهم خمس عشرة سنة؟","title":"كيفية تربية الصغار الذين يلعبون في الصلاة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه أما بعد.  فالواجب عليك هو ما فعلت من تأديبهم والقيام عليهم؛ لقول النبي ﷺ: مروا أبناءكم بالصلاة لسبع، واضربوهم عليها لعشر فإذا كان الوالد غير موجود فأنت في محل الوالد، وإن كان الوالد موجودًا.  فالواجب عليه أن يقوم بهذه المهمة، وعلى الوالدة أن تساعد في ذلك ولا تغضب، عليها أن تساعد في ذلك، وأن تعينك على هذا الأمر، وأن تتكلم عليهم وتزجرهم عن ذلك، حتى تكون معك في هذا الأمر؛ لأن الله جل وعلا يقول: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2] فلا بد من التعاون بينك وبين الوالدة على البر والتقوى، وعليك أن تشرح لها الأمر بالعبارة الحسنة، والأسلوب الحسن، وأن هذا شيء واجب، حتى تعلم الحق وتستجيب للحق إن شاء الله. المقدم: جزاكم الله خيرًا، وأحسن إليكم سماحة الشيخ! هل تنصحونه باصطحابهم إلى المسجد حتى يتأدبوا بآداب المصلين أيضًا؟ الشيخ: إذا تيسر اصطحابهم هذا طيب، وإلا فالواجب سوقهم إلى المسجد سواء معه وإلا قبله وإلا بعده، لا بد من حضورهم صلاة الجماعة، يصلون مع الناس في المساجد ولو بالضرب، ولو بالرفع إلى الهيئة إذا دعت الحاجة إلى الهيئة، حتى يساعدوه على ذلك؛ لأن هذا أمر لازم، أما الصلاة في البيت فلا، لا يصلون في البيت، بل يجب أن يصلوا مع الناس ويجب عليه أن يقوم عليهم بما يستطيع، من الضرب والتوبيخ وغير ذلك. نعم. المقدم: جزاكم الله خيرًا من كان له أبناء لكنهم لا يهتمون بالصلاة في المساجد، وتعب مع أولاده والحال كما ذكر، هل تنصحونه أيضًا بمراجعة الجهات المختصة؟ الشيخ: مثل ما تقدم، مثل ما تقدم إذا عجز يرفع الأمر للهيئة، تساعده الهيئة في ذلك.  المقدم: بارك الله فيكم، جزاكم الله خيرًا. الشيخ: نسأل الله السلامة. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/9356/كيفية-تربية-الصغار-الذين-يلعبون-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_372/37201.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":11244,"question":"هذا السائل -يا سماحة الشيخ- أيضًا يسأل في سؤاله الثاني ويقول: ما حكم الأب الذي لم يعدل بين أبنائه، ثم يكتب الأرض التي يملكها باسم زوجته حتى يحرم الابن الذي من زوجة أخرى من كل شيء، فما هي الحقوق التي على الابن الآخر المحروم تجاه والده، وبماذا تنصحون الأب مأجورين؟","title":"حكم الأب الذي لم يعدل بين أبنائه","answer":"الجواب: الواجب على الأب العدل بين الأولاد، كما قال النبي ﷺ: اتقوا الله واعدلوا بين أولادكم فالواجب عليه العدل بين الذكور والإناث في قسمة الميراث لا يخص أحدًا دون أحد، بل إذا أعطاهم أعطاهم جميعًا كالميراث، وإذا حرمهم حرمهم جميعًا، أما أن يخص أحدًا بعطية فلا يجوز، أو يتحيل ويعطي أمه وقصده للولد أو البنت فلا يجوز. أما إذا خص الزوجة بشيء ليس حيلة؛ تقديرًا لجهودها وأعمالها الطيبة فلا بأس، أما أن يفعل تحيلًا يكتب باسم الزوجة وهو قصده قد تواطأ معها على أنه للولد فهذا لا يجوز، الحيل التي تحرم ما أحل الله أو تحل ما حرم الله كلها باطلة، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/9425/حكم-الاب-الذي-لم-يعدل-بين-ابناىه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_291/29125.mp3","categories":["تربية الأولاد","الهبة والعطية"]},{"id":11306,"question":"تقول: إخوتي ثلاثة الصغير عمره ستة عشر عامًا، ووالدنا متوفى، وإخوتي لا يصلون ووالدتي تعبت منهم، فقد عملت معهم الكثير.الشيخ: أعد، لا حول ولا قوة إلا بالله.المقدم: إخوتي ثلاثة الصغير عمره ستة عشر عامًا، ووالدنا متوفى، وإخوتي لا يصلون، ووالدتي تعبت منهم، فقد عملت معهم الكثير لنصحهم، ماذا تفعل والدتي أرجو أن تدعو لإخواني ولجميع شباب المسلمين بالهداية؟ جزاكم الله خيرًا.","title":"موقف أم توفي زوجها تجاه أبناء لا يصلون","answer":"الجواب:  نسأل الله لهم الهداية والصلاح، نسأل الله أن يهديهم ويعيذهم من الشيطان، نسأل الله أن يعينك وأمك على جهادهم، والواجب نصيحتهم والحرص على إقامتهم الصلاة، والواجب ... منهم ولو أن ضربتهم الوالدة، أو ترفع بأمرهم إلى الهيئة هيئة الأمر بالمعروف حتى يساعدوها في ذلك، لأن هذا الأمر لا يسكت عنه هذا الأمر خطير. فالواجب أن ينصحوا ويوجهوا من الوالدة وغير الوالدة فإن استقاموا وإلا يرفع بأمرهم إلى الهيئة حتى يعاقبوا العقوبة الرادعة، نسأل الله لنا ولهم الهداية، نسأل الله أن يهديهم ويردهم إلى الصواب. نعم.  المقدم: اللهم آمين جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9484/موقف-ام-توفي-زوجها-تجاه-ابناء-لا-يصلون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_376/37616.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":11439,"question":"ما هي نصيحتكم للأب والأم والمدرسة في تربية الأبناء؟","title":"نصيحة للآباء والأمهات والمدرسين حول تربية الأبناء","answer":"الجواب:  النصيحة للجميع أن يوجه الأبناء إلى طاعة الله، وأن يعلموا الأخلاق الفاضلة، والكلمات الطيبة، وأن ينصحوا في طلب العلم والتفقه في الدين، والمحافظة على الصلاة، وعلى حسن الخلق مع الوالدين، ومع الأقارب، ومع الزوار والضيوف، وعلى الوالد والوالدة أيضًا أن يكونا مثالًا صالحًا لأولادهم في الأخلاق الفاضلة، والمحافظة على الصلاة في الجماعة، والحذر من المحرمات كالمسكرات، والدخان، وحلق اللحية، وأشباه ذلك. على الوالد أن يكون مثالًا طيبًا لأولاده في سيرته الطيبة، وفي محافظته على الصلاة في الجماعة، وفي توفير لحيته، وفي اجتنابه المعاصي، وهكذا الأم، كل منهما عليه أن يكون مثالًا طيبًا في الأخلاق الفاضلة، والأعمال الصالحة، والحذر من المعاصي، نسأل الله للمسلمين الهداية. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9621/نصيحة-للاباء-والامهات-والمدرسين-حول-تربية-الابناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_294/29416.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":11675,"question":"تقول أيضًا في سؤال آخر: شخص أهدى إلى والدته هدية من ذهب، ومع مرور الزمن احتاج هذه الهدية، فأخذها من والدته، فما الحكم؟","title":"حكم من أهدى لوالدته ذهباً ثم أخذه منها لحاجته إليه","answer":"الجواب:  إذا رضيت والدته وأعطته الهدية، وليس له إخوان، أو له إخوان رضوا، إخوان مكلفون مرشدون ورضوا؛ لا بأس، أما إذا كان له إخوان صغار، أو لم يرضوا؛ فليس له أن يأخذها، بل تكون للجميع، لأن الرسول ﷺ يقول: اتقوا الله، واعدلوا بين أولادكم؛ لأنها ملكتها، فليس له أن يأخذها وحده، بل عليها أن توزع الهدية بينه وبين إخوته، إلا أن يسمحوا إذا كانوا مرشدين، فلا بأس إذا سمحوا، وإلا فعليها أن تمسك لا تعيدها إليه. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9858/حكم-من-اهدى-لوالدته-ذهبا-ثم-اخذه-منها-لحاجته-اليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_390/39007.mp3","categories":["تربية الأولاد","الهبة والعطية"]},{"id":11787,"question":"بعد هذا رسالة مطولة بعث بها أحد الإخوة يقول: أخوكم في الله (ب. ع. ز)، أخونا رسالته مطولة جدًا، ملخص ما في هذه الرسالة أن والده تزوج، وأنجب من الزوجة الجديدة، وحينئذ أصبح لا يعاملهم معاملة الأب الحنون على أبنائه.الشيخ: أعد.المقدم: يقول: إن أباه تزوج، وأنجب من المرأة الجديدة، وحينئذ تغيرت مشاعره نحو أبنائه القدامى، وأصبح لا ينظر إليهم نظرة الأب الحنون، ويرجو من سماحة الشيخ توجيه هذا الأب بالذات وتوجيه أمثاله، ولاسيما أنهم يصفونه بالإهمال حتى لبنت معوقة عمرها ثنتا عشرة سنة، جزاكم الله خيرًا؟","title":"حكم إهمال الوالد لأولاده بعذر زواجه من ثانية","answer":"الجواب: الواجب على الوالد والوالدة العدل بين أولادهم في كل شيء؛ لقول النبي ﷺ: اتقوا الله، واعدلوا بين أولادكم فالواجب على الأب أن يعدل في عطيته، وفي ملاحظته، وفي إنفاقه، وفي حسن خلقه، عليه أن يعدل في الجميع ذكورًا وإناثًا، والأم كذلك، هذا هو الواجب على الجميع؛ لقول النبي ﷺ: اتقوا الله، واعدلوا بين أولادكم وهذا عام يعم العدل في النفقة والعطية، وغير ذلك؛ ولأن عدم العدل يسبب الشحناء والعداوة والبغضاء، وتلك عواقبها وخيمة، نسأل الله للجميع الهداية.  المقدم: اللهم آمين، سماحة الشيخ! لو تفضلتم.. في الواقع أن مما أساء إلى تعدد الزوجات تصرف بعض الناس مثل هذا التصرف أطمع في هذا البرنامج بكلمة من سماحة الشيخ حتى لا يسيء الناس إلى شريعة الله بسوء تصرفاتهم. جزاكم الله خيرًا؟ الشيخ: الواجب على من تزوج زوجتين، أو ثلاثًا، أو أربعًا أن يعدل، وأن يتحرى العدل بين زوجاته، وبين أولاده جميعًا، فالله سبحانه حين شرع التعدد شرع أيضًا العدل، وأمر بالعدل، يقول النبي ﷺ لما كان يقسم بين نسائه: اللهم هذا قسمي فيما أملك؛ فلا تلمني فيما تملكك، ولا أملك. وكان يقسم، ويعدل -عليه الصلاة والسلام- فهذا هو الواجب على الرجل أن يعدل بين زوجاته، وبين أولاده، ويتحرى العدل في ذلك، وما عجز عنه، ولم يستطعه؛ فالله لا يكلف نفسًا إلا وسعها فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9971/حكم-اهمال-الوالد-لاولاده-بعذر-زواجه-من-ثانية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_422/42204.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":11991,"question":"يقول: إن كثيرًا من الآباء لا ينصحون أبناءهم لتأدية الصلاة، فهل يأثم الأب؟","title":"حكم الوالد الذي لا يأمر أولاده بالصلاة","answer":"الجواب:  نعم يأثم الأب الذي لا يأمر أولاده بالصلاة؛ يأثم، وهكذا أخوهم، وهكذا عمهم وخالهم وأمهم، كلهم يأثمون إذا تركوا الأمر بالمعروف والنهي عن المنكر واجب، فيجب عليهم الأمر بالمعروف والنهي عن المنكر، وهو من واجب المؤمنين، والله يقول سبحانه: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71] ويقول النبي ﷺ: من رأى منكم منكرًا؛ فليغيره بيده، فإن لم يستطع؛ فبلسانه، فإن لم يستطع؛ فبقلبه وهم يقدرون الكلام، يعني: يقدرون الإنكار بالكلام، فالأم تنكر، والأب والأخ الكبير والعم والخال وغيرهم، فهذا من باب التعاون على البر والتقوى، الله يقول -سبحانه-: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَىى [المائدة:2] ويقول سبحانه: وَالْعَصْرِ ۝ إِنَّ الإِنسَانَ لَفِي خُسْرٍ ۝ إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ [العصر:1-3] لابد من التعاون على البر والتقوى، ولاشك أن الإنكار على من ترك الصلاة؛ من باب التعاون على البر والتقوى، من باب الدعوة إلى الله  نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم سماحة الشيخ؛ إذا تعب الأب في هذا الموضوع، ولم يستجب الأبناء الاستجابة المرجوة، فهل يطردهم من البيت؟ الشيخ: يطردهم وإلا يرفع أمرهم إلى ولاة الأمور حتى يأدبوا، فإذا لم يتيسر ذلك؛ يطردهم من بيته، يطردهم حتى تسلم ذمته، تبرأ ذمته -نسأل الله العافية- إلا إذا استطاع تأديبهم من جهة ولاة الأمور، نعم. المقدم: إذا خشي أن يقعوا في مصائب أخرى، سماحة الشيخ؟ الشيخ: ما عاد أكبر من الكفر، الكفر هو أعظم الذنوب الكفر، نسأل الله العافية. المقدم: الله المستعان، نسأل الله العافية، إذًا ليس بعد الكفر ذنب؟ الشيخ: نعم هو أعظم الذنوب. المقدم: نسأل الله العافية والسلامة.","link":"https://binbaz.org.sa/fatwas/10176/حكم-الوالد-الذي-لا-يامر-اولاده-بالصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_431/43105.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":12828,"question":"هل من يعطي الأولاد مبلغًا من المال من أجل أن يواظبوا على الصلوات والتهليل والتكبير لله سبحانه، هل هذا العمل جيد ومشروع؟","title":"حكم إعطاء الأولاد النقود لأجل المواظبة على الصلوات وغيرها","answer":"الجواب:  لا حرج في ذلك إذا كان ليس حيلة لتفضيل بعضهم على بعض، إنما هو لأجل تشجيعهم على الخير، فهذا في الغالب يكون.. شيء يسير ويعفى عنه؛ لأن هذا من باب التشجيع على الخير والمعاونة عليه، أما إذا كان عطايا لها أهمية يفضل بعضها على بعض لا، أما إذا كان أشياء طفيفة للتشجيع؛ فلا بأس -إن شاء الله- نعم. المقدم: إن شاء الله، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11042/حكم-اعطاء-الاولاد-النقود-لاجل-المواظبة-على-الصلوات-وغيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_463/46316.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":12849,"question":"الأخت (ل. ع. ف) من مدينة القصب بعثت تقول: ما رأيكم يا سماحة الشيخ في الأب الذي يربي أولاده وهم صغار تربية جيدة، ولكن إذا نضجوا، وبلغوا سن الرجولة، وتزوجوا، فإنه يهملهم، ولا يبدي لهم النصح، ولا يتابع أحوالهم، ولا سيما ما يتعلق بحياتهم الإسلامية، هل تنقطع تربية الوالد إلى أن يبلغ الأبناء سن النضج، ويتزوجوا، أم هي متصلة؟","title":"حكم إهمال الأب توجيه أولاده بعد تزويجهم","answer":"الجواب:  بل هي متصلة، والواجب عليه أن يتقي الله في ذلك، وأن يلاحظهم، وأن يوجههم إلى الخير إذا استطاع ذلك، أما إذا لم يستطع بأن كانوا في بلاد أخرى، وهو عاجز لا يصلونه، ولا يتصلون به؛ فإنه يعمل ما يستطيع ولو بالهاتف، ولو بالمكاتبة حسب الطاقة: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] ولا يجوز له أن يهملهم أبدًا، بل يجب عليه أن يرشدهم ولو بطريق الهاتف، ولو بطريق المكاتبة، ولو بطريق البرقية، أي طريق يستطيعه يفعله، ولا يجوز له إهمالهم؛ لأنهم أولاده، وهو مسؤول عنهم يوم القيامة. لكن إذا كانوا صغارًا، المسؤولية تكون أشد، وإذا كبروا وانفصلوا عنه، كانت المسؤولية أخف: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] عليه أن يتقي الله ما استطاع في ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11064/حكم-اهمال-الاب-توجيه-اولاده-بعد-تزويجهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_464/46415.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":12895,"question":"يقول: فتاة غير متزوجة، لا تصلي يقول لها والدها: صلي فلا تطيعه، ولا تعمل بما يقول: فعلى من تقع مسؤولية هذه الفتاة، جزاكم الله خيرًا؟","title":"كيفية تصرف الوالد مع ابنة تاركة للصلاة","answer":"الجواب: على والدها وعلى إخوتها، عليهم أن يقوموا عليها ولو بالضرب، حتى تستقيم، وحتى تصلي، فإن لم تستقم؛ يرفع بأمرها إلى المحكمة، تستتاب، فإن تابت وإلا قتلت، يرفع أمرها إلى المحكمة الشرعية، فإن تابت، وهداها الله؛ فالحمد لله، وإلا وجب قتلها؛ لأن من ترك الصلاة؛ يستتاب، فإن تاب؛ وإلا قتل من جهة ولي الأمر، والمحكمة تنوب عن ولي الأمر. ولا يجوز لأبيها السكوت عنها، ولا لإخوتها، ولا لأعمامها، على الجميع أن يقوموا عليها؛ لعل الله أن يهديها بأسبابهم، مع الضرب لا مانع أن يضربها أبوها، يضربها إخوتها ضربًا يسبب رجوعها عن الباطل، ولعل الله أن يهديها بذلك، فإن لم يجد ذلك؛ وجب أن يرفع أمرها إلى المحكمة حتى تجري عليها الحكم الشرعي، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11110/كيفية-تصرف-الوالد-مع-ابنة-تاركة-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_467/46710.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":12927,"question":"في سؤاله الثاني يقول يا سماحة الشيخ: إذا كان بعض من إخواني -سواء كانوا ذكورًا أو إناثًا- يقصرون في بعض الصلوات، هل هذا يؤثر على والدي المتوفى، علمًا بأن بعض الإناث متزوجات؟","title":"حكم الأب الذي لم ينصح أبناءه في أمور دينهم","answer":"الجواب:  إن كان قصر في حياته لم يأمر أبناءه وبناته، ولم يعلمهم؛ فهو على خطر من ذلك، والدعاء له، تدعو له أن الله يسامحه ويعفو عنه. أما إن كان لم يقصر، بل اجتهد في تربيتهم وتعليمهم، وأمرهم بالخير، ولكن قصروا بعد وفاته هم؛ فالإثم عليهم، وليس عليه من ذلك شيء. إذا قصروا بعد وفاته في الصلاة، أو غيرها؛ فالإثم عليهم، لكن في حياته إذا كان قد تساهل في حقهم؛ فهو على خطر، تدعون له بالمغفرة والرحمة والعفو، إذا كان تساهل معهم، ولم يعلمهم، ولم يؤدبهم؛ فقد ترك الواجب عليه، فهو مسؤول عن هذا، وهو خطر من هذا الشيء، لكن تدعون له بالمغفرة والرحمة والعفو. وعليكم أيضًا أن تتواصوا بالخير فيما بينكم، وأن تناصحوا، وأن تجتهدوا في أداء حق الله، وأن تحافظوا على الصلاة في الجماعة، وأن تجتهد مع أخواتك أيضًا بنصيحة أخواتك، وتوجيههن إلى الخير، وأمرهن بالصلاة والمحافظة عليها في أوقاتهاـ وغير هذا من وجوه الخير، كأداء الزكاة، وصوم رمضان، والمحافظة عليه، صلة الرحم، إكرام الجار، حفظ اللسان عما لا ينبغي، توصي جميع إخوتك من ذكور وإناث بتقوى الله، توصيهم بطاعة الله ورسوله، توصيهم بفعل الخير، وترك الشر، توصيهم بكثرة التسبيح والتهليل والتحميد والتكبير والذكر وقراءة القرآن، توصيهم بإكرام جيرانهم، وإكرام أقاربهم، وصلة أرحامهم، وأنت على خير. يقول الله : وَالْعَصْرِ  ۝  إِنَّ الإِنسَانَ لَفِي خُسْرٍ  ۝  إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ [العصر:1-3] من أفضل خصال الإيمان التواصي بالحق والتناصح، ويقول -جل وعلا-: ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ[النحل:125] ويقول سبحانه: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى وَلا تَعَاوَنُوا عَلَى الإِثْمِ وَالْعُدْوَانِ[المائدة:2]. فأنت -أيها السائل- عليك أن تتعاون مع إخوانك، ومع أقربائك، ومع جيرانك على البر والتقوى، على طاعة الله ورسوله، على الصلاة في الجماعة، على بر الوالدين، على صلة الرحم، على حفظ اللسان عما لا ينبغي، كل هذا من التناصح والتواصي بالحق، نعم. المقدم: جزاكم الله خيرًا يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11143/حكم-الاب-الذي-لم-ينصح-ابناءه-في-امور-دينهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_501/50102.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":13062,"question":"تقول السائلة في آخر أسئلتها: أحيانًا أقوم بالدعاء على أبنائي الصغار، وذلك لكثرة مشاغبتهم داخل المنزل، فهل دعاء الأم مستجاب؟ مع العلم بأنني أندم فورًا، والسلام عليكم.","title":"حكم الدعاء على الأبناء","answer":"الجواب:  يخشى من الاستجابة، ينبغي الحذر، ينبغي أن لا تدعي عليهم إلا بالخير، فاحذري الدعاء عليهم بالشر، جاهدي النفس، لا بد من جهاد حتى يكون الدعاء طيبًا لا سيئًا، وأبشري بالخير، لا بد من الصبر، ولا بد من جهاد النفس حتى يكون الدعاء طيبًا لا ضارًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11279/حكم-الدعاء-على-الابناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_505/50522.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":13140,"question":"لها سؤال طويل أيضًا تقول: إن والدها لا يهتم بإخوانها من حيث الصلاة، وإنها تصلي بهم من أجل تعويدهم، وأحيانًا تصلي بهم وإن كانت معذورة شرعًا، لئلا تبين لهم عذر النساء، فما رأيكم؟","title":"ما واجب الآباء نحو الأبناء في الصلاة، وحكم إمامة المرأة؟","answer":"الجواب:  الواجب على أبيهم العناية بهم، إن كانوا ذكورًا يلزمهم بالصلاة مع الجماعة في المساجد، ولو بالضرب حتى يستقيموا، لقوله ﷺ: مروا أبناءكم بالصلاة لسبع، واضربوهم عليها لعشر، وفرقوا بينهم في المضاجع فالوالد مسؤول عن أولاده، وعليه أن يجتهد في إقامتهم الصلاة، وصلاتهم مع الناس في المساجد حتى يعتادوها، ويستقيموا عليها. أما إن كان الأولاد بنات؛ فإنه أيضًا يقوم عليهن، ويلزمهن بالصلاة، ويؤدبهن إذا تكاسلوا عن الصلاة. أما أنت فلا مانع من أن تصلي بهن إذا كن بنات، تعلمينهن، وتقفي وسطهن، وتعلمينهن الصلاة؛ لأنهن بنات، أما الأولاد لا، الذكور يلزمهم الخروج إلى المسجد، وليس للمرأة أن تصلي بهم، المرأة لا تصلي بالرجال، ولكن تقومين عليهم، وتوجهينهم إلى الصلاة في المسجد، ولو بالتوبيخ إذا دعت الحاجة إلى ذلك، ولو بالضرب إذا كنت الكبيرة وهم الصغار إذا أهملهم أبوهم، ولا تصلي بهم، لا تصلي أنت بهم إذا كانوا ذكورًا، ولكن تأمرينهم وتجاهدينهم حتى يصلوا في الجماعة، وتشجعين الوالد على القيام عليهم، وتطلب منه العناية بهم، من باب التعاون على البر والتقوى. أما البنات فلا بأس أن تصلي بهن وتعلمينهن حتى يعتدن ذلك، والإمامة تكون وسط النساء، لا قدامهن. أما أن تصلي بهم وأنت في الحيض لا يجوز هذا، هذا منكر، ليس لك أن تصلي بهن وأنت حائض، أو نفساء، ولو قصدت الخير، ليس لك هذا، بل الحائض لا تصلي، ولا تستعمل أعمال الصلاة توهم الصلاة، ولا تصلي وهي نفساء، ويحرم عليها هذا العمل، هذا شر عظيم، ومنكر -نسأل الله السلامة- نعم. المقدم: جزاكم الله خيرًا، بالنسبة للمعلم إذا أراد أن يعلم الصبيان وهو على غير وضوء، يجوز له ذلك سماحة الشيخ، يعلمهم كيفية الصلاة، لكنه على غير وضوء؟ الشيخ: ما هو بهذه الصلاة، يعلم يقول: الركوع كذا، والسجود كذا، ما في بأس. المقدم: لا بأس بهذا. الشيخ: لا يصلي بهم على أنها صلاة. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11394/ما-واجب-الاباء-نحو-الابناء-في-الصلاة-وحكم-امامة-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_474/47415.mp3","categories":["حكم الصلاة وأهميتها","تربية الأولاد"]},{"id":13375,"question":"يقول السائل: يهتم البعض من الآباء والأمهات بغذاء أبنائهم وبناتهم، ويغفلون عن تربيتهم التربية الإيمانية السليمة القائمة على حب الله ورسوله، وقراءة القرآن، والتأدب بآداب الإسلام، ما كلمتكم يا سماحة الشيخ؟","title":"وجوب الاهتمام بالتربية الإيمانية للأولاد","answer":"الجواب: الواجب على كل مؤمن ومؤمنة العناية بالآداب الشرعية، والغذاء الشرعي، أما الغذاء البدني هذا شأن البهائم، الواجب أن تكون العناية بتوجيه الأولاد إلى الخير، وإرشادهم إلى أسباب النجاة، وتعليمهم الأخلاق الفاضلة، والسيرة الحميدة، وترغيبهم في قراءة القرآن الكريم، والاستفادة من القرآن والتدبر، وترغيبهم في صحبة الأخيار، ومجالسة الأخيار، هذا أهم شيء، إصلاح دينهم أهم شيء من إصلاح أبدانهم، فالغذاء يتعلق بصلاح الأبدان، وتعليمهم ما ينفعهم في الدنيا والآخرة، وتوجيههم إلى الخير، وإرشادهم إلى أسباب النجاة، هذا يتعلق بنجاتهم في الدنيا والآخرة، ويتعلق بصلاح القلوب وهذا أهم. فالواجب على الأقارب جميعًا أن يهتموا بما فيه صلاح القلوب، والاستقامة على شرع الله، وأن يعلموا أولادهم، وأيتامهم، وقراباتهم ما ينفعهم في الدنيا والآخرة، وما يرضي الله عنهم، ويشجعوهم على تعلم القرآن الكريم، والعناية بالقرآن وحفظه، والإكثار من تلاوته، وحضور مجالس الذكر وحلقات العلم، وعليهم أن يوصوهم أيضًا بصحبة الأخيار، والبعد عن صحبة الأشرار، كل هذه أمور تتعلق بصلاح القلوب، وصلاح الدين، وصلاح أمر الآخرة. أما ما يتعلق بالغذاء البدني، والكسوة، ونحوها هذا أمر ثانوي، لا مانع من العناية به، ولكنه أمر ثانوي، أمر الدين أهم وأعظم، نسأل الله للجميع الهداية. المقدم: اللهم آمين، جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11665/وجوب-الاهتمام-بالتربية-الايمانية-للاولاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_525/52502.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":13430,"question":"تقول السائلة في آخر أسئلتها (ب. ع. ش) من الإسكندرية من مصر: أبي يمنعنا من زيارة أقاربنا مثل: الخال، والخالة، والعمة، والأصدقاء، ويكاد يكون يحاسبنا في المنزل، ويسمح لنا بالذهاب لدور العلم فقط، ما رأيكم بذلك سماحة الشيخ؟","title":"توجيه لمن يمنعهن والدهن من زيارة أقاربهن","answer":"الجواب: الوالد قد يكون له رأي سديد في منعكم من الزيارة من الخالة والخال ونحو ذلك؛ لأن زيارتهم قد تجر عليكم شرًا، قد يكون الخال غير مضبوط، قد تكون الخالة غير مضبوطة، يخاف عليكم من شر هذه الزيارات، والدليل على هذا أنه يسمح لكم بزيارة دور العلم حتى تستفيدوا، فهذا يدل على أنه إنما منعكم خوفًا عليكم من هذه الزيارات، فإذا كان الخال، أو الخالة، أو العم، والعمة من أهل الصلاح والخير؛ فهو سوف لا يمنعكم، فأنتم تبحثون معه الموضوع الذي يمنعكم منه، واعرفوا أسباب المنع. فالوالد لا يتهم، يحب لأولاده الخير، فإذا منعكم من شيء؛ فالأصل وجوب طاعته؛ لأنه ناصح لولده، محب لولده الخير، فطاعته من طاعة الله، فإذا اتضح أنه نهاكم عن شيء فيه مصلحة لكم، وفيه خير، فالتفاوض معه، والبحث معه بالكلام طيب، والأسلوب الحسن؛ حتى يتضح الأمر، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11726/توجيه-لمن-يمنعهن-والدهن-من-زيارة-اقاربهن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_516/51611.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":13447,"question":"من الأردن السائل محمد أحمد القرارعة يقول في هذا  كيف للأب أن يعلم ابنه المعاق سمعيًا، ونطقيًا للصلاة سماحة الشيخ؟","title":"كيفية تعليم الولد الأصم الأبكم الصلاة","answer":"الجواب: يعلمه بالطريقة التي يفهمها، إذا كان لا يسمع فإنه يريه إياه بالعمل، يصلي وهو معه، يركع معه، ويسجد معه، ويرفع معه، وإن كان لا يبصر، ولكنه يسمع يصلي معه، ويسمعه التكبير الركوع والرفع من الركوع، وهكذا حتى يفهمه كيف السجود، كيف الركوع، كيف الرفع.. إلى آخر الصلاة. المقصود: يفهمه بالطريقة التي يفهمها.. بالسمع.. بالفعل.. باللمس، الشيء الذي يستطاع. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11744/كيفية-تعليم-الولد-الاصم-الابكم-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_527/52716.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":13531,"question":"آخر أسئلة في رسالة هذه السائلة سماحة الشيخ تقول السائلة: والدي متزوج من امرأتين، فجدي لأبي قبل أن يتوفاه الله أوصى ببيت لنا، وبيت لإخواني من أبي، فهل يجوز لوالدي أن يتصرف في البيت الذي هو ملكنا بأن يغير في بناياته، مع العلم أنه يغيره إلى الأحسن؛ لأن أحد إخواني قد عارض ذلك وقال: لا يجوز لوالدي أن يتصرف في ملكنا؟ وجهونا في ضوء هذا السؤال.","title":"وجوب العدل بين الأبناء","answer":"الجواب: لا مانع، يتصرف بتحسين ما يخصكم، لكن بشرط أن يعطي إخوانكم مثله، لابد من العدل؛ لأن الرسول ﷺ يقول: اتقوا الله واعدلوا بين أولادكم فإذا كان بيتكم يحتاج إلى ألف ريال، ألفين، ثلاثة؛ فلابد يعطي إخوانكم من أبيكم مثل ذلك؛ لأن عليه أن يعدل بينكم، وإلا فلا يجوز له يخصكم بشيء في إصلاح بيتكم، ولا يعطي إخوانكم إلا برضاهم إذا كانوا مرشدين ورضوا، أما إذا كانوا مرشدين ولم يرضوا؛ فليس له أن يخصكم بشيء، لا من جهة إصلاح البيت، ولا من جهة غيره، لابد من العدل. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11855/وجوب-العدل-بين-الابناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_532/53203.mp3","categories":["تربية الأولاد","الهبة والعطية"]},{"id":13735,"question":"امتدادًا للسؤال السابق سماحة الشيخ هذا السائل يقول في سؤاله -وهو قريب من السؤال السابق-: كثير من أولياء الأمور هداهم الله لا يحرصون على حث أولادهم على أداء الصلوات المفروضة، فهم يتساهلون كثيرًا معهم في ذلك، هل من كلمة سماحة الشيخ حول هذا الموضوع؟الشيخ: أعد.المقدم: يقول: كثير من أولياء الأمور -هداهم الله- لا يحرصون على حث أولادهم، وبناتهم على أداء الصلوات المفروضة، فهم يتساهلون في ذلك، فهل يأثمون في ذلك؟","title":"ما النصيحة في حث الأولاد على الصلاة؟","answer":"الجواب: نعم، الواجب على جميع المسلمين العناية بالصلاة، وتوجيه أولادهم إليها، الواجب على الآباء والأمهات والإخوة العناية بهذا الأمر، الأب يوجه أولاده، والأم كذلك، والأخ الكبير والعم.. كلهم يتعاونون على البر والتقوى؛ لأن الله يقول: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2] ويقول سبحانه: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71] ويقول -جل وعلا-: وَالْعَصْرِ [العصر:1] إِنَّ الإِنسَانَ لَفِي خُسْرٍ [العصر:2]، إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ [العصر:3] إذا تساهلوا يأثمون. الله -جل وعلا- يقول: وَأْمُرْ أَهْلَكَ بِالصَّلاةِ وَاصْطَبِرْ عَلَيْهَا [طه:132] ويقول : يَا أَيُّهَا الَّذِينَ آمَنُوا قُوا أَنفُسَكُمْ وَأَهْلِيكُمْ نَارًا وَقُودُهَا النَّاسُ وَالْحِجَارَةُ [التحريم:6]، ويقول -جل وعلا-: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71] ويقول : كُنْتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِالْمَعْرُوفِ وَتَنْهَوْنَ عَنِ الْمُنكَرِ [آل عمران:110].  فالواجب على الآباء والأمهات والإخوة وغيرهم التعاون في هذا، وأن يستقيموا على الحق، وأن يلزموا أولادهم بالصلاة، والمحافظة عليها، وأن يؤدبوا من تخلف. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12106/ما-النصيحة-في-حث-الاولاد-على-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_545/54519.mp3","categories":["تربية الأولاد","حكم الصلاة وأهميتها"]},{"id":13872,"question":"هذا السائل يقول الذي رمز لاسمه بـ (أ . أ) يقول: كيف يكون العدل بين الأولاد وخاصة بأنني متزوج من زوجتين؟","title":"كيفية العدل بين أولاد الزوجات","answer":"الجواب: كل جماعة يعطون حقوقهم، العدل فيهم أن تعطيهم حقوقهم، فالاثنان لهم شيء والثلاثة لهم شيء والأربعة لهم شيء، فإذا كان أولاد الزوجة إحدى الزوجات اثنين، وأولاد الأخرى ثلاثة أربعة كل يعطى حقه، كل يعطى حقه، وهكذا الزوجة الثالثة والرابعة تعطيهم النفقة اللازمة.\nأما العطايا التي غير النفقة فلابد من العدل فيها، تعطيهم شيء زائد على النفقة لابد من العدل؛ لقول النبي ﷺ: اتقوا الله واعدلوا بين أولادكم أما النفقة فعلى حسب الحاجة الأولاد الكثير لهم نفقة والقليل لهم نفقة، والصغير له نفقة والكبير له نفقة، يختلفون في كسوتهم وفي غير ذلك، نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12292/كيفية-العدل-بين-اولاد-الزوجات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_506/50620.mp3","categories":["النفقات","الهبة والعطية","تربية الأولاد"]},{"id":13886,"question":"هذا السائل يقول الذي رمز لاسمه بـ (أ . أ) يقول: كيف يكون العدل بين الأولاد وخاصة بأنني متزوج من زوجتين؟","title":"كيفية العدل بين أولاد الزوجات","answer":"الجواب: كل جماعة يعطون حقوقهم، العدل فيهم أن تعطيهم حقوقهم، فالاثنان لهم شيء والثلاثة لهم شيء والأربعة لهم شيء، فإذا كان أولاد الزوجة إحدى الزوجات اثنين، وأولاد الأخرى ثلاثة أربعة كل يعطى حقه، كل يعطى حقه، وهكذا الزوجة الثالثة والرابعة تعطيهم النفقة اللازمة.\nأما العطايا التي غير النفقة فلابد من العدل فيها، تعطيهم شيء زائد على النفقة لابد من العدل؛ لقول النبي ﷺ: اتقوا الله واعدلوا بين أولادكم أما النفقة فعلى حسب الحاجة الأولاد الكثير لهم نفقة والقليل لهم نفقة، والصغير له نفقة والكبير له نفقة، يختلفون في كسوتهم وفي غير ذلك، نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12292/كيفية-العدل-بين-اولاد-الزوجات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_506/50620.mp3","categories":["النفقات","الهبة والعطية","تربية الأولاد"]},{"id":13960,"question":"تسأل أختنا وتقول: هل يجوز أن أخص أولادي الذكور ببعض أثاث المنزل والأجهزة، مثل: الثلاجات والمسجلات والأشياء المعمرة..الشيخ: أعد أعد!!المقدم: تقول: هل يجوز أن أخص أولادي الذكور ببعض أثاث المنزل والأجهزة، مثل: الثلاجات والمسجلات والأشياء المعمرة؛ كي تكون ملكًا لهم بعد وفاتي؛ لأن البنات سبق وأن جهزتهن، هل هذا جائز أو لا؟","title":"حكم تخصيص الذكور بشيء دون الإناث","answer":"الجواب: ليس لك ولا لغيرك تخصيص الذكور بشيء دون البنات، بل الواجب التعديل بين الجميع؛ لقول النبي ﷺ: اتقوا الله واعدلوا بين أولادكم، فلا يجوز لك أن توصي للبنين بشيء دون البنات، إلا إذا كن رشيدات ورضين بذلك؛ فلا حرج في ذلك، والأحوط عدم الوصية للبنين ولو رضي البنات؛ لأنهن قد يرضين حياء منك، وهن في الحقيقة لا يرضين بذلك، فالأحوط لك أن لا تخصي البنين بشيء أبدًا، حتى ولو فرضنا أن البنات رضين بذلك، لأني أخشى أن يرضين بذلك مكرهات أو مستحيات، بل اجعلي ما خلفك للجميع على قسمة الله : لِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ [النساء:11]. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12381/حكم-تخصيص-الذكور-بشيء-دون-الاناث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_605/60505.mp3","categories":["تربية الأولاد","الهبة والعطية"]},{"id":14065,"question":"المستمع أنيس يحيى من مدينة الدوادمي بعث يسأل ويشكو من سوء معاملة أبيه، فهو يقول: إن له أخًا أكبر منه، وقد زوجه أبوه وأعطاه سيارة لكنه لم يفعل به مثل ما فعل بأخيه رغم نصح الناس له، ثم إنه أعطاه قطعة أرض فتصرف فيها وباعها، وسلم الثمن للوالد، ثم طلب والده ثمن تلك الأرض فأبى أن يعطيه، ويسأل سماحة الشيخ كيف يتصرف؟ وهل إذا ذهب إلى المحكمة هل يكون آثمًا؟ وجهوه ووجهوا والده جزاكم الله خيرًا.","title":"ما حكم عطية بعض الأولاد دون الآخرين؟","answer":"الجواب: الواجب على الوالد أن يعدل، ولا يجوز أن يخص بعض الأولاد بعطية أو زيادة على بقية الأولاد هذا لا يجوز؛ لأن الرسول عليه السلام قال: اتقوا الله واعدلوا بين أولادكم، هذا كلام المصطفى عليه الصلاة والسلام، اتقوا الله واعدلوا بين أولادكم، ولما جاءه بشير بن سعد الأنصاري  وذكر له أنه أعطى ابنه النعمان غلامًا، قال له النبي ﷺ: أعطيت ولدك كلهم مثله؟ ، قال: لا، قال: رده، اتقوا الله واعدلوا بين أولادكم، فليس له أن يعطي بعضهم سيارة أو مالًا أو أرضًا ولا يعطي الآخرين لا، بل إما أن يسوي بينهم في العطاء وإما أن يرجع في عطيته، هذا هو الواجب عليه. وأنت أيها الولد! لو توسطت بعض الطيبين من الأقارب أو غيرهم حتى يصلحوا بينك وبين الوالد يكون هذا حسنًا إن شاء الله، أحسن من الذهاب إلى المحكمة، إن تيسر من يشير على والدك وينصحه حتى يلتزم بالحق، وحتى يعدل فهذا حسن، وهذا أولى من المخاصمة، فإن أبى فلك أن تخاصمه إلى المحكمة، لك أن تخاصمه لأجل أنه قد ظلم، ولا بد من تعديل من جار عن الطريق، لا بد أن يعدل ويلزم بالحق من طريق المحكمة، وإن سمحت أنت ولم تخاصمه فأنت مأجور، نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12487/ما-حكم-عطية-بعض-الاولاد-دون-الاخرين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_484/48406.mp3","categories":["تربية الأولاد","نصائح وتوجيهات","الهبة والعطية"]},{"id":14469,"question":"ما هو رأي سماحتكم في اصطحاب الأطفال إلى المسجد، وهل هذا حرام أم مكروه أم جائز؟علمًا بأني أسمع على ألسنة كثير من الناس حديثًا -يقولون: إنه مروي عن رسول الله ﷺ: جنبوا المساجد صبيانكم ومجانينكم؟","title":"حكم اصطحاب الأطفال إلى المساجد","answer":"الجواب: يستحب، بل يشرع الذهاب بالأولاد إلى المساجد إذا بلغ الولد سبعًا فأعلى، ويضرب عليها إذا بلغ عشرًا؛ لأنه بذلك يتأهل للصلاة، ويعلم الصلاة حتى إذا بلغ فإذا هو قد عرف الصلاة واعتادها مع إخوانه المسلمين. أما الأطفال الذين دون السبع، فالأولى ألا يذهب بهم؛ لأنهم قد يضايقون الجماعة، ويشوشون على الجماعة، ويلعبون، فالأولى عدم الذهاب بهم إلى المسجد؛ لأنه لا تشرع لهم الصلاة. وأما حديث: جنبوا المساجد صبيانكم فهو حديث ضعيف، لا يصح عن النبي ﷺ، بل يؤمر الصبيان بالحضور للصلاة إذا بلغوا سبعًا فأكثر، حتى يعتادوا الصلاة، كما قال النبي ﷺ: مروا أبناءكم بالصلاة لسبع، واضربوهم عليها لعشر، وفرقوا بينهم في المضاجع فهذا فيه تشجيع للمؤمنين أن يحضروا أولادهم معهم، حتى يعتادوا الصلاة، وحتى إذا كانوا بلغوا الحلم قد اعتادوا، حتى إذا بلغوا فإذا هم قد اعتادوها وحضورها مع المسلمين، فيكون ذلك أسهل وأقرب إلى محافظتهم عليها، نعم.","link":"https://binbaz.org.sa/fatwas/12952/حكم-اصطحاب-الاطفال-الى-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_624/62412.mp3","categories":["صلاة الجماعة","تربية الأولاد"]},{"id":14564,"question":"سماحة الشيخ، بعض الآباء في المعاملة يميلون إلى البعض دون الآخرين، ويفرقون بينهم، هل من توجيه للآباء حول ذلك؟","title":"توجيه للأباء الذين لا يعدلون بين أولادهم","answer":"الجواب: الواجب على الآباء والأمهات تقوى الله في أولادهم، والعدل بينهم في النصيحة والتوجيه والإرشاد والتعليم؛ لأنهم جميعًا في الذمة أمانة، فيجب على الوالدين أن يتقوا الله في أولادهم، وأن يجتهدوا في تربيتهم التربية الإسلامية، وأن يحرصوا على الجد في الإحسان إليهم جميعًا، وعدم التخصيص؛ لأنهم جميعًا في الذمة.  فالواجب العناية بهم جميعًا، والحرص على تربيتهم التربية الإسلامية، وإذا كانوا محاويج جميعًا وجب الإنفاق عليهم بحسب حاجتهم إذا كان والدهم قادرًا على ذلك. أما أن يخص بعضهم من غير موجب شرعي، بل بالهوى فلا يجوز، فالواجب تقوى الله والعدل، كما قال النبي ﷺ: اتقوا الله، واعدلوا بين أولادكم. فعلى الأب وعلى الأم العدل، وتحري الحق في تربية الأولاد، والإنفاق على الأولاد وغير ذلك، لكن من عصى الله من الأولاد وعق والديه لا يكون له حق مثل حق من أطاع وبر بوالديه، من عصى والديه وعقهم فهو يستحق العقوبة والتأديب، وليس له حق مثل حق من أطاع وبر، فالعاق يؤدب ويعامل بما يستحق حتى يدع العقوق، وحتى يستقيم على بر والديه، ولا يكون له من الحق مثل حق من بر والديه، واستقام على طاعة الله فيهما. وهكذا من كان غنيًا ليس له حق فيما يعطاه الفقير، إذا كان أحد الأولاد فقيرًا أو مريضًا ليس عنده قدرة على الكسب، وأبوه يستطيع فإنه ينفق عليه، وليس للغني حق في ذلك، بل هذا من أجل الحاجة، فالأب ينفق على ولده الفقير والأم كذلك، ولا يكون جائرًا ولا ظالمًا إذا أنفق على الفقير، وعالج المريض؛ لأنه لا يستطيع، وترك القادر الذي يستطيع عنده المال ينفق على نفسه، ويعالج نفسه فهو مستغن عن والديه بما أعطاه الله من المال. أما الفقير كالطفل والمريض الذي ليس عنده ما يعالج به ونحو ذلك ممن يعجز عن النفقة لفقره أو مرضه أو علة به أو نحو ذلك ليس مثل الصحيح الغني، والله -جل وعلا- يقول سبحانه في كتابه العظيم: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] ويقول -جل وعلا-: لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286] فعلى المؤمن أن يتقي الله في جميع ما يأتي ويذر حسب شرع الله، وعليه أن يحذر الظلم والعدوان في أولاده أو في غيرهم، بل عليه أن يتحرى الحق أو العدل في كل شيء، وفق الله الجميع، نعم. المقدم: اللهم آمين، أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13061/توجيه-للاباء-الذين-لا-يعدلون-بين-اولادهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_556/55602.mp3","categories":["تربية الأولاد","نصائح وتوجيهات","الهبة والعطية","فتاوى متنوعة"]},{"id":14565,"question":"السائلة من جمهورية مصر العربية تقول: هل لنا أن نطالب الأبناء والبنات الذين لم يتجاوزوا الثانية عشرة إذا كانوا مصابين بالإرهاق أو التعب أو مصابين بأحد الجروح أو الكسور، هل لنا أن نوقظهم للصلاة، ونطلب منهم أن يقضوا هذه الصلاة؟","title":"هل يوقظ الأولاد للصلاة إذا كانوا مرضى؟","answer":"الجواب: نعم، يعلمون، ويوقظون للصلاة، ويصلون على حسب أحوالهم؛ لقول النبي ﷺ: مروا أولادكم بالصلاة لسبع، واضربوهم عليها لعشر فيوقظ في وقت الصلاة، ويصلي على حسب حاله، إن استطاع قائمًا صلى قائمًا، وإن عجز صلى قاعدًا، وإن لم يستطع صلى على جنب، كما قال النبي ﷺ لـعمران بن حصين لما مرض: صل قائمًا، فإن لم تستطع فقاعدًا، فإن لم تستطع فعلى جنب، فإن لم تستطع فمستلقيًا هذا هو الواجب على الوالدين مع أولادهم تنفيذًا لأمر النبي -عليه الصلاة والسلام- على حسب الطاقة فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] ولو كان غير بالغ ما دام قد بلغ سبعًا فأكثر، فالذي بلغ السبع ودون العشر يؤمر أمرًا ولا يضرب.  أما إذا بلغ عشرًا فأكثر فإنه يؤمر ويضرب إذا تخلف ويصلي على حسب حاله إذا كان مريضًا، أو به جرح أو نحو ذلك يعلم ويوجه ويصلي على حسب حاله كالبالغ، وفق الله الجميع.","link":"https://binbaz.org.sa/fatwas/13062/هل-يوقظ-الاولاد-للصلاة-اذا-كانوا-مرضى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_556/55603.mp3","categories":["تربية الأولاد","حكم الصلاة وأهميتها"]},{"id":14832,"question":"رسالة من أحد الإخوة المستمعين، هو عماد الدين عبدالقادر فضل الله، من السودان بعث يسأل ويقول: ما مدى صحة الحديث القائل: لا صلاة لجار المسجد إلا في المسجد؟ وإن كان صحيحًا فهل معناه: أن الشخص الذي يجاور مسجدًا لا تقبل له صلاة إلا في المسجد أم ماذا؟أفتونا، بارك الله فيكم.","title":"الحكم على حديث: (لا صلاة لجار المسجد...) ومعناه","answer":"الجواب:  الحديث ضعيف، لا صلاة لجار المسجد إلا في المسجد ضعيف، ولكنه مشهور عن علي ، وقد ثبت عن النبي ﷺ ما يغني عنه، وهو قوله ﷺ: من سمع النداء فلم يأت فلا صلاة له إلا من عذر يعم الجار وغير الجار؛ ولما جاءه رجل أعمى، قال: يا رسول الله، ليس لي قائد يقودني إلى المسجد، فهل لي من رخصة أن أصلي في بيتي؟ قال له ﷺ: هل تسمع النداء بالصلاة؟ قال: نعم، قال: فأجب فإذا كان أعمى ليس له قائد يؤمر بالإجابة فكيف بغيره؟! فالواجب على جميع المكلفين الحضور للصلاة في الجماعة، وأداؤها في المسجد مع الناس، ولا يجوز له التخلف عنها بوجه من الوجوه. ولكن لو تخلف لكسل أو نوم صلاها ويفوته فضل الجماعة، صلاها وتصح، تصح صلاته لكنه يأثم إذا تعمد التأخر يأثم، أما إذا كان مغلوبًا على أمره بنوم أو غيره ليس باختياره، فالله -جل وعلا- يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُم [التغابن:16]. أما إذا كان يتساهل في النوم، ولا يجعل ساعة، ولا من يوقظه، فهذا يؤاخذ بذلك؛ لأنه مفرط فهو آثم بذلك، لكن لو جعل الساعة، أو جعل من يوقظه، ثم لم يسمع الساعة، ولم يتيسر من يوقظه نام الموقظ، فلا حرج عليه، فقد ثبت عن النبي ﷺ «أنه نزل ذات ليلة في السفر في آخر الليل، وأمر بلالًا أن يرقب لهم الفجر، حتى يوقظهم فامتثل بلال، واتكأ على ناقته ينظر الصبح حتى يخبرهم إذا طلع الصبح، فأخذه النوم، ونام معهم، ونام مثلما ناموا، فلم يستيقظوا إلا بعدما مسهم حر الشمس، فلما استيقظوا قال النبي ﷺ لـبلال: أين كنت يا بلال؟! فقال: لقد أخذ بنفسي الذي أخذ بأنفسكم» فلم يعاتبه النبي ﷺ، وتوضؤوا وصلوا، تحولوا عن مكانهم، يقال: إنه موضع حضر فيه الشيطان، ثم توضؤوا وصلوا كما كانوا يصلون في وقتها. فالمقصود: أن الإنسان إذا فعل الأسباب، واجتهد، ثم لم تنفع الأسباب فلا شيء عليه، جعل الساعة، ولكن ما سمعها، أمر زوجته وهي تقوم أو أمه أو أباه، ولكن قدر أنهم تلك الليلة ما قاموا فلا حرج عليه، لكن بشرط: أن لا يكون مصيف، أما إذا كان يتعمد الصيفة فهو مفرط، المصيف يشتد به النوم، ولا يستمع ما يسمع صوت الساعة. فالحاصل: أنه لا بد من فعل الأسباب، ومنها أن يبكر بالنوم لا يسهر.\nالمقدم: المصيف معناه: المتأخر سماحة الشيخ؟ الشيخ: هو المتأخر الذي يتأخر عن النوم، نعم. فالحاصل: إن الواجب على المؤمن أن يفعل الأسباب التي تعينه على أن يصلي مع المسلمين في الوقت الفجر وغير الفجر، ومن أشدها الفجر، وهي أشدها على المنافقين أيضًا، فلا يليق بالمؤمن أن يتشبه بأعداء الله المنافقين، بل عليه أن يبكر في النوم، لا يسهر حتى يستيقظ، وعليه مع هذا أن يستعمل الساعة التي يركبها على الوقت، وإذا كان عنده أهل عندهم يقظة في آخر الليل: أم وإلا خالة وإلا زوجة جيدة تستيقظ، يؤكد عليهم أن يوقظونه، قد لا يسمع الساعة أيضًا فيؤكد عليهم حتى يوقظوه، يفعل الأسباب التي يستطيعها، والله يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13316/الحكم-على-حديث-لا-صلاة-لجار-المسجد-ومعناه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_491/49103.mp3","categories":["تربية الأولاد","الحكم على الأحاديث","صلاة الجماعة"]},{"id":15263,"question":"سماحة الشيخ، تساهل الكثير من الناس في الانصراف عن أطفالهم، يبلغون الحادية عشرة، والثانية عشرة وهم مهملون لهم، هل من توجيه للآباء والأمهات؟","title":"توجيه لمن يهملون أولادهم ولا يحثونهم على الصلاة","answer":"الجواب: نعم، لا يجوز هذا، الواجب على الآباء والأمهات توجيه الأولاد ونصيحتهم، إذا بلغ سبعًا أن يؤمر بالصلاة، والمرأة والبنت تؤمر بالصلاة وتعلم، والولد كذلك يؤمر ويعلم، ويخرج به أبوه أو أخوه إلى المسجد، وإذا بلغ عشرًا يضرب؛ لقوله ﷺ: مروا أولادكم بالصلاة لسبع، واضربوهم عليها لعشر، وفرقوا بينهم في المضاجع هذا هو الواجب، متى بلغ عشرًا فأكثر يؤمر بالصلاة مع الناس، ويضرب إذا تخلف، يضربه أبوه أو أخوه الكبير أو عمه، أما إذا بلغ الحلم، فإنها تجب عليه تكون فريضة، إذا تركها كفر، نسأل الله العافية.  أما ابن سبع وابن ثمان وابن تسع هذا يؤمر ولا يضرب، نعم، الله المستعان. المقدم: الله المستعان، جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13756/توجيه-لمن-يهملون-اولادهم-ولا-يحثونهم-على-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_565/56511.mp3","categories":["تربية الأولاد","نصائح وتوجيهات","الهبة والعطية","فتاوى متنوعة"]},{"id":15381,"question":"هذه السائلة أم حسين، أرسلت بمجموعة من الأسئلة تقول: سماحة الشيخ عبدالعزيز، يقوم بعض الآباء والأمهات والإخوة من باب الحرص والخوف على أبنائهم وبناتهم بالاطلاع والتفتيش على ما لدى أبنائهم من أشياء خاصة، بمعنى: التفتيش والبحث في أمتعتهم وكتبهم وحقائبهم من أجل معرفة أحوالهم وتصرفاتهم وسلوكهم؛ خوفًا عليهم من الفتن وأصحاب السوء، وما إلى ذلك، نسأل الله العافية، فهل يدخل ذلك ضمن الأشياء المحرمة شرعًا؟","title":"حكم تفتيش ما يخص الأبناء لأجل الحرص عليهم","answer":"الجواب: إذا كان هناك أسباب تدعو إلى هذا، فلا بأس من باب الحيطة، وإلا فلا ينبغي سوء الظن بهم. أما إذا كان هناك أسباب يخاف منها، فلا بأس بالتفتيش عند الحاجة؛ خوفًا عليهم من جلساء السوء، ومن دعاة الباطل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13885/حكم-تفتيش-ما-يخص-الابناء-لاجل-الحرص-عليهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_567/56712.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":15536,"question":"سماحة الشيخ، ترديد كلمة مثلًا المرأة تقول لابنها: يا حياتي، يا عمري، ما حكم ترديد مثل هذه العبارات؟","title":"حكم قول الأم لابنها: يا حياتي .. يا عمري","answer":"الجواب: ما أعلم في هذا شيء، من اللطف، والعطف عليه، هذه كلمات ما أعلم فيها شيئًا، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14073/حكم-قول-الام-لابنها-يا-حياتي-يا-عمري","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_569/56926.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":15563,"question":"ما هي أفضل الكتب الإسلامية النافعة التي ترشدوننا -سماحة الشيخ- في تربية الأولاد تربية إسلامية؟ وما هو النهج الصحيح في تربيتهم؟","title":"ما النهج الصحيح في تربية الأولاد؟","answer":"الجواب: النهج الصحيح أن يعلم الأولاد دينهم، حتى قال ﷺ: مروا أولادكم بالصلاة لسبع، واضربوهم عليها لعشر فيعلم دينه، ويعلم التوحيد، ويعلم الصلاة، وهكذا، حتى إذا بلغ السبع يؤمر بها، وإذا بلغ عشر يضرب عليها إذا تخلف، والبنت كذلك، ويعلم الآداب الشرعية في البيت ومع والديه، ومع إخوانه ومع أهل البيت يعلم ولو صغير حتى يستفيد، فالصغير قد يتلقن وينفع، يعلمه يسلم، يعلمه يحترم أمه، يحترم أباه، يعلمونه حتى لا يعبث يكسر شيء، أو يجلب أشياء، أو يفسد أشياء كالبول في الطعام، أو صب التراب على الطعام، أو ما أشبه ذلك، مما قد يقع، يعلم كل ما ينفعه، يعلمه أبوه، ويعلمه أمه، ويعلمه غيرهم من إخوانه الكبار وخالاته وعماته، ونحو ذلك. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14099/ما-النهج-الصحيح-في-تربية-الاولاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_570/57004.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":15628,"question":"يقول السائل: في هذه الأيام يفضل التمييز بين الأبناء، يقول: وهذا يخلق عداوة بين الإخوان فيما بينهم أفيدونا بتوجيه الآباء ونصيحتكم. جزاكم الله خيرًا.","title":"ما النصيحة للآباء في المفاضلة بين الأبناء؟","answer":"الجواب: لا يجوز للآباء تفضيل بعض الأولاد على بعض، لا يجوز لهم ذلك، بل هذا منكر؛ النبي ﷺ لما سأله بشير بن سعد أن يعطي النعمان ولده غلامًا قال: أعطيت ولدك كلهم؟ قال: لا، قال: اتقوا الله واعدلوا بين أولادكم وأراد أن النبي ﷺ يشهد فقال: إني لا أشهد على جور سماه النبي ﷺ جورًا. فالمقصود: أنه لا يجوز للأم ولا للأب التفضيل بين الأولاد، بل يجب التسوية بينهم للذكر مثل حظ الأنثيين، فلا يجوز أن يعطى زيد كذا، ويترك الآخر، لا، بل يجب التعديل بين الأولاد ذكورهم وإناثهم؛ ولهذا في الحديث الآخر: أيسرك أن يكونوا لك في البر سواء؟ قال: نعم، قال: فهكذا؛ لأنه إذا فرق بينهم ساءت أحوالهم، وربما قطعوه أيضًا. فالواجب على الأب والأم والجد والجدة عدم التفضيل، بل يجب العدل للذكر مثل حظ الأنثيين، إذا أعطى الذكر مائة يعطي الأنثى خمسين، وإذا أعطى الرجل ألفًا يعطي الأنثى خمسمائة وهكذا، يجب التعديل؛ لقوله ﷺ: اتقوا الله واعدلوا بين أولادكم ولقوله لـبشير بن سعد الأنصاري لما أراد أن يشهده على عطيته للنعمان وحده قال: إني لا أشهد على جور وقال لـبشير: أيسرك أن يكونوا لك في البر سواء؟ قال: نعم، قال: فلا إذًا يعني: فلا تخص بعضهم، سوِّ بينهم حتى يكونوا كلهم في البر لك سواء، نعم. المقدم: أحسن الله إليكم وبارك فيكم..","link":"https://binbaz.org.sa/fatwas/14169/ما-النصيحة-للاباء-في-المفاضلة-بين-الابناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_571/57111.mp3","categories":["تربية الأولاد","نصائح وتوجيهات","الهبة والعطية","فتاوى متنوعة"]},{"id":15696,"question":"من أسئلة السائل إبراهيم من الرياض، يقول: ما هي حقوق الأبناء على الآباء؟جزاكم الله خيرًا.","title":"حقوق الأبناء على آبائهم","answer":"الجواب: حق الولد على أبيه أن ينفق عليه، مادام صغيرًا، ومادام عاجزًا عن النفقة، ينفق عليه أبوه إذا استطاع، ويؤدبه، ويعلمه ما أوجب الله عليه، وينهاه عما حرم الله عليه، ويكون قدوةً له في الخير، بفعله وقوله.  هكذا يجب على الآباء أن يتقوا الله، وأن يكونوا قدوةً صالحة لأولادهم، وأن يعلموهم، ويوجهوهم إلى الخير، ويؤدبوهم إذا خالفوا الشرع، كما قال النبي ﷺ: مروا أولادكم بالصلاة لسبع، واضربوهم عليها لعشر، وفرقوا بينهم في المضاجع. وإذا كان الولد فقيرًا -والأب غنيًا- وجب عليه أن ينفق عليه، وإن كان كبيرًا، ينفق عليه حتى يوسع الله عليه، ويجد عملًا يستطيع النفقة منه، وأهم شيء العناية بدينه، كونه يعتني بدينه، يوجهه إلى الخير، يأمره بطاعة الله، ينهاه عن محارم الله، يأمره بالصلاة، يأمره بكل ما أمر الله به ورسوله، وينهاه عن كل ما نهى الله عنه ورسوله، ويكون قدوةً أيضًا في أفعاله، يكون الأب قدوة، والأم تكون قدوة في أفعالهما وأقوالهما الطيبة، قدوةً لأولادهما. المقدم: أحسن الله إليكم يا شيخ.","link":"https://binbaz.org.sa/fatwas/14253/حقوق-الابناء-على-اباىهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_573/57305.mp3","categories":["تربية الأولاد","النفقات","الهبة والعطية"]},{"id":15893,"question":"من محافظة مطروح، المستمع محمد علي من جمهورية مصر العربية، رسالة يقول فيها: لي إخوة ذكور وإناث، آمرهم بالصلاة، ولكنهم يتهاونون فيها، فهل عليّ إثم؟ وهل عليّ أن أغير هذا الأسلوب؟ علمًا بأن والدي موجود، وأنا أعتقد أن ولاية الأمر له. جزاكم الله خيرًا.","title":"ما واجب الأب تجاه أبنائه في أمرهم بالصلاة؟","answer":"الجواب: عليك أن تستمر في النصيحة، وأن تشجع الوالد على القيام بما يجب عليه من أمرهم بالمعروف، ونهيهم عن المنكر، وللوالد ضربهم إذا بلغوا العشر فأكثر، كما قال النبي ﷺ: مروا أولادكم بالصلاة لسبع، واضربوهم عليها لعشر فالوالد عليه واجب عظيم أن يعتني بهم، وأن يتكلم عليهم، وينصحهم، ويأمرهم وينهاهم، فإذا لم ينفع الكلام وجب عليه أن يؤدبهم ويضربهم حتى يستقيموا، وعليك أن تكون عونًا له في ذلك بالكلام الطيب، والأسلوب الحسن، فالله يقول -جل وعلا-: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى[المائدة:2] ويقول سبحانه: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ[التوبة:71] ويقول النبي ﷺ: من رأى منكم منكرًا فليغيره بيده، فإن لم يستطع فبلسانه، فإن لم يستطع فبقلبه؛ وذلك أضعف الإيمان.\nفالواجب على الوالد أن يعتني بهذا الأمر إذا كان الأولاد بلغوا عشرًا فأكثر أن يعتني بهم، وأن يؤدب من تخلف، ولو بالضرب الذي يردعه وأمثاله من دون أن يكون فيه خطر، يعني: ضربًا غير مبرح، ضربًا مناسبًا يحصل به المقصود. أما إذا كانوا قد بلغوا الحلم، فالأمر أشد، إذا كانوا قد بلغوا الحلم فالأمر أشد إن لم يستقيموا يرفع أمرهم إلى المحكمة حتى تستتيبهم فإن تابوا وإلا وجب قتل من لم يتب؛ لأن ترك الصلاة كفر أكبر، ومن لم يتب من تركها وجب أن يقتل مرتدًا في أصح قولي العلماء، وإن لم يجحد وجوبها. فالمقصود: أن الأمر عظيم، فعلى الوالد وعليكم أنتم أيها الأولاد أن تساعدوه في نصيحة الأبناء والبنات الذين لا يصلون، وهم قد بلغوا العشر فأكثر، وعلى الوالد أن يعتني بذلك أكثر لأنه المسؤول الأول، وعليه أن يضرب من تخلف الضرب المناسب الذي يحصل به المقصود.  أما إذا بلغوا الحلم فالأمر أشد، يزيد في ضربهم وتأديبهم، وإذا لم يحصل المقصود رفع بأمرهم إلى ولي الأمر إلى المحكمة الشرعية حتى تستتيبهم، فإن تابوا وإلا وجب قتلهم على ترك الصلاة، نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14486/ما-واجب-الاب-تجاه-ابناىه-في-امرهم-بالصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_745/nour_74513.mp3","categories":["تربية الأولاد","حكم الصلاة وأهميتها"]},{"id":15922,"question":"هذه سائلة للبرنامج تقول: أردنية، ومقيمة في تبوك، تذكر بأنها فتاة تقدم لخطبتها منذ أربع سنوات شابين، تقول: أنا وافقت على شخص، وأمي وافقت على الشخص الآخر، باعتباره قريب لنا، وحاولنا إقناعها بأنه سيئ الأخلاق، وأنا كنت موافقة على الشخص الآخر؛ لأنني أريد أن أبتعد عن أهلي، فكانت أمي واقفة عند باب الحمام يوم جمعة عند الظهيرة، فقالت لي: إن شاء الله لا تتزوجين أبدًا، فأنهت الموضوع بالنسبة للشخص الذي أريده من أجل المهر، واكتشفت أمي بعد فترة أن الشخص الذي كانت تريده غير مناسب أخلاقيًا، وقد نسيت أمي هذه الدعوة؛ لأنها من وراء قلبها، وبعد الحادثة كثيرًا ما كانت أمي تدعو مع الأوقات التي تكون فيها الإجابة موجودة بأن يرزقني الله بابن الحلال، فهل تكون الدعوة قد أجيبت يا سماحة الشيخ؟!","title":"نصيحة بالمبادرة في تزويج الأولاد والحذر من الدعاء عليهم","answer":"الجواب: الله أعلم ، لكن نوصيك بالتزوج بالرجل الطيب الصالح، ولو أبت أمك، نوصيك بالرجل الصالح تزوجيه، ولا تبقي عزباء بعدم الزواج، بل نوصيك بأن تجتهدي في الزواج، ونوصي وليك بذلك، لأن الرسول ﷺ يقول: إنما الطاعة في المعروف وما دامت أمك -هداها الله- رجعت عن رأيها، فالحمد لله.  المقصود: إذا خطب الكفء فبادروا بالزواج، يقول النبي ﷺ: إذا خطب إليكم من ترضون دينه وخلقه فزوجوه نسأل الله لك الزوج الصالح، نعم.\nالمقدم: سماحة الشيخ لعل لكم توجيه حول دعاء الآباء على الأبناء في مثل هذه الحالة.\nالشيخ: نوصي جميع المسلمين بالحذر من الدعاء على أولادهم، بل الدعاء لهم بالخير، المشروع للوالد والوالدة الدعاء لهم بالخير، لا عليهم، يشرع للوالد والوالدة الدعاء لأولادهما بالتوفيق والصلاح، ويدعى للرجل بالزوجة الصالحة، والذرية الصالحة، ويدعى للمرأة بالزوج الصالح، والذرية الصالحة، هكذا يجب، وهكذا ينبغي للآباء والأمهات والأقارب أن يتعاونوا على البر والتقوى، وأن يتناصحوا، وأن يدعو كل واحد لأخيه بالخير والصلاح، والعاقبة الحميدة، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14517/نصيحة-بالمبادرة-في-تزويج-الاولاد-والحذر-من-الدعاء-عليهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_577/57712.mp3","categories":["تربية الأولاد","نصائح وتوجيهات"]},{"id":16165,"question":"هذا سائل للبرنامج رمز لاسمه بـ (أ. أ) يقول: عندي اثنان من إخواني لا يصلون، أخلاقهم سيئة مع الجميع، حتى مع الوالد والوالدة، وهم منعزلون عنا، فلا يخالطوننا، وما حكم مقاطعتهم أنا وإخوتي لهم؟ جزاكم الله خيرًا يا سماحة الشيخ.","title":"واجب الأب تجاه من يترك الصلاة من أولاده","answer":"الجواب: إذا كان أخواك لا يصليان؛ فالواجب نصيحتهما، والحرص على توجيههما إلى الخير، وعلى والدك أن يجتهد في نصيحتهما، وأنتم معه أيضًا؛ لعل الله يهديهما بأسبابكم، وإن استطاع أبوك تأديبهما؛ أدبهما، يقول النبي ﷺ: مروا أولادكم بالصلاة لسبع، واضربوهم عليها لعشر فإذا كان ابن عشر يضرب؛ فالكبير يضرب، فإن تاب، وإلا يقتل قتلًا. فإذا كان أبوك الذي لا يستطيع، وأنتم لا تستطيعون؛ ارفعوا الأمر إلى الهيئة، أو إلى المحكمة حتى يقام عليهم أمر الله، فالذي لا يصلي يستتاب، فإن تاب وإلا قتل؛ يقول النبي ﷺ في الحديث الصحيح: بين الرجل، وبين الكفر والشرك ترك الصلاة ويقول ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر ويقول ﷺ: نهيت عن قتل المصلين. فدل على أن من لا يصلي؛ يقتل، والله يقول -جل وعلا-: فَإِنْ تَابُوا وَأَقَامُوا الصَّلاةَ وَآتَوُا الزَّكَاةَ فَخَلُّوا سَبِيلَهُم [التوبة:5]، دل على أن الذي لا يؤدي الصلاة لا يخلى سبيله، بل يقتل، ويقول ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة ويقول ﷺ: رأس الأمر الإسلام، وعموده الصلاة ويقول ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر. المقصود: أن الواجب عليكم، وعلى الوالد العناية بهذا، نصيحتهما، وتوبيخهما، والحرص على هدايتهما، فإن استقاما وإلا ارفعوا أمرهما إلى الهيئة حتى يؤدبا؛ لعلهما يصليان، فإن لم يصليا؛ يرفعا إلى المحكمة حتى يجري عليهما حكم الله بالاستتابة، فإن تابا وإلا قتلا.","link":"https://binbaz.org.sa/fatwas/14829/واجب-الاب-تجاه-من-يترك-الصلاة-من-اولاده","audio":"","categories":["تربية الأولاد","حكم الصلاة وأهميتها"]},{"id":16254,"question":"تقول السائلة: رجل عنده أولاد وبنات، فقام بإعطاء الأولاد مبالغ، وقطع أراضي وهبات، دون أن يعطي البنات، هل يجوز له ذلك؟","title":"وجوب العدل بين الأولاد في العطية","answer":"الجواب: الواجب على الوالد أن يعدل بين أولاده؛ الذكور والإناث، وهكذا الوالدة الأم يجب أن تعدل؛ لأن الرسول ﷺ قال: اتقوا الله، واعدلوا بين أولادكم هكذا قال -عليه الصلاة والسلام-: اتقوا الله، واعدلوا بين أولادكم. فالواجب على الأب إذا أعطاهم أراضي، أو نقودًا، أو إبلًا، أو غنمًا، أو غير ذلك أن يعدل بين الذكور والإناث للِلذَّكَرِ مِثْلُ حَظِّ الْأُنْثَيَيْنِ [النساء: 11] كالإرث، فإذا أعطى الرجل مائة ريال، يعطي البنت خمسين ريالًا، وإذا أعطى الولد عشرة آلاف، يعطي البنت خمسة آلاف.. وهكذا، وإذا أعطى الولد غنمًا، أو إبلًا، أو بقرًا، يعطي البنت مثل ذلك، النصف، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14937/وجوب-العدل-بين-الاولاد-في-العطية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_581/58102.mp3","categories":["تربية الأولاد","الهبة والعطية"]},{"id":16358,"question":"تقول يا سماحة الشيخ هذه الأم السائلة: إذا دعا الشخص على أولاده هل يجاب الدعاء؟","title":"التحذير من الدعاء على الأبناء","answer":"الجواب: على خطر، ينبغي له ألا يدعو، ينبغي أن يدعو بالخير، إذا غضب على أولاده لا يدعو عليهم إلا بالخير، يتقي الله؛ لئلا تصادف ساعة إجابة، فينبغي للمؤمن أن يتحرى الدعاء الطيب، وإذا غضب على أولاده يدعو لهم بالهداية والصلاح، لا يدعو عليهم، هذا هو الذي ينبغي له؛ يتحرى الخير، نعم. المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/15057/التحذير-من-الدعاء-على-الابناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_581/58108.mp3","categories":["الأدعية والأذكار","تربية الأولاد","نصائح وتوجيهات"]},{"id":16502,"question":"سماحة الشيخ: تتيح لنا هذه المستمعة بعض الأسئلة لو تكرمتم، جزاكم الله خيرًا.الشيخ: نعم.المقدم: بعض الأسر عندما ينشأ بينها شاب ملتزم، داعية إلى الله، ويلتزم بالسنة النبوية؛ تجد كثيرًا من الأسر تتذمر من هذا وتحاول أن تعيده على سيرتهم التي لم تكن مرضية، لعل لسماحتكم توجيه في هذا الباب؟ جزاكم الله خيرًا.","title":"حكم تذمر الأسرة عند التزام أبنائها","answer":"الجواب: هذا لا يجوز، الواجب على الأسرة أن تشجع على الخير، فإذا نشأ فيها شاب، والتزم بالحق، وحافظ على الصلوات، وترك الإسبال، وترك حلق لحيته الواجب مساعدته في هذا، وأن يشكر على هذا الخير العظيم، ويعان، ويرغب في الاستمرار والثبات. وهكذا الجارية إذا نشأت ملتزمة، محافظة على الصلاة، وعلى الحجاب، تشكر على هذا، وتشجع من أبيها وأمها وأخواتها، هذا هو الواجب على الجميع؛ لأن الله سبحانه يقول: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2] أما أنه يثبط، ويستهزأ به هذا منكر لا يجوز، وهكذا مع المرأة لا يجوز تثبيطها، ولا الاستهزاء بها إذا تحفظت، واحتجبت، وابتعدت عن أسباب الشر، وحافظت على الصلاة، واطمأنت فيها، وأدتها في أوقاتها، كل هذا يجب التشجيع عليه، والثناء على من فعله، وعدم تثبيطه، نسأل الله للجميع الهداية. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15264/حكم-تذمر-الاسرة-عند-التزام-ابناىها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_814/nour_81410.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":16505,"question":"سماحة الشيخ: تتيح لنا هذه المستمعة بعض الأسئلة لو تكرمتم، جزاكم الله خيرًا.الشيخ: نعم.المقدم: بعض الأسر عندما ينشأ بينها شاب ملتزم، داعية إلى الله، ويلتزم بالسنة النبوية؛ تجد كثيرًا من الأسر تتذمر من هذا وتحاول أن تعيده على سيرتهم التي لم تكن مرضية، لعل لسماحتكم توجيه في هذا الباب؟ جزاكم الله خيرًا.","title":"حكم تذمر الأسرة عند التزام أبنائها","answer":"الجواب: هذا لا يجوز، الواجب على الأسرة أن تشجع على الخير، فإذا نشأ فيها شاب، والتزم بالحق، وحافظ على الصلوات، وترك الإسبال، وترك حلق لحيته الواجب مساعدته في هذا، وأن يشكر على هذا الخير العظيم، ويعان، ويرغب في الاستمرار والثبات. وهكذا الجارية إذا نشأت ملتزمة، محافظة على الصلاة، وعلى الحجاب، تشكر على هذا، وتشجع من أبيها وأمها وأخواتها، هذا هو الواجب على الجميع؛ لأن الله سبحانه يقول: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2] أما أنه يثبط، ويستهزأ به هذا منكر لا يجوز، وهكذا مع المرأة لا يجوز تثبيطها، ولا الاستهزاء بها إذا تحفظت، واحتجبت، وابتعدت عن أسباب الشر، وحافظت على الصلاة، واطمأنت فيها، وأدتها في أوقاتها، كل هذا يجب التشجيع عليه، والثناء على من فعله، وعدم تثبيطه، نسأل الله للجميع الهداية. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15264/حكم-تذمر-الاسرة-عند-التزام-ابناىها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_814/nour_81410.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":16535,"question":"من أسئلة هذه السائلة، تقول: ما حكم ضرب الأطفال الذين دون سن العاشرة على أي أمر يفعلونه؟ وما توجيهكم بذلك مأجورين؟","title":"حكم ضرب الأطفال دون سن العاشرة","answer":"الجواب: للوالد والوالدة تأديب الأطفال إذا رأيا ذلك، ولو كان دون العشر، ولو كان دون السابعة، إذا رأى أن يؤدب ولده ذكرًا كان أو أنثى؛ لا بأس، لكن بالشيء الذي يناسبه، لا يضره، التأديب الخفيف ينفعه، ولا يضره، إذا كان يتعدى على إخوانه الصغار، إذا كان يعبث في البيت عبثًا يؤذي، أو ما أشبه ذلك؛ يؤدبه، الضربات الخفيفة، أو بالكلام الشديد الذي يردعه، أو بالضربات الخفيفة، أو منعه من بعض حاجاته التي يريدها حتى يتأدب، من الأم والأب، ومن أخيه الكبير إذا كان ما عنده أب ولا أم، أو من عمه، أو من خالته، على حسب حاله، يعني ممن يربيه ويقوم عليه، له أن يؤدبه، سواء كان أمًا، أو أبًا، أو خالًا، أو خالة، أو أخًا كبيرًا، على حسب الحال، فالذي يربيه، ويقوم عليه له أن يؤدبه بالشيء الذي لا يضره، شيئًا خفيفًا، لكن يحصل به النفع. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15259/حكم-ضرب-الاطفال-دون-سن-العاشرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_583/58311.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":17087,"question":"من أحد الإخوة المستمعين يقول من بور سودان، يقول: منذ أكثر من ثلاثة عشر عامًا طلقت زوجتي، ولي منها ولدان وبنتان، ويتم خصم نفقة أولادي منها بواسطة المحكمة، وقد قسمت المحكمة مرتبي مناصفة بيني وبين أولادي؛ لأنني متزوج من امرأة أخرى، ولي منها أطفال، أكبر أبنائي منها ذكر، وكان يقيم معي عند طلاقي منها، لم أتركه يصاحبها حتى يتربى تحت يدي، لكنها لم تتركه، وسعت خلفه حتى أخذته، وكانت النتيجة الفشل في الدراسة، والعمل أيضًا، وهو الآن عاطل، ويشكل عبئًا عليها، هل يجوز لي أن آخذ أولادي منها؟ جزاكم الله خيرًا.","title":"أخذ الأولاد من أمهم المطلقة يرجع إلى المحكمة","answer":"الجواب: هذا إلى المحكمة بارك الله فيك، تراجع المحكمة، وفيها البركة إن شاء الله.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15913/اخذ-الاولاد-من-امهم-المطلقة-يرجع-الى-المحكمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_831/nour_83106.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":17226,"question":"تقول أم سعد: يا شيخ -حفظكم الله- عندي أولاد لا يصلون، وقد نصحتهم كثيرًا، ولم يستجيبوا لنصحي، ماذا أفعل معهم؟ وهل آثم بتركهم؟","title":"كيفية التعامل مع الأولاد الذين لا يصلون","answer":"الجواب: الواجب نصيحتهم، وتأديبهم إذا استطعت أن تؤدبيهم، أو ترفعي أمرهم إلى الهيئة، أو إلى المحكمة؛ حتى يؤدبوا، لا يجوز السكوت عنهم، بل يجب العناية بهم، تجب العناية بهم، والحرص على إقامتهم الصلاة؛ لأن من تركها كفر، أمر الصلاة عظيم، فعليك أن تجتهدي في نصيحتهم، أو بضربهم إن استطعت، فإن لم تستطيعي، ارفعي شأنهم لولاة الأمور، للهيئة، إذا كان ببلدكم هيئة، أو للمحكمة، أو للأمير، حتى يعينوك عليهم؛ لأن السكوت عنهم لا يجوز.  الله -جل وعلا- يقول: يَا أَيُّهَا الَّذِينَ آمَنُوا قُوا أَنفُسَكُمْ وَأَهْلِيكُمْ نَارًا وَقُودُهَا النَّاسُ وَالْحِجَارَةُ [التحريم:6].. ويقول الله -جل وعلا-: وَأْمُرْ أَهْلَكَ بِالصَّلاةِ وَاصْطَبِرْ عَلَيْهَا [طه:132].. ويقول -جل وعلا-: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71] وترك الصلاة من أعظم المنكرات. فالواجب العناية بهم، والحرص عليهم، ووعظهم، وتذكيرهم، ونصيحتهم، وتأديبهم إذا استطعت، أو أبوهم، إن كان له أبٌ موجود، أو أخٌ كبير يؤدبهم، فإن لم تستطيعي؛ فارفعي أمرهم إلى الإمارة، أو الهيئة، أو المحكمة. نعم.  المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16052/كيفية-التعامل-مع-الاولاد-الذين-لا-يصلون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_591/59103.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":17358,"question":"نعود في بداية هذه الحلقة إلى رسالة الأخت المستمعة (ف. ح. م) المطيري، أختنا عرضنا بعض أسئلتها في حلقة مضت، وفي هذه الحلقة بقي لها عدد من الأسئلة في أحدها تقول: إن لي أخًا يبلغ من العمر عشر سنوات، يتكلم على أمي، ويتلفظ عليها بعبارات غير لائقة؛ لأنها تأمره بالصلاة، وطاعة الله، فأنا أضربه ضربًا شديدًا، وأحيانًا أضربه؛ لأنه لا يذاكر دروسه، أو لأنه يأخذ شيئًا دون أن تعلم به أمي، وأحيانًا أكويه بالنار، فهل أكون آثمة في فعلي هذا؟ جزاكم الله خيرًا.","title":"حكم ضرب الأخ لتركه الصلاة وعصيان أمه","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.. أما بعد.  فأنت جزاك الله خيرًا مأجورة على اجتهادك، وحرصك على صلاحه، وعلى تأدبه مع والدته، وعلى بره لها، ولا حرج عليك في تأديبه، وضربه حتى يستقيم، وحتى يقوم بما يلزم من جهة والدته. والحاصل: أنك مأجورة في ضربه حتى يصلي، وحتى يذاكر في دروسه، وحتى لا يتكلم على والدته بما لا ينبغي، كل هذا أنت مأجورة عليه، وإذا كان أبوه موجودًا فالواجب على أبيه أن يقوم بهذه المهمة، أو أخوه الكبير حتى يتساعد معك بذلك، وإذا كان أبوه يقوم بالواجب؛ كفى عنك. فالحاصل: أن الواجب على أبيه إن كان موجودًا، أو أخيه الكبير إن كان موجودًا أن يقوم بذلك، وإن قامت أمه بذلك فلا بأس، وإذا لم تقم به أمه، ولم يقم بذلك أحد غيرك فأنت مأجورة على ذلك، وجزاك الله خيرًا، لكن لا تكويه بالنار، أما الكي بالنار فلا يجوز. وإذا كان يأخذ شيئًا يسيرًا من المال لحاجة الأطفال فينبغي التسامح بهذا، أما الشيء الذي قد يضر الوالدة، أو قد يعوده السرقة فلا مانع من ضربك له ضربًا خفيفًا، لا تضربيه ضربًا خطيرًا لا في الصلاة، ولا في غيرها، ضربًا خفيفًا يؤلمه، ويردعه، ولكن ليس فيه خطر، بارك الله فيك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16193/حكم-ضرب-الاخ-لتركه-الصلاة-وعصيان-امه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_834/nour_83401.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":17669,"question":"سماحة الشيخ! بعض الأمهات هداهن الله، يغفلن عن تنبيه بناتهن إلى مثل هذه الأمور، ما هو توجيهكم للأمهات حيال هذا؟ جزاكم الله خيرًا.","title":"توجيه الأمهات بتعليم بناتهن أحكام العبادة","answer":"الجواب: الواجب على الأمهات تنبيه بناتهن، وهكذا الأخوات الكبيرات، تنبيه أخواتهن، وهكذا العمات، والخالات؛ التعاون على البر والتقوى، كل واحدة تنبه الصغيرة على ما يجب عليها من جهة الصوم في رمضان، من جهة عدم الصلاة في أيام الحيض، من جهة الطمأنينة في الصلاة، والخشوع فيها، في جميع الوجوه، كل واحدة تعلم أختها في الله، أختها، بنتها، بنت أخيها، بنت أختها، جيرانها، جلساءها، تلاميذها، عليها أن تعلم، توضح لهم ما قد يخفى عليهم في أمور الصلاة، أمور الصيام، أمور الزكاة، أمور الحج، أمور بر الوالدين، إلى غير ذلك، على كلٍ من الأخوات، والعمات، والخالات، والأمهات؛ التوجيه للبنات الشابات، والإرشاد لهن إلى ما قد يخفى عليهن من أمور الدين. نعم.\nالمقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16600/توجيه-الامهات-بتعليم-بناتهن-احكام-العبادة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_727/nour_72711.mp3","categories":["تربية الأولاد","نصائح وتوجيهات"]},{"id":17713,"question":"الدعاء على الأولاد بين فترة وأخرى، ما حكمه يا شيخ؟","title":"حكم الدعاء على الأولاد","answer":"الجواب: لا ينبغي الدعاء عليهم، لا تصادف ساعة إجابة، ينبغي للوالدة والوالد وغيرهم الحذر من الدعاء على الأولاد، الدعاء لهم بالخير، وعدم الدعاء عليهم بالشر، هذا هو الذي ينبغي، وهذا هو المشروع؛ الحذر من الدعاء عليهم، ولكن الدعاء لهم بالخير والصلاح والهداية.\nالمقدم: جزاكم الله خيرًا يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16665/حكم-الدعاء-على-الاولاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_595/59524.mp3","categories":["تربية الأولاد","الأدعية والأذكار"]},{"id":17742,"question":"تقول السائلة في آخر أسئلتها: للأم حقوق كثيرة فهل لها الحق بالقول بكلام جارح أو فاسق وشنيع تجاه بناتها، الله يعلم بطهرهن؟","title":"حق الآباء على الأبناء والعكس","answer":"الجواب: الواجب على الأولاد البر بالوالدين، وإحسان المعاشرة لهما، والرفق بهما؛ لأن حقهما عظيم؛ كما قال الله سبحانه: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ وَبِالْوَالِدَيْنِ إِحْسَانًا[الإسراء:23]، وقال سبحانه: أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ إِلَيَّ الْمَصِيرُ[لقمان:14]، وقال جل وعلا: وَوَصَّيْنَا الإِنسَانَ بِوَالِدَيْهِ إِحْسَانًا[الأحقاف:15] ولما سئل النبي عليه الصلاة والسلام قيل: «يا رسول الله! من أحق الناس بحسن الصحبة؟ قال: أمك، قال: ثم من؟ قال: أمك، قال: ثم من؟ قال: أمك، قال: ثم من؟ قال: أبوك»، وفي الرواية الأخرى: «يا رسول الله! من أبر؟ قال: أمك، قال: ثم من ؟ قال: أمك، قال: ثم من؟ قال: أمك، قال: ثم من؟ قال: أباك، ثم الأقرب فالأقرب»، فبرهما واجب، والإحسان إليهما، والرفق بهما، وحسن المعاشرة لهما، وطيب الكلام معهما؛ هذا واجب الأولاد.\nأما الوالدان فعليهما أن يتقيا الله في أولادهما، وأن يحسنا إلى الأولاد، وأن يجتهدا في تربيتهما التربية الصالحة، وأن لا يسيئا إلى أولادهم بغير حق، لا بالكلام، ولا بالفعال، يجب على الأم وعلى الوالد - الأب - أن يحفظ كل منهما لسانه عما يؤذي الأولاد من الشتم، والكلام السيئ بغير حق.\nعليهما حق، ولهما حق، فعليهما حق بأن يحسنا إلى أولادهما، ويربيان أولادهما التربية الشرعية، وعليهما أن يحذرا سبهما، أو وصفهما بشيء باطل؛ لأن هذا يسبب العداوة، والبغضاء، والقطيعة، فعلى كل من الصنفين أداء الواجب، على الأولاد أداء الحق الذي عليهم من البر، والصلة، والإحسان، وعلى الوالدين تقوى الله، وأن يحسنا إلى أولادهما، وأن يكفا الشر عنهما. نعم.\nالمقدم: أحسن الله إليكم، وجزاكم الله عنا وعن المسلمين خير الجزاء.","link":"https://binbaz.org.sa/fatwas/16714/حق-الاباء-على-الابناء-والعكس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_777/nour_77710.mp3","categories":["تربية الأولاد","نصائح وتوجيهات"]},{"id":17832,"question":"من أسئلة هذا السائل يقول: في كثير من البيوت أولاد بالغين، والآباء يذهبون إلى المسجد للصلوات، وهؤلاء الأولاد البالغين في الصلاة: إما نيام أو مشغولين، ولا يأمرونهم بالصلاة، فهل من كلمة لمثل هؤلاء سماحة الشيخ للآباء؟","title":"نصيحة للمتساهلين مع أبنائهم في أمر الصلاة","answer":"الجواب: هذا لا يجوز، بل الواجب على الآباء أن يأمروهم، على آبائهم وأمهاتهم وإخوانهم الكبار أن يأمروهم ويلزموهم بالصلاة، ويضربوهم -أيضًا- حتى يصلوا مع الناس في المساجد، يقول النبي ﷺ: مروا أولادكم بالصلاة لسبع، واضربوهم عليها لعشر فإذا كان فوق العشر أشد وأشد، فالواجب على الآباء أن يأمروهم وأن يحرضوهم وأن يعاقبوهم أيضًا، وهكذا إخوتهم الكبار. نعم.","link":"https://binbaz.org.sa/fatwas/16824/نصيحة-للمتساهلين-مع-ابناىهم-في-امر-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_597/59729.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":18014,"question":"المستمع إبراهيم حسين من ضياء بعث يسأل ويقول: ولدي تارك للصلاة، قلت له: إذا لم تصل فحرام علي أن أحادثك، لكني لم أصبر وحادثته، فماذا علي؟","title":"كيفية تعامل الأب مع ابنه التارك للصلاة","answer":"الجواب: يجب عليك أن تنكر عليه، وأن تؤدبه على ذلك بالضرب حتى يصلي، وعليك أن تهجره أيضًا؛ لأنه مستحق لذلك والصلاة عمود الإسلام من تركها كفر نسأل الله العافية، لقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة خرجه مسلم في صحيحه، وقوله ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر خرجه الإمام أحمد وأهل السنن بإسناد صحيح، في أحاديث أخرى تدل على كفر تارك الصلاة. فالواجب عليك الإنكار عليه والتشديد عليه في ذلك حتى يصلي، وهجره من أهم المهمات إذا لم تنفع فيه النصيحة، وإذا استطعت تأديبه بالضرب فلك أن تؤدبه بل عليك أن تؤدبه، فإذا كان الصغير يضرب عليها إذا بلغ عشرًا فالكبير يضرب أشد إذا تركها، ولك أن ترفع أمره إلى ولاة الأمور حتى يستتاب فإن تاب وإلا قتل كافرًا، لكن مهما أمكن أن تستر عليه وأن تنصحه حتى يستقيم قبل أن يرفع إلى ولي الأمر فلعل الله يهديه بأسبابك، ولك أن تعمل ما تستطيع من الأسباب من هجر وضرب وغير ذلك من الأسباب التي تراها مجدية ونافعة في طلب هدايته، نسأل الله أن يهديه. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17053/كيفية-تعامل-الاب-مع-ابنه-التارك-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_850/nour_85006.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":18131,"question":"الحاج علي الريشي من ليبيا وأخونا فيصل بن عبد العزيز أحمد الهندي، يسألون سماحة الشيخ عن تفضيل بعض الأبناء عن بعض، لعل رسالة الأخ من ليبيا توضح بعض الشيء فيقول: أسأل عن قضية لي: وهي أن لي ثلاثة أبناء منهم اثنان لهما مسكنان، أما الثالث وهو الأصغر عنده قطعة أرض غير مبنية، فالأول قمت ببناء منزله على نفقتي؛ لأنه عاجز، وبه مرض الصرع عافاكم الله، ولا يستطيع عمله بنفسه، أما الأوسط فقد بنى منزله بقرض من أحد المصارف، وأما الأصغر فلم يتمكن من البناء في الوقت الحالي، ولي منزل باسمي كبير قررت أن أتنازل عنه لبناتي الأربعة ووالدتهن، علمًا بأنهن جميعًا متزوجات، ولكن قد يحتجن يومًا للمنزل، فهل يحق لابني الصغير نصيب في المنزل هذا، دلوني حتى ألاقي وجه ربي نظيفًا؟ جزاكم الله خيرًا.","title":"وجوب العدل بين الأولاد في العطية","answer":"الجواب: الواجب عليك أن تعدل بين أولادك ذكورهم وإناثهم، وليس لك أن تخص البنات بشيء سواء كن متزوجات أو غير متزوجات لا بالبيت ولا بغيره، لقول الرسول ﷺ: اتقوا لله واعدلوا بين أولادكم، فعليك أن تعدل بينهم ذكورهم وإناثهم إلا أن يسمح بعضهم فالذي يسمح يسقط حقه، إذا سمح بعضهم سقط حقه، وإذا سمح الأولاد الثلاثة بالبيت للبنات سقط حقهم والحمد لله. أما أن تخص أحدًا بشيء، فليس لك أن تخصه بشيء، لقوله عليه الصلاة والسلام: اتقوا الله واعدلوا بين أولادكم، فهم في الذمة، وهم في الحق سواء، فعليك أن تعدل بينهم أو تترك إعطاءهم، أما أن تعطي البنات وتدع الذكور أو تزيد هذا على هذا فليس لك ذلك، بل عليك أن تسوي بينهم كالميراث للذكر مثل حظ الأنثيين، هذا هو الواجب عليك، إلا إذا سمح المكلف منهم الرشيد سمح عن حقه، فلا بأس بذلك. نعم.","link":"https://binbaz.org.sa/fatwas/17176/وجوب-العدل-بين-الاولاد-في-العطية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_852/nour_85204.mp3","categories":["تربية الأولاد","الهبة والعطية"]},{"id":18137,"question":"السائل من الكويت يقول: كيف تكون المعاملة الصحيحة مع الأبناء حتى يكونون ملتزمين بأمور دينهم الحنيف؟فهل علي أن أجبرهم على الذهاب إلى المسجد في كل فرض؟ علمًا بأنهم في كثير من الفروض يصلونها في المسجد إلا أن النوم في بعض الأحيان يأخذهم، وإنهم في بعض الأوقات يؤخرون الصلاة عن وقتها، بعضهم وصل إلى سن البلوغ.وكيف أحببهم بالدين الإسلامي الصحيح، وبالصحبة الصالحة؟ وجهونا سماحة الشيخ عبد العزيز.","title":"الوسائل المعينة على التربية الصحيحة للأبناء","answer":"الجواب: الواجب عليك أن تأمرهم بالصلاة، وأن تلزمهم بذلك حتى يصلوا مع الناس، ولا يصلوا في البيت، بل عليهم أن يصلوا مع الناس، يقول النبي ﷺ: مروا أبناءكم بالصلاة لسبع، واضربوهم عليها لعشر، وفرقوا بينهم في المضاجع فكيف إذا بلغ الحلم؟ الأمر أعظم. فالمقصود أن الواجب عليك أن تأمرهم وأن تلزمهم بالصلاة في الجماعة، وأن تؤدب من تخلف، ولا تضعف في هذا، وعليك أن تنصحهم، وتعظهم، وتذكرهم بالقرآن والحديث، وتحثهم على صحبة الأخيار الطيبين؛ حتى يساعدوك في هذا، ولا تغفل عن هذا الشيء، ولا تتساهل فالأمر عظيم، وهم في ذمتك. نعم.","link":"https://binbaz.org.sa/fatwas/17183/الوساىل-المعينة-على-التربية-الصحيحة-للابناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_781/nour_78115.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":18148,"question":"سماحة الشيخ! تساهل كثير من الأسر في أبنائهم، وهم الحقيقة صغار، ثم يصعب عليهم في الكبر، هل من توجيه؟","title":"توجيه لمن يتساهل في تربية أبنائه","answer":"الجواب: هذا من المصائب العظيمة، التساهل من المصائب العظيمة، والواجب على الأب والأم والإخوة أن لا يتساهلوا في هذا، بل عليهم أن يجتهدوا في توجيه الأبناء والشباب إلى الصلاة، وإلى كل خير، وتحذيرهم مما حرم الله من السب والشتم والعقوق وغيرها من الفواحش والتدخين، وشرب المسكر وغير هذا من المنكرات. ومن أهم شيء بل أهم شيء بعد الشهادتين الصلاة، فعليهم أن يلزموا أولادهم بالصلاة، ويضربوا من تخلف عنها إذا كان بلغ عشرًا فأكثر، هذا هو الواجب على الآباء والأمهات، والإخوة الكبار مع الصغار، هذا من التعاون على البر والتقوى، وقد قال الله سبحانه: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ[التوبة:71]، وقال النبي ﷺ: من رأى منكم منكرًا فليغيره بيده، فإن لم يستطع فبلسانه، فإن لم يستطع فبقلبه، وذلك أضعف الإيمان. والوالد مأمور بأن يؤدب أولاده، بالضرب إذا بلغوا عشرًا فأكثر، حتى يستقيموا حتى يصلوا مع الناس.نعم. المقدم: أحسن الله إليكم سماحة الشيخ، وبارك فيكم على هذا التوجيه الطيب المبارك.","link":"https://binbaz.org.sa/fatwas/17188/توجيه-لمن-يتساهل-في-تربية-ابناىه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_781/nour_78116.mp3","categories":["تربية الأولاد","نصائح وتوجيهات","الهبة والعطية","فتاوى متنوعة"]},{"id":18366,"question":"فضيلة الشيخ يقول هذا السائل: كيف يكون تربية الأولاد؟ وكيف يتم تعليمهم على الصلوات إذا كانوا قد نشؤوا نشأة غير صالحة؟","title":"وجوب المجاهدة والصبر في تربية الأولاد","answer":"الجواب: بالمجاهدة يجاهدهم والدهم وأخوهم الأكبر حتى يستقيموا على طاعة الله، يجاهدوهم بالكلام الطيب والتأديب حتى يستقيموا على الصلاة وعلى الأخلاق الطيبة، لابد من مجاهدة وصبر، يقول جل وعلا: وَالَّذِينَ جَاهَدُوا فِينَا لَنَهْدِيَنَّهُمْ سُبُلَنَا [العنكبوت:69]، ويقول جل وعلا: يَا أَيُّهَا الَّذِينَ آمَنُوا قُوا أَنفُسَكُمْ وَأَهْلِيكُمْ نَارًا [التحريم:6]، ويقول النبي ﷺ: كلكم راعي وكلكم مسئول عن رعيته، فالإمام راع ومسئول عن رعيته، والرجل راع في أهل بيته ومسئول عن رعيته لابد من الصبر. المقدم: بارك الله فيكم ونفع الله بعلمكم.","link":"https://binbaz.org.sa/fatwas/17431/وجوب-المجاهدة-والصبر-في-تربية-الاولاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_913/nour_91327.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":18872,"question":"رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات، تقول: أم ياسر من السعودية، أختنا تقول: إني أنجبت بنتين معوقتين، وهما أختان من الأب والأم، البنت الأولى عمرها ثلاث عشرة سنة، وهي تسمع وترى، لكنها لا تعرف أن تتكلم، أو أن تنطق اسمها، ولا تعرف حتى الليل من النهار، ودرست ست سنوات في المعهد الفكري في جدة، ولم تستفد شيئًا، ولا حتى حرفًا واحدًا من القرآن الكريم، فبماذا تنصحوني يا فضيلة الشيخ، ولا سيما في أمر الصلاة؛ ذلك أنها لا تعرف شيئًا عنها، وإنني احترت معها، وأنا أعلمها، هل علي إثم إذا تركتها؟أرجو إرشادي، جزاكم الله خيرًا.","title":"كيفية تعليم المعاق والأصم الصلاة","answer":"الجواب: إذا كانت تعقل بالإشارة؛ فعلموها بالإشارة كيف تصلي وكيف تطهر، وإذا كانت لا عقل لها؛ فالحرج منتفي حينئذٍ، ولا تكليف عليها حينئذٍ؛ لقول النبي ﷺ في الحديث الصحيح: رفع القلم عن ثلاثة: عن النائم حتى يستيقظ، وعن الصغير حتى يبلغ، وعن المعتوه حتى يفيق فهي الآن بين الأمرين: إما أن تكون تعقل؛ فعلموها ولو بالإشارة، كيف تصلي، كيف تتوضأ، كيف تستنجي، علموها، فإذا تعلمت، كفى والحمد لله، وهي تصلي بقلبها ولو لم تنطق: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] وأحسنوا إليها، وأبشروا بالخير، وارحموها يرحمكم الله. أما إن كانت لا تعقل، ولا تفهم الإشارة، ولا تستفيد؛ فليس عليكم شيء، والتكليف عنها مرفوع، كالمجنون ونحوه، نسأل الله السلامة، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18036/كيفية-تعليم-المعاق-والاصم-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_880/nour_88008.mp3","categories":["تربية الأولاد","العالم والمتعلم"]},{"id":19016,"question":"إحدى الأخوات المستمعات من الرياض تقول: المرسلة أم عبد الله لها قضية تقول فيها: رجل قارب من العمر الثلاثين عامًا، ويصلي في المنزل غالبًا إلا أنه يحضر الجماعة في بعض الأوقات وفي الجمعة، ولكن لا يبدو عليه الحرص على ملازمة الجماعة، ووالدته تلح عليه في لزوم الجماعة، وهناك من اقترح عليها أن تظهر غضبها عليه، وألا تجالسه لعله يرجع، ولكنها تخاف عليه وتقول: أنصحه..أريد توجيهًا مفصلًا لهذا الرجل حول أدلة وجوب الجماعة، وما ينبغي للمسلم من طاعة الله وشكره على ما أنعم على الإنسان من نعم صالحة، ومن نعمة الصحة والشباب والعافية وسعة الرزق ولله الحمد.وما هو الحكم الشرعي في مجالسته ومؤاكلته والحالة هذه؟ ونصيحة أخرى نرجو أن تتفضلوا بتوجيهها للأم وتوصيتها بأي أسلوب تستعمله مع هذا الشاب لعله أن يرجع.","title":"كيفية التعامل مع الابن المتهاون بصلاة الجماعة","answer":"الجواب: لا ريب أن الصلاة في الجماعة مع المسلمين في بيوت الله من أهم الفرائض، وهي شعار الإسلام، فالواجب على كل مكلف أن يعتني بذلك وأن يبادر ويسارع إلى إقامة الصلاة في الجماعة مع المسلمين، وأن يتباعد عن مشابهة أهل النفاق، قال ابن مسعود : «من سره أن يلقى الله غدًا مسلمًا، فليحافظ على هؤلاء الصلوات الخمس حيث ينادى بهن؛ فإن الله شرع لنبيكم الهدى، وإنهن من سنن الهدى، ولو أنكم صليتم في بيوتكم كما يصلي هذا المتخلف في بيته لتركتم سنة نبيكم، ولو تركتم سنة نبيكم لضللتم -وفي لفظ: لكفرتم- ولقد رأيتنا وما يتخلف عنها -يعني: الصلاة في الجماعة- إلا منافق معلوم النفاق، ولقد كان الرجل -يعني: من الصحابة- يؤتى به يهادى بين الرجلين -يعني: مريض أو كبير السن- حتى يقام في الصف» من شدة حرصهم على أداء الصلاة في الجماعة . ويقول النبي ﷺ: من سمع النداء فلم يأت فلا صلاة له إلا من عذر قيل لابن عباس: ما هو العذر؟ قال: خوف أو مرض يعني: خوف إن خرج من بيته أن يقتل أو يسجن أو يضرب؛ لأن البلاد غير آمنة أو مرض يمنعه من ذلك. وفي الصحيح عن أبي هريرة  عن النبي ﷺ: أنه أتاه رجل أعمى فقال: يا رسول الله! ليس لي قائد يلائمني إلى المسجد، فهل لي من رخصة أن أصلي في بيتي؟ فقال له النبي عليه الصلاة والسلام: هل تسمع النداء بالصلاة؟ قال: نعم، قال: فأجب رواه مسلم في صحيحه. وفي رواية أخرى في غير مسلم: لا أجد لك رخصة فأخبر ﷺ أنه لا يجد رخصة لأعمى ليس له قائد يلائمه، أن يصلي في بيته بل عليه أن يصلي في المسجد مع الناس، فإذا كان الأعمى الذي ليس له قائد يلائمه، ليس له رخصة فكيف بحال الصحيح المعافى البصير ؟ الأمر أعظم. وقد هم ﷺ أن يحرق على المتخلفين بيوتهم كما في الصحيحين عنه عليه الصلاة والسلام أنه قال: لقد هممت أن آمر بالصلاة فتقام ثم آمر رجلاً فيؤم الناس، ثم انطلق برجال معهم حزم من حطب إلى رجال لا يشهدون الصلاة -يعني: في المساجد- فأحرق عليهم بيوتهم هكذا يقول عليه الصلاة والسلام، وفي رواية لأحمد: لولا ما في البيوت من النساء والذرية لحرقتها عليهم. فالمقصود أن الصلاة في الجماعة في بيوت الله أمر مفترض، وأمر لازم ومن شعار المسلمين، من شعار أهل الحق، والتخلف عن ذلك في البيوت من شعار المنافقين، فلا ينبغي للمسلم أن يرضى بمشابهة أهل النفاق الذين قال الله فيهم سبحانه: إِنَّ الْمُنَافِقِينَ يُخَادِعُونَ اللَّهَ وَهُوَ خَادِعُهُمْ وَإِذَا قَامُوا إِلَى الصَّلاةِ قَامُوا كُسَالَى يُرَاءُونَ النَّاسَ وَلا يَذْكُرُونَ اللَّهَ إِلَّا قَلِيلًا  ۝  مُذَبْذَبِينَ بَيْنَ ذَلِكَ لا إِلَى هَؤُلاءِ وَلا إِلَى هَؤُلاءِ [النساء:142-143] ذكرهم سبحانه بخمس صفات المنافقين خمس: إحداها: أنهم يخادعون الله والذين آمنوا، ما عندهم نصيحة ولا أمانة، عندهم المكر والخديعة، والكذب في معاملاتهم. والثانية: أنهم إذا قاموا إلى الصلاة قاموا كسالى، ما عندهم نشاط لعدم إيمانهم، إنما هو رياء. الثالثة: أنهم لا يذكرون الله إلا قليلا، ذكرهم لله قليل تغلب عليهم الغفلة. والرابعة: أنهم أهل رياء يراءون الناس بأعمالهم ليس عندهم إخلاص، الغالب عليهم في أعمالهم الرياء والسمعة، وطلب المحمدة، وليس عندهم إخلاص لله . والخامسة: أنهم مذبذبون ليس عندهم ثبات، وليس عندهم هدف مستقيم، بل هم تارة مع المؤمنين وتارة مع الكافرين، ليس عندهم قاعدة ولا دين ثابت ولا إيمان صادق، بل إن ظهر المؤمنون ونصروا صاروا مع المؤمنين، وإن ظهر الكفار على المسلمين صاروا مع الكفار، هذه حال المنافقين. فكيف يرضى المؤمن أن يتشبه بهم في التخلف عن الصلاة في الجماعة؟ والوالدة التي نصحت ولدها في أن يصلي مع الجماعة قد أحسنت، وهذا هو الواجب عليها، والواجب عليها أن تستمر في ذلك، وأن تنصحه دائمًا وتهجره إذا امتنع ولم يمتثل، تستعين عليه بالله، ثم بمن ترى من أقاربه كأبيه وأخيه الكبير وعمه.. ونحو ذلك إذا كان له أقارب صالحين، إذا كان له أقارب صالحون تستعين بالله ثم بهم. والحاصل أن من يعرف بالتخلف عن الجماعة يستحق الهجر، ويستحق التأديب من ولاة الأمور حتى يستقيم، وحتى يحافظ على الصلاة في الجماعة. ثم من أعظم المصائب: أن التخلف عنها في الجماعة من أعظم الأسباب في تركها بالكلية نعوذ بالله؛ لأن هذا المرض الذي في القلب الذي أوجب له التخلف سيجره في الغالب إلى الترك وعدم المبالاة، فتارة يصلي وتارة لا يصلي، وقد يحمله على الرياء، إن رأى من يستحي منهم صلى وإن خلا له الجو ترك، هذه حال المنافقين نعوذ بالله. فالواجب الحذر، والواجب على الوالدة وعلى أقارب الرجل، وعلى أصدقائه أن ينصحوه، وأن يعينوا والدته عليه، وأن يهجروه إذا استمر في باطله وتخلفه، نسأل الله الهداية للجميع. المقدم: جزاكم الله خيرًا، تسأل في نهاية السؤال سماحة الشيخ عن مجالسته ومؤاكلته، وترجو منكم التوجيه جزاكم الله خيرًا. الشيخ: تعمل ما هو الأصلح، إن رأت أن في مؤاكلته ومجالسته ما يعين على أدائه الواجب والحفاظ على الصلاة فعلت ذلك واجتهدت، فإن لم ينفع ذلك ولم تؤثر فيه هجرته، فلا تجالسه ولا تؤاكله واستحق منها الغضب، أن تغضب عليه، وأن تستعين بمن ترى من أقاربه وأهل الخير في هدايته أو ردعه. نعم. المقدم: جزاكم الله خيرًا، هذا وهو يحضر بعض الجماعات ويحضر الجمعة؟ الشيخ: ولو، نعم نسأل الله السلامة، لابد من الحضور للجميع والعناية بالجميع، نسأل الله السلامة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18183/كيفية-التعامل-مع-الابن-المتهاون-بصلاة-الجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_927/nour_92702.mp3","categories":["تربية الأولاد","الحكم على الأحاديث","صلاة الجماعة"]},{"id":19230,"question":"يسأل أخونا أيضًا ويقول: لي أربع بنات وثلاثة أولاد، أولادي الكبار بنيت لكل منهم منزلًا خاصًا به، وابني الصغير لم أستطع أن أبني له منزلًا، وعندي منزل قديم سبق وأن منحته لزوجتي وبناتها الأربع في وصية رسمية، فهل للابن الأصغر حق شرعي في المنزل مع أمه وأخواته أم لا؟ أفيدوني جزاكم الله خيرًا.","title":"وجوب العدل بين الأولاد الكبار والصغار في العطية","answer":"الجواب: الواجب عليك يا أخي التعديل بين أولادك، الذكور والإناث؛ لقول النبي ﷺ: اتقوا الله واعدلوا بين أولادكم، فإذا كنت حين بنيت لأبنائك الكبار منازل قد وجد لك الولد الصغير والبنات وجب عليك التعديل، أما إن كنت بنيت لهم وأعطيتهم قبل وجود البنات وقبل وجود الابن الصغير فلا شيء عليك؛ لأنك ما عندك أولاد ذاك الوقت غيرهم، أما إن كان إعطاؤك لهم المنازل بعد وجود الابن الصغير، وبعد وجود البنات فالواجب التعديل، فإما أن تعطيهم مثل إخوانهم، لِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ [النساء:11]، وإما أن ترجع في المنازل التي أعطيتها إخوانهم وتجعلها للجميع، بين الجميع أو لنفسك، وتبقى إرثًا لهم بعدك. وأما أن تخص أولئك بالمنازل أو البنات، هذا لا يجوز، بل عليك أن تعدل، وإذا أعطيت الأم وهي الزوجة شيئًا من مالك في صحتك فلا بأس، تخصها بشيء، لا بأس أن تخصها بشيء، وأما الأولاد ذكورهم وإناثهم فلا بد من التعديل بينهم، لِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ [النساء:11]، في الأراضي وفي النقود وفي غير ذلك، هكذا أمر النبي ﷺ قال: اتقوا الله واعدلوا بين أولادكم. وليس لك أن توصي للزوجة ولا للبنات ولا غيرهم من الورثة وصية؛ لأن الورثة ليس لهم وصية، يقول النبي ﷺ: إن الله قد أعطى كل ذي حق حقه فلا وصية لوارث، ولكن لا مانع أن تعطي الزوجة في صحتك شيئًا من مالك في مقابل خدمتها ومعاشرتها الطيبة. وإذا كان لك زوجة أخرى تعطيها مثلها، وأما البنات وإخوتهم فلا بد من التعديل بينهم في المنازل وغيرها، إلا إذا سمحوا، إذا سمحت البنات عن إخوانهم وقالوا: ما نرغب في شيء وأنت مسامح، فلا بأس، وهكذا الابن الصغير إذا بلغ الحلم وسمح إذا كان رشيدًا وسمح، وقال: أنا سامح عن إخواني ولا لزوم للتعديل، فلا بأس الحق لهم، فإذا سمحوا سقط الوجوب الذي عليك. أما إن لم يسمحوا أو سمحوا سماحًا يخافون منك، ما هو بسماح عن رضا وعن طيب نفس ، لكن لأنك توعدهم أو يخشون من أمر يضرهم منك فالسماح الذي ليس له سند واضح، بل حصل عن خشية وخوف لا يعتبر، لا بد أن يكون سماح واضح من دون خوف منك ولا وعيد منك بل عن طيب نفس من أنفسهم، فلا بأس بذلك. نعم. المقدم: جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/18403/وجوب-العدل-بين-الاولاد-الكبار-والصغار-في-العطية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_889/nour_88902.mp3","categories":["تربية الأولاد","الهبة والعطية"]},{"id":19521,"question":"هل من توجيه كريم للآباء والأمهات في توجيه أولادهم في السن المبكرة لتعويدهم على الأمور الشرعية؟","title":"نصيحة للآباء والأمهات بتوجيه الأبناء في الأمور الشرعية","answer":"الجواب: نعم، الواجب على الآباء والأمهات تعليم الأولاد وتوجيههم إلى الخير، تعليم البنين والبنات، وإرشادهم فيما يتعلق بالصوم والصلاة، وما يتعلق بحيض المرأة وغير ذلك، يجب على الأب والأم إرشاد الأولاد يَا أَيُّهَا الَّذِينَ آمَنُوا قُوا أَنفُسَكُمْ وَأَهْلِيكُمْ نَارًا [التحريم:6]، الله جل وعلا أمرهم بهذا.\nوقال ﷺ: كلكم راع وكلكم مسئول عن رعيته، فالرجل راع في أهل بيته ومسئول عن رعيته، والمرأة راعية في بيت زوجها ومسئولة عن رعيتها كلهم راع. فالواجب على الأب أن يعتني بالأولاد وأن يرشدهم، وهكذا الأم، كلهم مسئولون فَوَرَبِّكَ لَنَسْأَلَنَّهُمْ أَجْمَعِينَ  ۝ عَمَّا كَانُوا يَعْمَلُونَ [الحجر:92، 93]. فالأب يعلم أولاده الذكور والإناث، والأم كذلك حتى ينشئوا على خير وعلى هدى وعلى بصيرة.\nنسأل الله للجميع الهداية. المقدم: اللهم آمين، أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/18768/نصيحة-للاباء-والامهات-بتوجيه-الابناء-في-الامور-الشرعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_939/nour_93934.mp3","categories":["تربية الأولاد","نصائح وتوجيهات","الهبة والعطية","فتاوى متنوعة"]},{"id":19567,"question":"بالنسبة - يقول السائل - عن صلاة الأولاد دون العاشرة: هل على الوالدين إثم إذا لم يلتزموا في هذه الصلاة؟","title":"إذا لم يلتزم الأولاد الذين دون العشر بالصلاة هل يأثم الوالدان؟","answer":"الجواب: يأمرونهم بها فقط، ولا إثم عليهم، فإذا بلغوا عشرًا وجب أمرهم، وتأديبهم حتى يصلوا، أما دون العشر ما فوق السابعة ودون العشر فالمشروع الأمر فقط، إذا بلغ سبعًا يؤمر ولا يضرب، فإذا بلغ عشرًا فأكثر يضرب عليها. نعم. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/18830/اذا-لم-يلتزم-الاولاد-الذين-دون-العشر-بالصلاة-هل-ياثم-الوالدان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_947/nour_94719.mp3","categories":["تربية الأولاد","حكم الصلاة وأهميتها"]}]
